window.RANKING=[{"law":"lbrl","art":"46","t":"Artículo 46.","sub":"Sesiones del Pleno — Mensual (+20.000), bimensual (5.001–20.000), trimestral (hasta 5.000); extraordinaria 1/4, máx. 3 al año, 15 días hábiles; convocatoria 2 días hábiles; quórum 1/3, mín. 3.","mat":"Sesiones del Pleno","cl":"Mensual (+20.000), bimensual (5.001–20.000), trimestral (hasta 5.000); extraordinaria 1/4, máx. 3 al año, 15 días hábiles; convocatoria 2 días hábiles; quórum 1/3, mín. 3.","w":27.0,"n":14,"ex":8,"alc":2,"pr":"A","note":"Plenos ordinarios «1-2-3»: >20.000 hab. y Diputaciones cada MES; 5.001-20.000 cada DOS meses; ≤5.000 cada TRES. Extraordinaria: Presidente o 1/4 del número legal (máx. 3 solicitudes por concejal y año), en 15 días hábiles. Convocatoria con 2 días HÁBILES. Quórum: 1/3 del número legal, nunca menos de 3, con Presidente y Secretario. Votación ordinaria por regla general."},{"law":"haciendalocal","art":"191","t":"Artículo 191. Cierre y liquidación del presupuesto.","sub":"Liquidación y remanente — 31/12; remanente de tesorería; confección antes del 1 de marzo.","mat":"Liquidación y remanente","cl":"31/12; remanente de tesorería; confección antes del 1 de marzo.","w":15.0,"n":8,"ex":7,"alc":1,"pr":"A","note":"Liquidación: «31-D cierra, 1-M confecciona, el PRESIDENTE aprueba». Se liquida a 31 de diciembre, se confecciona antes del 1 de MARZO y la aprueba el Presidente previo informe de Intervención (NO el Pleno, que solo recibe cuenta). Remanente = pendientes de cobro + fondos líquidos − pendientes de pago."},{"law":"lbrl","art":"49","t":"Artículo 49.","sub":"Ordenanzas — Inicial Pleno + 30 días + definitiva Pleno; sin reclamaciones, automática.","mat":"Ordenanzas","cl":"Inicial Pleno + 30 días + definitiva Pleno; sin reclamaciones, automática.","w":10.0,"n":5,"ex":5,"alc":1,"pr":"A","note":"Ordenanzas «I-30-D»: aprobación Inicial por el Pleno, información pública 30 días MÍNIMO, aprobación Definitiva por el Pleno. Si no hay reclamaciones, el acuerdo provisional pasa a definitivo automáticamente. Entran en vigor tras publicar el texto íntegro en el BOP y transcurrir 15 días hábiles (art. 70.2 y 65.2)."},{"law":"haciendalocal","art":"177","t":"Artículo 177. Créditos extraordinarios y suplementos de crédito.","sub":"Crédito extraordinario y suplemento — Informe de Intervención; Pleno; mismos trámites que el presupuesto.","mat":"Crédito extraordinario y suplemento","cl":"Informe de Intervención; Pleno; mismos trámites que el presupuesto.","w":8.0,"n":4,"ex":4,"alc":1,"pr":"A","note":"Crédito extraordinario (NO existe crédito) y suplemento (crédito INSUFICIENTE): lo incoa el Presidente, informa la Intervención y aprueba el PLENO con los trámites del presupuesto."},{"law":"ce","art":"113","t":"Artículo 113.","sub":"Moción de censura — 1/10 de diputados, candidato, mayoría absoluta, 5 días, 2 días para alternativas.","mat":"Moción de censura","cl":"1/10 de diputados, candidato, mayoría absoluta, 5 días, 2 días para alternativas.","w":7.0,"n":2,"ex":2,"alc":1,"pr":"A","note":"Moción de censura «1/10-MA-5-2-mismo periodo»: la propone 1/10 de los Diputados con un candidato; se aprueba por MAYORÍA ABSOLUTA del Congreso; no se vota hasta pasados 5 días, y en los 2 primeros caben mociones alternativas; si fracasa, sus firmantes no pueden presentar otra en el mismo período de sesiones."},{"law":"lbrl","art":"81","t":"Artículo 81.","sub":"Alteración de calificación — Automática: planes y adscripción de más de 25 años.","mat":"Alteración de calificación","cl":"Automática: planes y adscripción de más de 25 años.","w":7.0,"n":2,"ex":2,"alc":1,"pr":"A","note":"Cambio de calificación de bienes: requiere EXPEDIENTE de oportunidad y legalidad. Es AUTOMÁTICO en dos casos: aprobación definitiva de planes urbanísticos o de proyectos de obras y servicios, y adscripción de un bien patrimonial más de 25 AÑOS a un uso o servicio público."},{"law":"haciendalocal","art":"104","t":"Artículo 104. Naturaleza y hecho imponible. Supuestos de no sujeción.","sub":"Plusvalía (IIVTNU) — Transmisión de propiedad o derecho real de goce limitativo del dominio.","mat":"Plusvalía (IIVTNU)","cl":"Transmisión de propiedad o derecho real de goce limitativo del dominio.","w":7.0,"n":2,"ex":2,"alc":1,"pr":"A","note":"Plusvalía (IIVTNU): impuesto DIRECTO; grava el incremento de valor de terrenos URBANOS por transmisión de la propiedad o de derechos reales de GOCE limitativos del dominio. No sujetos: los terrenos rústicos y las aportaciones o adjudicaciones entre cónyuges a la sociedad conyugal."},{"law":"haciendalocal","art":"170","t":"Artículo 170. Reclamación administrativa: legitimación activa y causas.","sub":"Reclamaciones — Interesados (a–c) y causas tasadas (a–c).","mat":"Reclamaciones","cl":"Interesados (a–c) y causas tasadas (a–c).","w":7.0,"n":2,"ex":2,"alc":1,"pr":"A","note":"Reclamaciones contra el presupuesto «TRA-OMI-INSU»: solo por TRAmitación incorrecta, OMIsión de créditos para obligaciones exigibles o INSUficiencia manifiesta de ingresos o gastos. Interesados: habitantes, directamente afectados y entidades representativas."},{"law":"ce","art":"87","t":"Artículo 87.","sub":"Iniciativa legislativa — Gobierno, Congreso, Senado; Asambleas CCAA (máx. 3 miembros); popular: 500.000 firmas.","mat":"Iniciativa legislativa","cl":"Gobierno, Congreso, Senado; Asambleas CCAA (máx. 3 miembros); popular: 500.000 firmas.","w":6.0,"n":2,"ex":2,"alc":1,"pr":"A","note":"Iniciativa legislativa «GO-CON-SEN + CCAA + 500.000»: Gobierno, Congreso y Senado. Las Asambleas autonómicas piden un proyecto al Gobierno o remiten una proposición (con un máximo de 3 defensores). La iniciativa popular exige 500.000 firmas y NO cabe en «OTIG»: Orgánica, Tributaria, Internacional y Gracia."},{"law":"haciendalocal","art":"102","t":"Artículo 102. Base imponible, cuota y devengo.","sub":"ICIO: base y devengo — Coste de ejecución material; máx. 4 %; devengo al iniciar la obra.","mat":"ICIO: base y devengo","cl":"Coste de ejecución material; máx. 4 %; devengo al iniciar la obra.","w":6.0,"n":2,"ex":2,"alc":1,"pr":"A","note":"ICIO «CRE-4-INI»: la base es el Coste Real y Efectivo, es decir, la ejecución material (sin IVA, tasas, honorarios ni beneficio industrial); tipo máximo del 4 %; se devenga al INICIARSE la obra, aunque no haya licencia."},{"law":"lbrl","art":"82","t":"Artículo 82.","sub":"Prerrogativas sobre bienes — Recuperación: dominio público en cualquier momento; patrimoniales 1 año. Deslinde.","mat":"Prerrogativas sobre bienes","cl":"Recuperación: dominio público en cualquier momento; patrimoniales 1 año. Deslinde.","w":5.0,"n":1,"ex":1,"alc":1,"pr":"A","note":"Prerrogativas sobre bienes «RE-DE»: REcuperar de oficio (dominio público: en cualquier momento; patrimoniales: en 1 AÑO) y DEslindar."},{"law":"lbrl","art":"85 ter","t":"Artículo 85 ter.","sub":"Sociedades mercantiles — Derecho privado salvo presupuestaria, contable, control financiero, de eficacia y contratación.","mat":"Sociedades mercantiles","cl":"Derecho privado salvo presupuestaria, contable, control financiero, de eficacia y contratación.","w":5.0,"n":1,"ex":1,"alc":1,"pr":"A","note":"Sociedades mercantiles locales: Derecho PRIVADO, salvo en lo presupuestario, contable, de control financiero y de eficacia y contratación. Adoptan una forma de la Ley de Sociedades de Capital y sus estatutos regulan la Junta General y el Consejo de Administración."},{"law":"lbrl","art":"26","t":"Artículo 26.","sub":"Servicios mínimos — Todos / más de 5.000 / más de 20.000 / más de 50.000. Muy preguntado.","mat":"Servicios mínimos","cl":"Todos / más de 5.000 / más de 20.000 / más de 50.000. Muy preguntado.","w":13.0,"n":10,"ex":9,"alc":0,"pr":"A","note":"Servicios mínimos en 4 escalones: TODOS (alumbrado, cementerio, recogida de residuos, limpieza viaria, agua, alcantarillado, acceso, pavimentación); >5.000 «PaBiTra» (parque, biblioteca, tratamiento de residuos); >20.000 «ProSoInDe» (protección civil, servicios sociales, incendios, deportes); >50.000 «TraMa» (transporte urbano, medio ambiente urbano). La Diputación coordina en municipios de <20.000."},{"law":"lbrl","art":"21","t":"Artículo 21.","sub":"Alcalde — Atribuciones 21.1; indelegables 21.3; voto de calidad; bandos.","mat":"Alcalde","cl":"Atribuciones 21.1; indelegables 21.3; voto de calidad; bandos.","w":10.0,"n":7,"ex":7,"alc":0,"pr":"A","note":"Alcalde: atribuciones residuales. INDELEGABLES «COPRO-JE-SE-UR-PLA»: convocar y presidir, decidir empates, jefatura de personal (separación y despido), medidas urgentes en catástrofes, PLAntillas… Delegables en la JGL o los Tenientes de Alcalde: el resto. Operaciones de crédito previstas en el Presupuesto hasta el 10 % de los recursos ordinarios (las de tesorería, hasta el 15 %)."},{"law":"haciendalocal","art":"2","t":"Artículo 2. Enumeración de los recursos de las entidades locales.","sub":"Recursos de las haciendas locales — Lista a)–h): patrimonio, tributos, participaciones, subvenciones, precios públicos, crédito, multas…","mat":"Recursos de las haciendas locales","cl":"Lista a)–h): patrimonio, tributos, participaciones, subvenciones, precios públicos, crédito, multas…","w":10.0,"n":6,"ex":5,"alc":0,"pr":"A","note":"Recursos de las haciendas locales «PA-TRI-PAR-SUB-PRE-CRE-MUL-DEMÁS»: PAtrimonio, TRIbutos propios y recargos, PARticipaciones, SUBvenciones, PREcios públicos, CRÉditos, MULtas y demás prestaciones de Derecho público."},{"law":"haciendalocal","art":"17","t":"Artículo 17. Elaboración, publicación y publicidad de las ordenanzas fiscales.","sub":"Ordenanzas fiscales — 30 días mínimo; BOP y, si más de 10.000 hab., diario; sin reclamaciones, definitivo.","mat":"Ordenanzas fiscales","cl":"30 días mínimo; BOP y, si más de 10.000 hab., diario; sin reclamaciones, definitivo.","w":10.0,"n":8,"ex":7,"alc":0,"pr":"A","note":"Ordenanzas fiscales: exposición 30 días mínimo en el tablón; anuncio SIEMPRE en el BOP; además en un diario si la población es >10.000 habitantes (y las Diputaciones). Sin reclamaciones, provisional = definitivo. Ayuntamientos de >20.000 habitantes editan el texto íntegro en el primer cuatrimestre."},{"law":"haciendalocal","art":"169","t":"Artículo 169. Publicidad, aprobación definitiva y entrada en vigor.","sub":"Aprobación y prórroga — 15 días; 1 mes para resolver; antes del 31/12; prórroga automática.","mat":"Aprobación y prórroga","cl":"15 días; 1 mes para resolver; antes del 31/12; prórroga automática.","w":10.0,"n":6,"ex":5,"alc":0,"pr":"A","note":"Presupuesto «15-1M-31D»: exposición pública de 15 días previo anuncio en el BOP; sin reclamaciones queda aprobado; si las hay, el Pleno tiene 1 MES para resolverlas; aprobación definitiva antes del 31 de diciembre; si no, se prorroga automáticamente el anterior."},{"law":"ce","art":"103","t":"Artículo 103.","sub":"Principios de la Administración — Eficacia, jerarquía, descentralización, desconcentración, coordinación. Mérito y capacidad.","mat":"Principios de la Administración","cl":"Eficacia, jerarquía, descentralización, desconcentración, coordinación. Mérito y capacidad.","w":8.0,"n":5,"ex":5,"alc":0,"pr":"A","note":"Principios de la Administración «EJE-DesDes-Co»: Eficacia, Jerarquía, Descentralización, Desconcentración, Coordinación. Acceso según mérito y capacidad (el 23.2 añade igualdad)."},{"law":"ce","art":"137","t":"Artículo 137.","sub":"Organización territorial — Municipios, provincias y CCAA; autonomía para sus intereses.","mat":"Organización territorial","cl":"Municipios, provincias y CCAA; autonomía para sus intereses.","w":8.0,"n":7,"ex":7,"alc":0,"pr":"A","note":"Estado territorial «MPCA»: Municipios, Provincias y Comunidades Autónomas, todas con autonomía para la gestión de SUS intereses."},{"law":"escv","art":"10","t":"Artículo 10.","sub":"Derechos sociales — Carta de Derechos Sociales por Ley de Les Corts.","mat":"Derechos sociales","cl":"Carta de Derechos Sociales por Ley de Les Corts.","w":7.0,"n":5,"ex":4,"alc":0,"pr":"A","note":"Derechos sociales en el EACV: la Generalitat los defiende y una LEY de Les Corts elabora la Carta de Derechos Sociales. Ámbitos «FAMI-MENOR-MAYOR-DISCAP-MUJER-VIVIENDA…»: familia, uniones legalizadas, menores, no discriminación de discapacitados, mayores, igualdad de la mujer, vivienda, inmigrantes…"},{"law":"lbrl","art":"16","t":"Artículo 16.","sub":"Padrón — Prueba de residencia y domicilio; documento público y fehaciente; renovación cada 2 años (extranjeros no comunitarios sin autorización de residencia permanente).","mat":"Padrón","cl":"Prueba de residencia y domicilio; documento público y fehaciente; renovación cada 2 años (extranjeros no comunitarios sin autorización de residencia permanente).","w":7.0,"n":5,"ex":4,"alc":0,"pr":"A","note":"Padrón: prueba de residencia y domicilio. Extranjeros no comunitarios sin residencia de larga duración: renovación cada 2 AÑOS."},{"law":"lbrl","art":"20","t":"Artículo 20.","sub":"Organización municipal — Alcalde, Tenientes y Pleno en todos; JGL en más de 5.000 o si se acuerda.","mat":"Organización municipal","cl":"Alcalde, Tenientes y Pleno en todos; JGL en más de 5.000 o si se acuerda.","w":7.0,"n":5,"ex":5,"alc":0,"pr":"A","note":"Existen en todos los municipios: Alcalde, Tenientes de Alcalde, Pleno y Comisión Especial de Cuentas. JGL en los de >5.000 (o si lo decide el ROM o el Pleno)."},{"law":"lbrl","art":"22","t":"Artículo 22.","sub":"Pleno — Atribuciones 22.2; delegables e indelegables 22.4.","mat":"Pleno","cl":"Atribuciones 22.2; delegables e indelegables 22.4.","w":6.0,"n":4,"ex":4,"alc":0,"pr":"A","note":"Pleno = todos los Concejales, presidido por el Alcalde. Atribuciones «CONTROL-ORGANIZACIÓN-NORMAS-DINERO»: control de los órganos de gobierno, alteración del término, bandera, ordenanzas y reglamentos, presupuesto, plantilla y RPT, acciones judiciales en sus materias, cuestión de confianza. Indelegables las del 22.4 (salvo las delegables en el Alcalde y la JGL)."},{"law":"ce","art":"1","t":"Artículo 1.","sub":"Valores superiores y forma política — 4 valores: libertad, justicia, igualdad, pluralismo político. Soberanía en el pueblo. Monarquía parlamentaria.","mat":"Valores superiores y forma política","cl":"4 valores: libertad, justicia, igualdad, pluralismo político. Soberanía en el pueblo. Monarquía parlamentaria.","w":5.0,"n":5,"ex":5,"alc":0,"pr":"A","note":"Valores superiores «LIJUIGPO»: LIbertad, JUsticia, IGualdad, Pluralismo pOlítico. Soberanía en el pueblo español. Monarquía parlamentaria."},{"law":"ce","art":"140","t":"Artículo 140.","sub":"Municipio — Autonomía; personalidad jurídica plena; concejales por sufragio; concejo abierto.","mat":"Municipio","cl":"Autonomía; personalidad jurídica plena; concejales por sufragio; concejo abierto.","w":5.0,"n":4,"ex":4,"alc":0,"pr":"A","note":"Municipio: autonomía garantizada y personalidad jurídica PLENA (la provincia, PROPIA: art. 141). Concejales elegidos por sufragio universal, igual, libre, directo y secreto; el Alcalde, por los concejales o por los vecinos. La ley regula el concejo abierto."},{"law":"lbrl","art":"15","t":"Artículo 15.","sub":"Empadronamiento — Obligación; quien viva en varios: donde habite más tiempo; vecino desde la inscripción.","mat":"Empadronamiento","cl":"Obligación; quien viva en varios: donde habite más tiempo; vecino desde la inscripción.","w":5.0,"n":4,"ex":4,"alc":0,"pr":"A","note":"Padrón: obligatorio inscribirse donde se reside habitualmente (si son varios, donde más tiempo se vive). Vecino desde la inscripción."},{"law":"lbrl","art":"23","t":"Artículo 23.","sub":"Junta de Gobierno Local — Alcalde + hasta 1/3 de concejales; Tenientes.","mat":"Junta de Gobierno Local","cl":"Alcalde + hasta 1/3 de concejales; Tenientes.","w":5.0,"n":3,"ex":3,"alc":0,"pr":"A","note":"Junta de Gobierno: Alcalde + concejales ≤ 1/3 del número legal, nombrados y separados LIBREMENTE por el Alcalde (dando cuenta al Pleno). Funciones: asistir al Alcalde y las atribuciones delegadas o legales. Tenientes de Alcalde: los nombra el Alcalde de entre los miembros de la JGL y sustituyen por orden de nombramiento."},{"law":"lprevencion","art":"14","t":"Artículo 14. Derecho a la protección frente a los riesgos laborales.","sub":"Derecho a la protección — Protección eficaz; deber del empresario y de las AA. PP.","mat":"Derecho a la protección","cl":"Protección eficaz; deber del empresario y de las AA. PP.","w":5.0,"n":4,"ex":4,"alc":0,"pr":"A","note":"Derecho a la protección eficaz = deber del empresario (y de las Administraciones con su personal). Comprende «IN-CON-PAR-FOR-PARALIZ-VIGIL»: INformación, CONsulta, PARticipación, FORmación, PARALIZación ante riesgo grave e inminente y VIGILancia de la salud. Su coste no recae nunca en los trabajadores."},{"law":"lprevencion","art":"35","t":"Artículo 35. Delegados de Prevención.","sub":"Delegados de Prevención — Escala: 50–100: 2; 101–500: 3; 501–1.000: 4… Hasta 30: Delegado de Personal.","mat":"Delegados de Prevención","cl":"Escala: 50–100: 2; 101–500: 3; 501–1.000: 4… Hasta 30: Delegado de Personal.","w":5.0,"n":3,"ex":3,"alc":0,"pr":"A","note":"Delegados de Prevención por escala «50-100: 2 · 101-500: 3 · 501-1000: 4 · 1001-2000: 5 · 2001-3000: 6 · 3001-4000: 7 · más de 4001: 8». Hasta 30 trabajadores, el Delegado de Personal; de 31 a 49, uno elegido por y entre los Delegados de Personal."},{"law":"leyigualdaMyH","art":"1","t":"Artículo 1. Objeto de la Ley.","sub":"Objeto — Iguales en dignidad, derechos y deberes.","mat":"Objeto","cl":"Iguales en dignidad, derechos y deberes.","w":5.0,"n":3,"ex":3,"alc":0,"pr":"A","note":"Objeto de la LO 3/2007: igualdad de trato y de oportunidades, en desarrollo de los arts. 9.2 y 14 CE, en las esferas «PoCiLaEcoSoCu» (política, civil, laboral, económica, social y cultural), para una sociedad más democrática, justa y solidaria. Se aplica a toda persona física o jurídica que se encuentre o actúe en territorio español."},{"law":"ce","art":"142","t":"Artículo 142.","sub":"Haciendas locales — Medios suficientes; tributos propios y participación en los del Estado y CCAA.","mat":"Haciendas locales","cl":"Medios suficientes; tributos propios y participación en los del Estado y CCAA.","w":4.0,"n":4,"ex":4,"alc":0,"pr":"A","note":"Haciendas locales: medios SUFICIENTES; se nutren FUNDAMENTALMENTE de tributos propios y de la participación en los del Estado y de las CCAA."},{"law":"haciendalocal","art":"168","t":"Artículo 168. Procedimiento de elaboración y aprobación inicial.","sub":"Elaboración del presupuesto — Lo forma el Presidente; documentación que se une.","mat":"Elaboración del presupuesto","cl":"Lo forma el Presidente; documentación que se une.","w":4.0,"n":4,"ex":4,"alc":0,"pr":"A","note":"Formación del presupuesto: la hace el PRESIDENTE y lleva «MemLiqPerInvBenConv»: Memoria, Liquidación (y avance de 6 meses), anexos de Personal, Inversiones, Beneficios fiscales, Convenios de gasto social, más el informe económico-financiero. El Presidente lo remite, informado por la Intervención, al Pleno antes del 15 de octubre."},{"law":"ce","art":"106","t":"Artículo 106.","sub":"Control y responsabilidad — Tribunales controlan; indemnización salvo fuerza mayor.","mat":"Control y responsabilidad","cl":"Tribunales controlan; indemnización salvo fuerza mayor.","w":4.0,"n":3,"ex":2,"alc":0,"pr":"B","note":"Los Tribunales controlan la potestad reglamentaria y la legalidad administrativa. Responsabilidad patrimonial: toda lesión de bienes y derechos derivada del funcionamiento de los servicios públicos, SALVO fuerza mayor, en los términos de la ley."},{"law":"ce","art":"149","t":"Artículo 149.","sub":"Competencias del Estado — Lista exclusiva; cláusula residual; prevalencia y supletoriedad (149.3).","mat":"Competencias del Estado","cl":"Lista exclusiva; cláusula residual; prevalencia y supletoriedad (149.3).","w":4.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Competencias exclusivas del Estado: 32 materias. Trucos: lo «básico» y la «legislación» suelen ser del Estado (legislación laboral, mercantil, penal, procesal, civil con matices) y la «ejecución» de la CA. Las cláusulas residuales del 149.3 favorecen al Estado."},{"law":"ce","art":"161","t":"Artículo 161.","sub":"Competencias del TC — Inconstitucionalidad, amparo, conflictos.","mat":"Competencias del TC","cl":"Inconstitucionalidad, amparo, conflictos.","w":4.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Tribunal Constitucional «I-A-C»: recurso de Inconstitucionalidad, Amparo y Conflictos de competencia. Si el Gobierno impugna disposiciones autonómicas, se produce la SUSPENSIÓN, que el TC ratifica o levanta en un plazo no superior a 5 MESES."},{"law":"escv","art":"12","t":"Artículo 12.","sub":"Identidad y creatividad — Protección de identidad, patrimonio y creatividad artística, científica y técnica.","mat":"Identidad y creatividad","cl":"Protección de identidad, patrimonio y creatividad artística, científica y técnica.","w":4.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Identidad: la Generalitat protege la identidad, los valores e intereses del Pueblo Valenciano, su diversidad cultural y su patrimonio histórico, y también la creatividad artística, científica y técnica."},{"law":"escv","art":"21","t":"Artículo 21.","sub":"Les Corts — Potestad legislativa; inviolables; sede en el Palacio de los Borja.","mat":"Les Corts","cl":"Potestad legislativa; inviolables; sede en el Palacio de los Borja.","w":4.0,"n":2,"ex":1,"alc":0,"pr":"B","note":"Les Corts: potestad legislativa; representan al pueblo; son INVIOLABLES y gozan de autonomía. Sede: Palau dels BORJA (València), aunque pueden reunirse en otros lugares de la Comunitat."},{"law":"lbrl","art":"18","t":"Artículo 18.","sub":"Derechos y deberes de los vecinos — Lista 18.1 a)–h).","mat":"Derechos y deberes de los vecinos","cl":"Lista 18.1 a)–h).","w":4.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Derechos y deberes de los vecinos: elector y elegible; participar; usar los servicios y aprovechamientos comunales; CONTRIBUIR (deber); ser informado; pedir CONSULTA popular; exigir el servicio obligatorio; iniciativa popular."},{"law":"lbrl","art":"19","t":"Artículo 19.","sub":"Gobierno municipal — Ayuntamiento: Alcalde y Concejales.","mat":"Gobierno municipal","cl":"Ayuntamiento: Alcalde y Concejales.","w":4.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Gobierno municipal: el AYUNTAMIENTO (Alcalde y Concejales), salvo en el Concejo Abierto. Concejales por sufragio; Alcalde por los concejales o por los vecinos. Los municipios de gran población se rigen por el Título X."},{"law":"lbrl","art":"47","t":"Artículo 47.","sub":"Mayorías — Simple como regla; lista de mayoría absoluta 47.2.","mat":"Mayorías","cl":"Simple como regla; lista de mayoría absoluta 47.2.","w":4.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Mayorías: la regla es la SIMPLE de los presentes (más síes que noes). La ABSOLUTA del número legal para: creación o supresión de municipios, nombre y capitalidad, bandera, ROM, mancomunidades, delegaciones de otras Administraciones, cesiones de bienes, alteración de la calificación demanial, quitas y créditos de más del 10 %, aprobación del planeamiento general, entre otras."},{"law":"lbrl","art":"89","t":"Artículo 89.","sub":"Personal — Funcionarios, laborales y eventuales.","mat":"Personal","cl":"Funcionarios, laborales y eventuales.","w":4.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Personal local «FUN-LAB-EVE»: funcionarios de carrera, contratados laborales y eventuales de confianza o asesoramiento especial."},{"law":"haciendalocal","art":"31","t":"Artículo 31. Base imponible.","sub":"Contribuciones especiales — Base máxima: 90 % del coste.","mat":"Contribuciones especiales","cl":"Base máxima: 90 % del coste.","w":4.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Contribuciones especiales: base imponible MÁXIMA del 90 % del coste (estudios y proyectos, obras, terrenos, indemnizaciones, intereses); el coste es una mera previsión. Se reparte según metros lineales de fachada, superficie, volumen o valor catastral."},{"law":"ce","art":"10","t":"Artículo 10.","sub":"Dignidad e interpretación — Interpretación conforme a la Declaración Universal y a los tratados ratificados.","mat":"Dignidad e interpretación","cl":"Interpretación conforme a la Declaración Universal y a los tratados ratificados.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Fundamento del orden político «DIDELI-RES»: Dignidad, Derechos inviolables, Libre desarrollo de la personalidad, Respeto a la ley y a los derechos de los demás. Los derechos se interpretan conforme a la Declaración Universal de Derechos Humanos y los tratados ratificados."},{"law":"ce","art":"14","t":"Artículo 14.","sub":"Igualdad — Nacimiento, raza, sexo, religión, opinión u otra circunstancia. Se refiere a los «españoles».","mat":"Igualdad","cl":"Nacimiento, raza, sexo, religión, opinión u otra circunstancia. Se refiere a los «españoles».","w":3.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Igualdad ante la ley, sin discriminación por «NARASEREOP»: NAcimiento, RAza, SExo, RElig., OPinión o cualquier otra condición o circunstancia personal o social. Es amparable."},{"law":"ce","art":"53","t":"Artículo 53.","sub":"Garantías — 53.2: preferencia y sumariedad + amparo para art. 14, Sección 1.ª y objeción de conciencia (art. 30).","mat":"Garantías","cl":"53.2: preferencia y sumariedad + amparo para art. 14, Sección 1.ª y objeción de conciencia (art. 30).","w":3.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Garantías «53.1 ley-contenido esencial; 53.2 preferente, sumario y amparo (art. 14, Sección 1.ª y objeción del art. 30); 53.3 principios rectores que informan la legislación y solo se alegan conforme a sus leyes»."},{"law":"ce","art":"59","t":"Artículo 59.","sub":"Regencia — Padre, madre o pariente mayor de edad más próximo; las Cortes en su defecto.","mat":"Regencia","cl":"Padre, madre o pariente mayor de edad más próximo; las Cortes en su defecto.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Regencia: si el Rey es menor, el padre o la madre y si no, el pariente mayor de edad más próximo. Si se inhabilita (reconocido por las Cortes): el Príncipe heredero mayor de edad. Si no hay nadie: la nombran las Cortes con 1, 3 o 5 personas. Requisitos: ser español y mayor de edad."},{"law":"ce","art":"168","t":"Artículo 168.","sub":"Reforma agravada — Título Preliminar, Sección 1.ª Cap. II Tít. I y Tít. II; 2/3, disolución, referéndum obligatorio.","mat":"Reforma agravada","cl":"Título Preliminar, Sección 1.ª Cap. II Tít. I y Tít. II; 2/3, disolución, referéndum obligatorio.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Reforma agravada «2/3 + DISOLUCIÓN + 2/3 + REFERÉNDUM obligatorio»: revisión total, Título Preliminar, Sección 1.ª del Capítulo II del Título I (arts. 15-29) o Título II (la Corona)."},{"law":"escv","art":"3","t":"Artículo 3.","sub":"Condición política de valenciano — Vecindad administrativa en un municipio de la CV.","mat":"Condición política de valenciano","cl":"Vecindad administrativa en un municipio de la CV.","w":3.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Condición política de valenciano: españoles con VECINDAD ADMINISTRATIVA en cualquier municipio de la Comunitat. Los residentes en el extranjero, si su última vecindad fue aquí y lo acreditan en el Consulado (también sus descendientes, si lo solicitan)."},{"law":"escv","art":"20","t":"Artículo 20.","sub":"Instituciones — Corts, President, Consell + Sindicatura, Síndic, CVC, AVL, CJC, CES.","mat":"Instituciones","cl":"Corts, President, Consell + Sindicatura, Síndic, CVC, AVL, CJC, CES.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Generalitat = «CORTS-PRESIDENT-CONSELL». Otras instituciones «SiSiCuAcaJuCES»: Sindicatura de Comptes, Síndic de Greuges, Consell Valencià de Cultura, Acadèmia Valenciana de la Llengua, Consell Jurídic Consultiu y Comité Econòmic i Social."},{"law":"escv","art":"27","t":"Artículo 27.","sub":"President — Elegido por Les Corts de entre sus miembros y nombrado por el Rey; mayoría absoluta en 1.ª votación.","mat":"President","cl":"Elegido por Les Corts de entre sus miembros y nombrado por el Rey; mayoría absoluta en 1.ª votación.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"President: elegido por Les Corts de ENTRE SUS MIEMBROS y nombrado por el Rey. Los candidatos los presentan los Grupos Parlamentarios y el Presidente de Les Corts propone uno tras consultar. El candidato expone su programa y pide la confianza."},{"law":"lbrl","art":"13","t":"Artículo 13.","sub":"Creación de municipios — Núcleos diferenciados de al menos 4.000 habitantes (no 5.000).","mat":"Creación de municipios","cl":"Núcleos diferenciados de al menos 4.000 habitantes (no 5.000).","w":3.0,"n":3,"ex":2,"alc":0,"pr":"B","note":"«4.000, no 5.000»: para segregar y crear municipio hacen falta núcleos de población territorialmente diferenciados de al menos 4.000 habitantes. Truco: 4 patas = un municipio que se sostiene. Además, el nuevo y el de origen deben ser financieramente sostenibles, sin merma de la calidad del servicio."},{"law":"lbrl","art":"17","t":"Artículo 17.","sub":"Gestión del Padrón — Ayuntamiento; Diputaciones si no tienen capacidad; Consejo de Empadronamiento.","mat":"Gestión del Padrón","cl":"Ayuntamiento; Diputaciones si no tienen capacidad; Consejo de Empadronamiento.","w":3.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Padrón = «lo hace el AYUNTAMIENTO, lo coordina el INE». Formación, mantenimiento, revisión y custodia: Ayuntamiento (Diputaciones si no puede). Discrepancias INE–Ayuntamiento → Consejo de Empadronamiento (adscrito al Ministerio, presidido por el Presidente del INE)."},{"law":"lbrl","art":"70","t":"Artículo 70.","sub":"Publicidad — Pleno público; JGL no; ordenanzas en el BOP.","mat":"Publicidad","cl":"Pleno público; JGL no; ordenanzas en el BOP.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"«Pleno a la vista, Junta a puerta cerrada»: las sesiones del Pleno son públicas (salvo debate que afecte al art. 18.1 CE, por mayoría absoluta); las de la JGL no. Las ordenanzas se publican íntegras en el BOP y entran en vigor tras 15 días hábiles (art. 65.2)."},{"law":"lbrl","art":"80","t":"Artículo 80.","sub":"Inalienabilidad — Dominio público y comunales: inalienables, inembargables, imprescriptibles.","mat":"Inalienabilidad","cl":"Dominio público y comunales: inalienables, inembargables, imprescriptibles.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Dominio público y comunales: «las 3 I»: Inalienables, Inembargables, Imprescriptibles (y no sujetos a tributo). Los patrimoniales se rigen por su legislación específica y, en su defecto, por el Derecho privado."},{"law":"lbrl","art":"85","t":"Artículo 85.","sub":"Formas de gestión — Directa (4) e indirecta.","mat":"Formas de gestión","cl":"Directa (4) e indirecta.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Gestión directa = «GO-EE-SM»: Gestión por la propia entidad, Organismo autónomo, Entidad pública empresarial, Sociedad mercantil 100 % pública. EPE y SM solo si son más sostenibles y eficientes (memoria justificativa). Indirecta = modalidades del contrato de concesión (LCSP). Nunca indirecta ni por sociedad privada si hay ejercicio de autoridad."},{"law":"haciendalocal","art":"20","t":"Artículo 20. Hecho imponible.","sub":"Tasas: hecho imponible — Dominio público + servicio no voluntario o no prestado por el sector privado.","mat":"Tasas: hecho imponible","cl":"Dominio público + servicio no voluntario o no prestado por el sector privado.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Tasa = «DO o SE no voluntario»: utilización privativa o aprovechamiento especial del DOminio público, o prestación de un SErvicio/actividad en régimen de Derecho público que no sea de solicitud voluntaria o que no presta el sector privado."},{"law":"haciendalocal","art":"59","t":"Artículo 59. Enumeración de impuestos.","sub":"Impuestos municipales — Obligatorios: IBI, IAE, IVTM. Potestativos: ICIO, IIVTNU.","mat":"Impuestos municipales","cl":"Obligatorios: IBI, IAE, IVTM. Potestativos: ICIO, IIVTNU.","w":3.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Obligatorios «IBI-IAE-IVTM» (los 3 de siempre: la casa, el negocio y el coche). Potestativos «ICIO e IIVTNU» (las obras y la plusvalía). Los potestativos se establecen por ordenanza fiscal."},{"law":"haciendalocal","art":"163","t":"Artículo 163. Ámbito temporal.","sub":"Ejercicio presupuestario — Año natural.","mat":"Ejercicio presupuestario","cl":"Año natural.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Ejercicio presupuestario = AÑO NATURAL. Truco «Reyes-Nochevieja»: del 1 de enero al 31 de diciembre se imputan los derechos liquidados y las obligaciones reconocidas en el año."},{"law":"haciendalocal","art":"174","t":"Artículo 174. Compromisos de gasto de carácter plurianual.","sub":"Gastos plurianuales — Casos 174.2.","mat":"Gastos plurianuales","cl":"Casos 174.2.","w":3.0,"n":3,"ex":2,"alc":0,"pr":"B","note":"Gasto plurianual: «ni más de 4 años ni más del 70-60-50-50 %». Casos: inversiones y transferencias de capital, contratos de suministro/servicios que no puedan estipularse por un año, arrendamientos de bienes, cargas financieras y transferencias corrientes según leyes. El Pleno puede ampliar el número de anualidades y los porcentajes en casos excepcionales."},{"law":"haciendalocal","art":"180","t":"Artículo 180. Transferencias de crédito: límites objetivos.","sub":"Límites de las transferencias — No a créditos ampliables ni extraordinarios.","mat":"Límites de las transferencias","cl":"No a créditos ampliables ni extraordinarios.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Transferencias: «NO AMPLÍO, NO EXTRAORDINO, NO REPITO». No afectan a créditos ampliables ni extraordinarios; no minoran créditos suplementados o ampliados ni incrementan los que han sido objeto de minoración (salvo personal ni programas de imprevistos)."},{"law":"haciendalocal","art":"184","t":"Artículo 184. Fases del procedimiento de gestión de los gastos.","sub":"Fases del gasto — A-D-O-P.","mat":"Fases del gasto","cl":"A-D-O-P.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Fases del gasto «A-D-O-P» = «Ana Dice Oye Paga»: Autorización, Disposición (compromiso), reconocimiento de la Obligación y ordenación del Pago. Se pueden acumular (AD, ADO)."},{"law":"lprevencion","art":"15","t":"Artículo 15. Principios de la acción preventiva.","sub":"Principios de la acción preventiva — Evitar, evaluar, combatir en origen, adaptar, sustituir, planificar, protección colectiva.","mat":"Principios de la acción preventiva","cl":"Evitar, evaluar, combatir en origen, adaptar, sustituir, planificar, protección colectiva.","w":3.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Principios de la acción preventiva: «EVITAR, EVALUAR, COMBATIR EN EL ORIGEN, ADAPTAR AL HOMBRE, TÉCNICA, SUSTITUIR, PLANIFICAR, COLECTIVO > INDIVIDUAL, INSTRUCCIONES». Regla de oro: primero se evita; lo que no se puede evitar, se evalúa; la protección colectiva va antes que la individual."},{"law":"leyigualdaMyH","art":"6","t":"Artículo 6. Discriminación directa e indirecta.","sub":"Discriminación directa e indirecta — Definiciones casi literales en examen.","mat":"Discriminación directa e indirecta","cl":"Definiciones casi literales en examen.","w":3.0,"n":3,"ex":2,"alc":0,"pr":"B","note":"DIRECTA = «te tratan peor POR ser mujer/hombre» (en situación comparable). INDIRECTA = «norma aparentemente neutra que pone en desventaja particular a un sexo», salvo que se justifique objetivamente con un fin legítimo y medios necesarios y adecuados."},{"law":"leyigualdaMyH","art":"7","t":"Artículo 7. Acoso sexual y acoso por razón de sexo.","sub":"Acoso sexual y por razón de sexo — Distinguir: «de naturaleza sexual» / «en función del sexo».","mat":"Acoso sexual y por razón de sexo","cl":"Distinguir: «de naturaleza sexual» / «en función del sexo».","w":3.0,"n":3,"ex":3,"alc":0,"pr":"B","note":"Acoso SEXUAL = comportamiento «de naturaleza sexual». Acoso POR RAZÓN DE SEXO = comportamiento «en función del sexo». Ambos: atentan contra la dignidad, entorno intimidatorio, degradante u ofensivo. Ambos son discriminatorios."},{"law":"ce","art":"2","t":"Artículo 2.","sub":"Unidad y autonomía — Indisoluble unidad; autonomía de nacionalidades y regiones; solidaridad.","mat":"Unidad y autonomía","cl":"Indisoluble unidad; autonomía de nacionalidades y regiones; solidaridad.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Art. 2 «U-A-S»: Unidad (indisoluble, patria común e indivisible), Autonomía (de nacionalidades y regiones) y Solidaridad entre todas ellas."},{"law":"ce","art":"17","t":"Artículo 17.","sub":"Libertad personal — Detención preventiva: máximo 72 horas. Habeas corpus.","mat":"Libertad personal","cl":"Detención preventiva: máximo 72 horas. Habeas corpus.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Detención preventiva «72 horas máximo» (no más de lo estrictamente necesario). Derechos del detenido: informado de forma inmediata y comprensible, no declarar, abogado. Habeas corpus = puesta inmediata a disposición judicial. Prisión provisional: plazo máximo por ley."},{"law":"ce","art":"54","t":"Artículo 54.","sub":"Defensor del Pueblo — Alto comisionado de las Cortes; designado por ellas; ley orgánica.","mat":"Defensor del Pueblo","cl":"Alto comisionado de las Cortes; designado por ellas; ley orgánica.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Defensor del Pueblo: «Alto comisionado de las CORTES», designado por ellas, para defender el Título I; supervisa la actividad de la Administración; regulado por LO (LO 3/1981). Mandato de 5 años."},{"law":"ce","art":"102","t":"Artículo 102.","sub":"Responsabilidad penal del Gobierno — Sala de lo Penal del TS; traición: iniciativa de 1/4 del Congreso y mayoría absoluta.","mat":"Responsabilidad penal del Gobierno","cl":"Sala de lo Penal del TS; traición: iniciativa de 1/4 del Congreso y mayoría absoluta.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Responsabilidad criminal del Gobierno → Sala de lo Penal del TS. Traición o delito contra la seguridad del Estado: iniciativa de 1/4 del Congreso + aprobación por mayoría absoluta. Truco «1/4 acusa, la absoluta confirma». Prerrogativa de gracia: NO aplicable."},{"law":"ce","art":"117","t":"Artículo 117.","sub":"Poder Judicial — Emana del pueblo; independientes, inamovibles, responsables, sometidos a la ley.","mat":"Poder Judicial","cl":"Emana del pueblo; independientes, inamovibles, responsables, sometidos a la ley.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Justicia «emana del pueblo», se administra en nombre del Rey. Jueces «IIRS»: Independientes, Inamovibles, Responsables y Sometidos únicamente al imperio de la ley. Unidad jurisdiccional; prohibidos los tribunales de excepción."},{"law":"ce","art":"147","t":"Artículo 147.","sub":"Estatutos — Norma institucional básica; contenido mínimo (147.2).","mat":"Estatutos","cl":"Norma institucional básica; contenido mínimo (147.2).","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Estatuto = norma institucional básica de la CA. Contenido mínimo «DeTeDeCo»: Denominación, Territorio, Denominación/organización/sede de las instituciones, Competencias. Reforma: lo que el propio Estatuto diga + ley orgánica de las Cortes."},{"law":"ce","art":"150","t":"Artículo 150.","sub":"Leyes marco, transferencia y armonización — 150.1 marco; 150.2 ley orgánica; 150.3 armonización por mayoría absoluta.","mat":"Leyes marco, transferencia y armonización","cl":"150.1 marco; 150.2 ley orgánica; 150.3 armonización por mayoría absoluta.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"«MARCO - TRANSFIERO - ARMONIZO»: 150.1 ley marco (Cortes atribuyen facultades legislativas con control); 150.2 ley orgánica de transferencia o delegación; 150.3 ley de armonización (las Cortes aprecian la necesidad por mayoría absoluta de cada Cámara)."},{"law":"escv","art":"16","t":"Artículo 16.","sub":"Vivienda — Acceso a vivienda digna; ayudas a jóvenes, sin medios, maltratadas, discapacidad.","mat":"Vivienda","cl":"Acceso a vivienda digna; ayudas a jóvenes, sin medios, maltratadas, discapacidad.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Vivienda digna: la Generalitat garantiza el acceso, con especial atención a «JÓ-SIN-MAL-DIS»: JÓvenes, personas SIN medios, mujeres MALtratadas, personas con DIScapacidad y afectadas por dependencia."},{"law":"escv","art":"23","t":"Artículo 23.","sub":"Composición de Les Corts — No menos de 99 diputados.","mat":"Composición de Les Corts","cl":"No menos de 99 diputados.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Les Corts: «99 = mínimo». Las integran no menos de 99 diputados y diputadas, elegidos por sufragio universal, igual, libre, directo y secreto."},{"law":"escv","art":"24","t":"Artículo 24.","sub":"Ley Electoral Valenciana — 2/3 de Les Corts; mínimo 20 diputados por provincia; desproporción inferior a 1 a 3.","mat":"Ley Electoral Valenciana","cl":"2/3 de Les Corts; mínimo 20 diputados por provincia; desproporción inferior a 1 a 3.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Ley electoral valenciana: «2/3, 20 y 1 a 3»: se aprueba por 2/3 de Les Corts; cada provincia tiene un mínimo de 20 diputados; desproporción entre escaños y población menor de 1 a 3."},{"law":"escv","art":"39","t":"Artículo 39. La Sindicatura de Comptes.","sub":"Sindicatura de Comptes — Control externo económico y presupuestario.","mat":"Sindicatura de Comptes","cl":"Control externo económico y presupuestario.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Sindicatura de Comptes = el «Tribunal de Cuentas valenciano»: control externo económico y presupuestario de la Generalitat, entes locales y sector público valenciano; depende orgánicamente de Les Corts."},{"law":"lbrl","art":"3","t":"Artículo 3.","sub":"Clases de entidades locales — Territoriales: municipio, provincia, isla. Además: comarcas, áreas metropolitanas, mancomunidades.","mat":"Clases de entidades locales","cl":"Territoriales: municipio, provincia, isla. Además: comarcas, áreas metropolitanas, mancomunidades.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Territoriales «M-P-I»: Municipio, Provincia, Isla (Baleares y Canarias). También locales: «CO-AM-MAN»: COmarcas, Áreas Metropolitanas, MANcomunidades de municipios."},{"law":"lbrl","art":"11","t":"Artículo 11.","sub":"Municipio — Entidad local básica; elementos: territorio, población, organización.","mat":"Municipio","cl":"Entidad local básica; elementos: territorio, población, organización.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Municipio = entidad local básica de la organización territorial del Estado. Elementos «TPO»: Territorio, Población y Organización. Personalidad jurídica y plena capacidad."},{"law":"lbrl","art":"79","t":"Artículo 79.","sub":"Bienes — Dominio público o patrimoniales; comunales.","mat":"Bienes","cl":"Dominio público o patrimoniales; comunales.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Bienes «DP-P-C»: Dominio Público (uso o servicio público), Patrimoniales y Comunales (cuyo aprovechamiento corresponde al común de vecinos, que son dominio público). Alteración de la calificación: expediente que acredite oportunidad y legalidad."},{"law":"lbrl","art":"130","t":"Artículo 130. Órganos superiores y directivos.","sub":"Órganos superiores y directivos — Superiores: Alcalde y JGL. Lista de directivos.","mat":"Órganos superiores y directivos","cl":"Superiores: Alcalde y JGL. Lista de directivos.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Gran población: órganos SUPERIORES = solo dos: Alcalde y miembros de la JGL. DIRECTIVOS = coordinadores generales, directores generales, titular de la asesoría jurídica, Secretario General del Pleno, Interventor general, titular del órgano de gestión tributaria… (los «técnicos de mando»)."},{"law":"haciendalocal","art":"3","t":"Artículo 3. Definición.","sub":"Ingresos de derecho privado — Rendimientos del patrimonio y adquisiciones a título de herencia, legado o donación.","mat":"Ingresos de derecho privado","cl":"Rendimientos del patrimonio y adquisiciones a título de herencia, legado o donación.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Ingresos de Derecho privado = «PA-HE-LE-DO»: rendimientos del PAtrimonio y adquisiciones por HErencia, LEgado o DOnación."},{"law":"leyigualdaMyH","art":"10","t":"Artículo 10. Consecuencias jurídicas de las conductas discriminatorias.","sub":"Consecuencias jurídicas — Nulos y sin efecto; reparaciones reales, efectivas y proporcionadas.","mat":"Consecuencias jurídicas","cl":"Nulos y sin efecto; reparaciones reales, efectivas y proporcionadas.","w":2.0,"n":2,"ex":2,"alc":0,"pr":"B","note":"Consecuencias: «NULO + REPARO + DISUADO»: el acto discriminatorio es nulo y sin efecto; reparaciones reales, efectivas y proporcionadas; sanciones eficaces y disuasorias."},{"law":"ce","art":"9","t":"Artículo 9.","sub":"Principios garantizados (9.3) — 7 principios: legalidad, jerarquía, publicidad, irretroactividad, seguridad jurídica, responsabilidad, interdicción de la arbitrariedad.","mat":"Principios garantizados (9.3)","cl":"7 principios: legalidad, jerarquía, publicidad, irretroactividad, seguridad jurídica, responsabilidad, interdicción de la arbitrariedad.","w":2.0,"n":2,"ex":1,"alc":0,"pr":"C","note":"9.3 = «LE-JE-PU-IRRE-SE-RE-IN» (7 principios): LEgalidad, JErarquía normativa, PUblicidad de las normas, IRREtroactividad de las sancionadoras no favorables o restrictivas, SEguridad jurídica, REsponsabilidad e INterdicción de la arbitrariedad de los poderes públicos. Ojo: la «eficacia» NO está (es del art. 103)."},{"law":"ce","art":"68","t":"Artículo 68.","sub":"Congreso — 300–400 diputados; provincia como circunscripción; 4 años.","mat":"Congreso","cl":"300–400 diputados; provincia como circunscripción; 4 años.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Congreso «300-400 / 4 años / provincia»: mínimo 300 y máximo 400 diputados (la LOREG fija 350); circunscripción = provincia; Ceuta y Melilla 1 diputado cada una; representación proporcional; mandato de 4 años."},{"law":"ce","art":"73","t":"Artículo 73.","sub":"Períodos de sesiones — Septiembre–diciembre y febrero–junio.","mat":"Períodos de sesiones","cl":"Septiembre–diciembre y febrero–junio.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Periodos de sesiones: «SE-DI y FE-JU» = SEptiembre–DIciembre y FEbrero–JUnio. Extraordinarias: Gobierno, Diputación Permanente o mayoría absoluta de una Cámara, con orden del día determinado."},{"law":"ce","art":"99","t":"Artículo 99.","sub":"Investidura — Mayoría absoluta; a las 48 h simple; 2 meses y disolución.","mat":"Investidura","cl":"Mayoría absoluta; a las 48 h simple; 2 meses y disolución.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Investidura «absoluta, 48 h simple, 2 meses y fuera»: 1.ª votación mayoría absoluta; 48 horas después mayoría simple; si en 2 meses desde la 1.ª votación nadie la obtiene → disolución de ambas Cámaras con refrendo del Presidente del Congreso."},{"law":"ce","art":"167","t":"Artículo 167.","sub":"Reforma ordinaria — 3/5; comisión paritaria; 2/3 Congreso + mayoría absoluta Senado; referéndum si 1/10 en 15 días.","mat":"Reforma ordinaria","cl":"3/5; comisión paritaria; 2/3 Congreso + mayoría absoluta Senado; referéndum si 1/10 en 15 días.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Reforma ordinaria «3/5-Comisión-2/3-1/10-15»: 3/5 de cada Cámara; si no hay acuerdo, Comisión paritaria; si falla, mayoría absoluta del Senado y 2/3 del Congreso; referéndum si lo pide 1/10 de cualquier Cámara dentro de 15 días."},{"law":"lbrl","art":"116","t":"Artículo 116.","sub":"Cuentas anuales — Antes del 1 de junio a la Comisión Especial de Cuentas.","mat":"Cuentas anuales","cl":"Antes del 1 de junio a la Comisión Especial de Cuentas.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Cuentas: «1 de JUNIO a la Comisión»: las cuentas anuales se someten a la Comisión Especial de Cuentas antes del 1 de junio; información pública; Pleno antes del 1 de octubre (art. 212 TRLRHL)."},{"law":"haciendalocal","art":"101","t":"Artículo 101. Sujetos pasivos.","sub":"ICIO: sujetos — Dueño de la obra; sustitutos: quienes soliciten la licencia o realicen la obra.","mat":"ICIO: sujetos","cl":"Dueño de la obra; sustitutos: quienes soliciten la licencia o realicen la obra.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"ICIO, sujeto pasivo: contribuyente = el DUEÑO de la obra (quien soporta su coste), sea o no propietario del suelo; sustituto = quien solicita la licencia, presenta la declaración responsable o realiza la obra (y puede repercutir la cuota)."},{"law":"haciendalocal","art":"107","t":"Artículo 107. Base imponible.","sub":"Plusvalía: base — Periodo máximo de 20 años.","mat":"Plusvalía: base","cl":"Periodo máximo de 20 años.","w":2.0,"n":2,"ex":1,"alc":0,"pr":"C","note":"Plusvalía «20 años»: base = incremento del valor de los terrenos urbanos durante un máximo de 20 años. Valor = el catastral (IBI). Si el incremento real es menor, se tributa por el real (art. 107.5). Tipo máximo: 30 %."},{"law":"haciendalocal","art":"179","t":"Artículo 179. Transferencias de crédito: límites formales y competencia.","sub":"Transferencias de crédito — Competencia del Pleno si son entre distintas áreas de gasto.","mat":"Transferencias de crédito","cl":"Competencia del Pleno si son entre distintas áreas de gasto.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Transferencias: las regulan las bases de ejecución. Entre distintas áreas de gasto (la ley dice «grupos de función») → PLENO, salvo las de PERSONAL. Las del Pleno siguen el trámite del art. 169 (exposición pública 15 días)."},{"law":"haciendalocal","art":"212","t":"Artículo 212. Rendición, publicidad y aprobación de la cuenta general.","sub":"Cuenta general — 15 mayo, 1 junio, 15 días, 1 octubre.","mat":"Cuenta general","cl":"15 mayo, 1 junio, 15 días, 1 octubre.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Cuenta general «15-M, 1-J, 15+8, 1-O»: rinde el Presidente antes del 15 de MAYO; Comisión Especial de Cuentas antes del 1 de JUNIO; exposición pública 15 días + 8 para reclamaciones; Pleno antes del 1 de OCTUBRE; al Tribunal de Cuentas antes del 15 de octubre."},{"law":"lprevencion","art":"22","t":"Artículo 22. Vigilancia de la salud.","sub":"Vigilancia de la salud — Voluntaria, con excepciones tasadas; consentimiento.","mat":"Vigilancia de la salud","cl":"Voluntaria, con excepciones tasadas; consentimiento.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Vigilancia de la salud: «Voluntaria, salvo 3 excepciones»: cuando sea imprescindible evaluar los efectos de las condiciones de trabajo, verificar si el estado del trabajador es un peligro para él o para otros, o lo disponga una ley. Datos confidenciales: el empresario solo recibe las conclusiones de aptitud."},{"law":"leyigualdaMyH","art":"14","t":"Artículo 14. Criterios generales de actuación de los Poderes Públicos.","sub":"Criterios de los poderes públicos — Lista 1–12.","mat":"Criterios de los poderes públicos","cl":"Lista 1–12.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Criterios de los poderes públicos (12): compromiso con la igualdad, integración en políticas, colaboración entre AA. PP., participación equilibrada, erradicación de la violencia de género, atención a colectivos vulnerables, protección de la maternidad, conciliación y corresponsabilidad, lenguaje no sexista… Truco: «los 12 mandamientos de la igualdad»."},{"law":"leyigualdaMyH","art":"15","t":"Artículo 15. Transversalidad del principio de igualdad de trato entre mujeres y hombres.","sub":"Transversalidad — Informará con carácter transversal.","mat":"Transversalidad","cl":"Informará con carácter transversal.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"TRANSVERSALIDAD («mainstreaming»): la igualdad informa de forma transversal toda la actuación pública; se integra activamente en normas, presupuestos y políticas en TODOS los ámbitos."},{"law":"leyigualdaMyH","art":"19","t":"Artículo 19. Informes de impacto de género.","sub":"Impacto de género — Proyectos que se aprueben en Consejo de Ministros.","mat":"Impacto de género","cl":"Proyectos que se aprueben en Consejo de Ministros.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Informe de impacto de GÉNERO: proyectos de disposiciones generales y planes de especial relevancia económica, social, cultural y artística que se aprueben en CONSEJO DE MINISTROS."},{"law":"leyigualdaMyH","art":"36","t":"Artículo 36. La igualdad en los medios de comunicación social de titularidad pública.","sub":"Medios públicos — Imagen igualitaria, plural y no estereotipada.","mat":"Medios públicos","cl":"Imagen igualitaria, plural y no estereotipada.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Medios públicos: imagen «IPNE»: Igualitaria, Plural y No Estereotipada de mujeres y hombres; promover el conocimiento y la difusión de la igualdad."},{"law":"leyigualdaMyH","art":"51","t":"Artículo 51. Criterios de actuación de las Administraciones públicas.","sub":"Criterios de las AA. PP. — Remover obstáculos, conciliación, formación, presencia equilibrada.","mat":"Criterios de las AA. PP.","cl":"Remover obstáculos, conciliación, formación, presencia equilibrada.","w":2.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Criterios de las AA. PP. «RE-CO-FO-PRE-ACO-EVA»: REmover obstáculos, COnciliación, FOrmación, PREsencia equilibrada en órganos de selección y valoración, protección frente al ACOso, acciones positivas, EVAluación periódica."},{"law":"ce","art":"57","t":"Artículo 57.","sub":"Sucesión en la Corona — Varón a mujer (en el mismo grado); Príncipe de Asturias; abdicaciones por ley orgánica.","mat":"Sucesión en la Corona","cl":"Varón a mujer (en el mismo grado); Príncipe de Asturias; abdicaciones por ley orgánica.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Sucesión: «Juan Carlos I, primogenitura y representación; línea anterior a posterior; grado más próximo; VARÓN a mujer; mayor a menor». Heredero = Príncipe de Asturias. Extinguidas las líneas → Cortes. Abdicaciones y dudas → LEY ORGÁNICA."},{"law":"ce","art":"62","t":"Artículo 62.","sub":"Funciones del Rey — Sancionar, convocar y disolver, mando supremo de las FF. AA., Alto Patronazgo.","mat":"Funciones del Rey","cl":"Sancionar, convocar y disolver, mando supremo de las FF. AA., Alto Patronazgo.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Funciones del Rey (art. 62): SANCIONA y promulga, CONVOCA y disuelve, convoca REFERÉNDUM, PROPONE e inviste Presidente, NOMBRA y separa ministros, EXPIDE decretos, CONFIERE empleos y honores, informado y PRESIDE el Consejo de Ministros a petición, MANDO SUPREMO de las FF. AA., GRACIA (sin indultos generales) y ALTO PATRONAZGO de las Reales Academias. «Dirigir la política» NO: es del Gobierno (97)."},{"law":"ce","art":"64","t":"Artículo 64.","sub":"Refrendo — Presidente del Gobierno / Ministros; el Presidente del Congreso refrenda la propuesta e investidura del 99.","mat":"Refrendo","cl":"Presidente del Gobierno / Ministros; el Presidente del Congreso refrenda la propuesta e investidura del 99.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Refrendo: actos del Rey → Presidente del Gobierno y Ministros. Propuesta e investidura del Presidente y disolución del art. 99.5 → PRESIDENTE DEL CONGRESO. «Quien refrenda, responde». El Rey: inviolable e irresponsable."},{"law":"ce","art":"69","t":"Artículo 69.","sub":"Senado — Representación territorial; 4 senadores por provincia.","mat":"Senado","cl":"Representación territorial; 4 senadores por provincia.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Senado = Cámara de REPRESENTACIÓN TERRITORIAL. «4 por provincia»; islas mayores 3; menores 1; Ceuta y Melilla 2 cada una; CCAA: 1 + 1 por cada millón de habitantes."},{"law":"ce","art":"122","t":"Artículo 122.","sub":"CGPJ — Presidente del TS + 20 miembros; 5 años.","mat":"CGPJ","cl":"Presidente del TS + 20 miembros; 5 años.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"CGPJ «1 + 20, 5 años»: Presidente del TS + 20 vocales nombrados por el Rey por 5 años: 12 jueces y magistrados + 8 juristas de más de 15 años (4 Congreso y 4 Senado por 3/5)."},{"law":"ce","art":"141","t":"Artículo 141.","sub":"Provincia — Personalidad jurídica propia; agrupación de municipios; alteración por ley orgánica.","mat":"Provincia","cl":"Personalidad jurídica propia; agrupación de municipios; alteración por ley orgánica.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Provincia: entidad local con personalidad jurídica propia; agrupación de municipios y división territorial del Estado; cambio de límites por LEY ORGÁNICA; gobierno: Diputaciones; islas: Cabildos o Consejos."},{"law":"ce","art":"153","t":"Artículo 153.","sub":"Control de las CCAA — TC, Gobierno (previo Consejo de Estado), contencioso, Tribunal de Cuentas.","mat":"Control de las CCAA","cl":"TC, Gobierno (previo Consejo de Estado), contencioso, Tribunal de Cuentas.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Control de las CCAA «TC-GO-CA-TCU»: TC (leyes), GObierno con dictamen del Consejo de Estado (funciones delegadas del 150.2), Contencioso-Administrativo (administración y reglamentos), Tribunal de CUentas (economía y presupuesto)."},{"law":"ce","art":"159","t":"Artículo 159.","sub":"Tribunal Constitucional — 12 miembros: 4+4 (3/5) + 2 Gobierno + 2 CGPJ; 9 años; renovación por tercios cada 3.","mat":"Tribunal Constitucional","cl":"12 miembros: 4+4 (3/5) + 2 Gobierno + 2 CGPJ; 9 años; renovación por tercios cada 3.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"TC «12 = 4+4+2+2»: 4 Congreso (3/5), 4 Senado (3/5), 2 Gobierno, 2 CGPJ. Juristas con más de 15 años; mandato de 9 años; renovación por terceras partes cada 3. Truco «12-15-9-3»."},{"law":"escv","art":"25","t":"Artículo 25.","sub":"Funcionamiento — Reglamento por mayoría absoluta; leyes de bases y presupuestos no delegables; 2 periodos, mín. 8 meses.","mat":"Funcionamiento","cl":"Reglamento por mayoría absoluta; leyes de bases y presupuestos no delegables; 2 periodos, mín. 8 meses.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Les Corts: Reglamento por MAYORÍA ABSOLUTA; eligen Presidente, Mesa y Diputación Permanente; funcionan en Pleno y Comisiones; NO delegables en Comisión: reforma del Estatuto, leyes de bases, presupuestos e instituciones (las de mayoría cualificada)."},{"law":"escv","art":"29","t":"Artículo 29.","sub":"Consell — Órgano colegiado; potestad ejecutiva y reglamentaria; sede en Valencia.","mat":"Consell","cl":"Órgano colegiado; potestad ejecutiva y reglamentaria; sede en Valencia.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Consell: órgano colegiado de gobierno con potestad EJECUTIVA y REGLAMENTARIA; consellers nombrados por el President; sede en Valencia, pero sus servicios pueden descentralizarse por todo el territorio."},{"law":"lbrl","art":"25","t":"Artículo 25.","sub":"Competencias propias — Lista 25.2.","mat":"Competencias propias","cl":"Lista 25.2.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Competencias propias (25.2): ¡las de cada día en el pueblo! Urbanismo, medio ambiente urbano, agua, infraestructura viaria, policía local, tráfico, protección civil, residuos, cementerios, mercados, transporte urbano, cultura, deporte, turismo, ferias, servicios sociales (atención inmediata), vigilancia de la escolaridad. Siempre determinadas por LEY."},{"law":"lbrl_cv","art":"139","t":"Artículo 139. Participación en sesiones.","sub":"Sesiones del Pleno — Régimen de sesiones en la CV.","mat":"Sesiones del Pleno","cl":"Régimen de sesiones en la CV.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Plenos en la CV: «puertas abiertas»: sesiones PÚBLICAS, acceso de los medios según el reglamento orgánico, respetando el art. 20 CE. En las comisiones, vecinos y asociaciones pueden ser oídos sobre un tema concreto."},{"law":"lbrl_cv","art":"178","t":"Artículo 178. Protección y defensa del patrimonio.","sub":"Defensa de bienes — Allanamiento y defensa de bienes.","mat":"Defensa de bienes","cl":"Allanamiento y defensa de bienes.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Defensa del patrimonio: «PROTEGE, INSCRIBE, DEFIENDE»: obligación de proteger y defender sus bienes, inscribirlos en el Registro y ejercer acciones. Cualquier vecino puede requerir que se ejerzan. Concesionarios y personal custodio también están obligados."},{"law":"lbrl_cv","art":"181","t":"Artículo 181. Desafectación de bienes comunales.","sub":"Bienes comunales — Desafectación del carácter comunal.","mat":"Bienes comunales","cl":"Desafectación del carácter comunal.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Comunales: «10 años sin uso → patrimonial»: si no se han disfrutado como comunales en más de 10 años, pueden desafectarse con información pública + mayoría absoluta + aprobación de la Generalitat."},{"law":"lbrl_cv","art":"189","t":"Artículo 189. Permutas.","sub":"Permuta — Requisitos de la permuta de bienes patrimoniales.","mat":"Permuta","cl":"Requisitos de la permuta de bienes patrimoniales.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Permuta en la CV: necesidad o conveniencia + equivalencia de valores; diferencia máxima del 50 % (en el RBEL estatal, 40 %) con compensación económica. Truco: «la CV es más generosa: 50 frente a 40»."},{"law":"haciendalocal","art":"14","t":"Artículo 14. Revisión de actos en vía administrativa.","sub":"Recurso de reposición — Único recurso contra actos tributarios; 1 mes.","mat":"Recurso de reposición","cl":"Único recurso contra actos tributarios; 1 mes.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Tributos locales: «REPOSICIÓN y punto»: único recurso administrativo; 1 mes para interponer; 1 mes para resolver (silencio negativo); no suspende salvo garantía; después, contencioso-administrativo."},{"law":"haciendalocal","art":"21","t":"Artículo 21. Supuestos de no sujeción y de exención.","sub":"Tasas prohibidas — Aguas en fuentes, alumbrado, vigilancia, limpieza vía pública, enseñanza obligatoria.","mat":"Tasas prohibidas","cl":"Aguas en fuentes, alumbrado, vigilancia, limpieza vía pública, enseñanza obligatoria.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Tasas PROHIBIDAS «A-A-V-P-L-E»: Aguas en fuentes públicas, Alumbrado de vías públicas, Vigilancia pública general, Protección civil, Limpieza de la vía pública, Enseñanza obligatoria. Truco: lo que es de todos y nadie elige no se cobra."},{"law":"lprevencion","art":"21","t":"Artículo 21. Riesgo grave e inminente.","sub":"Riesgo grave e inminente — Interrumpir y abandonar; comunicación en 24 horas.","mat":"Riesgo grave e inminente","cl":"Interrumpir y abandonar; comunicación en 24 horas.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Riesgo grave e inminente: informar, adoptar medidas, permitir interrumpir y abandonar. Si el empresario no actúa: paralización por mayoría de los representantes (o de los delegados de prevención si urge) → autoridad laboral anula o ratifica en 24 h. Sin perjuicio salvo mala fe o negligencia grave."},{"law":"lprevencion","art":"29","t":"Artículo 29. Obligaciones de los trabajadores en materia de prevención de riesgos.","sub":"Obligaciones de los trabajadores — Uso adecuado, informar, cooperar.","mat":"Obligaciones de los trabajadores","cl":"Uso adecuado, informar, cooperar.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Obligaciones del trabajador «U-U-NO-I-C-C»: Usar bien las máquinas, Usar los EPI, NO desactivar los dispositivos de seguridad, Informar de los riesgos, Contribuir al cumplimiento, Cooperar con el empresario. Incumplir = incumplimiento laboral (o falta disciplinaria si es funcionario)."},{"law":"lprevencion","art":"31","t":"Artículo 31. Servicios de prevención.","sub":"Servicios de prevención — Concepto y funciones.","mat":"Servicios de prevención","cl":"Concepto y funciones.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Servicio de prevención = conjunto de medios humanos y materiales para la prevención; puede ser propio o ajeno (este, acreditado por la autoridad laboral). Funciones: diseñar y evaluar planes, priorizar, informar y formar, primeros auxilios, VIGILANCIA DE LA SALUD."},{"law":"leyigualdaMyH","art":"3","t":"Artículo 3. El principio de igualdad de trato entre mujeres y hombres.","sub":"Igualdad de trato — Ausencia de discriminación directa o indirecta.","mat":"Igualdad de trato","cl":"Ausencia de discriminación directa o indirecta.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Igualdad de trato = AUSENCIA de toda discriminación directa o indirecta por razón de sexo, especialmente por «MA-FA-CI»: MAternidad, obligaciones FAmiliares y estado CIvil."},{"law":"leyigualdaMyH","art":"13","t":"Artículo 13. Prueba.","sub":"Prueba — Carga en la persona demandada; no en procesos penales.","mat":"Prueba","cl":"Carga en la persona demandada; no en procesos penales.","w":1.0,"n":1,"ex":1,"alc":0,"pr":"C","note":"Prueba «INVERTIDA»: si se alega discriminación por sexo, la persona demandada prueba que no la hubo y que la medida era proporcionada. NUNCA en procesos penales."},{"law":"ce","art":"55","t":"Artículo 55.","sub":"Suspensión de derechos — Lista exacta de artículos suspendibles; el 17.3 no se suspende en el estado de excepción.","mat":"Suspensión de derechos","cl":"Lista exacta de artículos suspendibles; el 17.3 no se suspende en el estado de excepción.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Suspensión en excepción y sitio: «17-18-19-20-21-28-37»: arts. 17, 18.2 y 3, 19, 20.1.a) y d) y 5, 21, 28.2 (huelga) y 37.2 (conflicto colectivo). En excepción, el 17.3 (abogado) NO. Individual por terrorismo: 17.2 y 18.2 y 3, mediante LO y control judicial."},{"law":"ce","art":"81","t":"Artículo 81.","sub":"Leyes orgánicas — Mayoría absoluta del Congreso en votación final.","mat":"Leyes orgánicas","cl":"Mayoría absoluta del Congreso en votación final.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Leyes orgánicas: «DE-ES-RE + las que diga la CE»: Derechos fundamentales, EStatutos, Régimen electoral general. Aprobación: MAYORÍA ABSOLUTA del Congreso en votación final sobre el conjunto. No admiten delegación legislativa, decreto-ley ni ILP."},{"law":"ce","art":"86","t":"Artículo 86.","sub":"Decreto-ley — Extraordinaria y urgente necesidad; convalidación en 30 días.","mat":"Decreto-ley","cl":"Extraordinaria y urgente necesidad; convalidación en 30 días.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Decreto-ley: «extraordinaria y urgente necesidad»; límites «IN-DE-CA-E» (INstituciones básicas, DErechos del Título I, CCAA, Electoral general). Convalidación por el Congreso en 30 días; puede tramitarse como proyecto de ley urgente."},{"law":"ce","art":"90","t":"Artículo 90.","sub":"Senado y leyes — 2 meses para veto/enmiendas; 20 días naturales si es urgente; veto: mayoría absoluta.","mat":"Senado y leyes","cl":"2 meses para veto/enmiendas; 20 días naturales si es urgente; veto: mayoría absoluta.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Senado: «2 meses / 20 días si urge». Veto por mayoría absoluta; el Congreso lo levanta por mayoría absoluta o, a los 2 meses, por simple. Enmiendas: el Congreso las acepta o no por mayoría simple."},{"law":"ce","art":"116","t":"Artículo 116.","sub":"Estados excepcionales — Alarma 15 días; excepción 30 + 30; sitio: mayoría absoluta del Congreso.","mat":"Estados excepcionales","cl":"Alarma 15 días; excepción 30 + 30; sitio: mayoría absoluta del Congreso.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Estados: «ALARMA 15 – EXCEPCIÓN 30+30 – SITIO absoluta»: alarma por el Gobierno por 15 días, dando cuenta al Congreso (prórroga con autorización); excepción por el Gobierno con autorización previa del Congreso, 30 días + 30; sitio: mayoría absoluta del Congreso a propuesta exclusiva del Gobierno. El Congreso no puede disolverse."},{"law":"ce","art":"134","t":"Artículo 134.","sub":"Presupuestos — 3 meses antes; prórroga automática; no crean tributos.","mat":"Presupuestos","cl":"3 meses antes; prórroga automática; no crean tributos.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"PGE: «elabora el Gobierno, aprueban las Cortes»; anuales; presentados 3 meses antes de que expiren los anteriores; prórroga automática; la ley de presupuestos NO crea tributos (solo los modifica si lo prevé una ley tributaria)."},{"law":"ce","art":"155","t":"Artículo 155.","sub":"Coerción estatal — Requerimiento previo; mayoría absoluta del Senado.","mat":"Coerción estatal","cl":"Requerimiento previo; mayoría absoluta del Senado.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Coerción estatal: «REQUIERO, SENADO, INSTRUYO»: requerimiento al Presidente de la CA → si no se atiende, aprobación del Senado por mayoría absoluta → el Gobierno puede dar instrucciones a todas las autoridades de la CA."},{"law":"ce","art":"162","t":"Artículo 162.","sub":"Legitimación ante el TC — 50 diputados/senadores, Presidente, Defensor; amparo: interés legítimo.","mat":"Legitimación ante el TC","cl":"50 diputados/senadores, Presidente, Defensor; amparo: interés legítimo.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Inconstitucionalidad «P-D-50-50-CCAA»: Presidente del Gobierno, Defensor del Pueblo, 50 diputados, 50 senadores, órganos ejecutivos y asambleas de las CCAA. Amparo: persona con interés legítimo, Defensor del Pueblo y MINISTERIO FISCAL."},{"law":"escv","art":"6","t":"Artículo 6.","sub":"Lenguas — Lengua propia: valenciano; cooficial con el castellano; AVL como institución normativa (6.8).","mat":"Lenguas","cl":"Lengua propia: valenciano; cooficial con el castellano; AVL como institución normativa (6.8).","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Lenguas: valenciano = lengua PROPIA; cooficial con el castellano; nadie puede ser discriminado por su lengua; especial protección a la recuperación del valenciano; AVL = institución normativa (6.8)."},{"law":"escv","art":"28","t":"Artículo 28.","sub":"Censura y disolución — Moción: mayoría absoluta y 1/5 de diputados; 5 días.","mat":"Censura y disolución","cl":"Moción: mayoría absoluta y 1/5 de diputados; 5 días.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Moción de censura en Les Corts: «1/5 la propone, absoluta la aprueba, con candidato». El President dirige el Consell, ostenta la más alta representación de la Comunitat y la ordinaria del Estado; responde ante Les Corts."},{"law":"escv","art":"38","t":"Artículo 38. El Síndic de Greuges.","sub":"Síndic de Greuges — Alto Comisionado de Les Corts.","mat":"Síndic de Greuges","cl":"Alto Comisionado de Les Corts.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Síndic de Greuges = el «Defensor del Pueblo valenciano»: Alto Comisionado de Les Corts, designado por ellas; defiende los Títulos I CE y II EACV; informe ANUAL a Les Corts."},{"law":"escv","art":"43","t":"Artículo 43. El Consell Jurídic Consultiu.","sub":"Consell Jurídic Consultiu — Órgano consultivo supremo.","mat":"Consell Jurídic Consultiu","cl":"Órgano consultivo supremo.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Consell Jurídic Consultiu = el «Consejo de Estado valenciano»: órgano consultivo SUPREMO del Consell, de la Administración autonómica y, en su caso, de los entes locales, en materia jurídica."},{"law":"escv","art":"81","t":"Artículo 81.","sub":"Reforma del Estatuto — Consell, 1/3 de Les Corts, 2 grupos o Cortes Generales; 2/3; mayoría simple si solo amplía competencias.","mat":"Reforma del Estatuto","cl":"Consell, 1/3 de Les Corts, 2 grupos o Cortes Generales; 2/3; mayoría simple si solo amplía competencias.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Reforma del EACV: iniciativa «C-1/3-2G-CG»: Consell, 1/3 de Les Corts, 2 Grupos Parlamentarios o Cortes Generales. Aprobación por 2/3 de Les Corts (simple si solo amplía competencias) + Cortes Generales mediante LO."},{"law":"lbrl","art":"4","t":"Artículo 4.","sub":"Potestades — Reglamentaria, autoorganización, tributaria, financiera, planificación, expropiatoria, sancionadora…","mat":"Potestades","cl":"Reglamentaria, autoorganización, tributaria, financiera, planificación, expropiatoria, sancionadora…","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Potestades «RE-AU-TRI-FI-PRO-EX-INV-DES-REC-PRE-EJE-SAN-REV-PRELA-INEM»: Reglamentaria y de autoorganización; tributaria y financiera; programación; expropiatoria e investigación, deslinde y recuperación de oficio; presunción de legitimidad y ejecutividad; ejecución forzosa y sancionadora; revisión de oficio; prelaciones de Hacienda; inembargabilidad. Lo que NUNCA tienen: potestad LEGISLATIVA."},{"law":"lbrl","art":"52","t":"Artículo 52.","sub":"Fin de la vía administrativa — Pleno, Alcaldes y JGL; reposición potestativa.","mat":"Fin de la vía administrativa","cl":"Pleno, Alcaldes y JGL; reposición potestativa.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Fin de la vía administrativa: «PLENO, ALCALDE, JUNTA = punto final» (salvo que una ley sectorial exija aprobación estatal o autonómica), también lo que se resuelve por delegación de ellos o lo que diga una ley. Recurso: reposición potestativa o contencioso directo."},{"law":"lbrl","art":"92","t":"Artículo 92. Funcionarios al servicio de la Administración local.","sub":"Funcionarios — Potestades públicas reservadas a funcionarios de carrera.","mat":"Funcionarios","cl":"Potestades públicas reservadas a funcionarios de carrera.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Puestos locales: por regla general, FUNCIONARIOS. Exclusivamente funcionarios: potestades públicas, salvaguarda de intereses generales, fe pública, control y fiscalización interna, contabilidad, tesorería, recaudación, inspección y sanción. Secretaría, intervención y tesorería → habilitados nacionales (92 bis)."},{"law":"lbrl","art":"121","t":"Artículo 121. Ámbito de aplicación.","sub":"Grandes ciudades — Más de 250.000; capitales de más de 175.000; capitales autonómicas; más de 75.000 con circunstancias especiales.","mat":"Grandes ciudades","cl":"Más de 250.000; capitales de más de 175.000; capitales autonómicas; más de 75.000 con circunstancias especiales.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Gran población «250 – 175 – capital – 75»: más de 250.000; capitales de provincia de más de 175.000; capitales de provincia, autonómicas o sedes de instituciones; más de 75.000 con circunstancias especiales si lo deciden las Asambleas autonómicas a iniciativa del Ayuntamiento. Alcoi (≈60.000) NO entra."},{"law":"lbrl_cv","art":"24","t":"Artículo 24. Padrón de habitantes.","sub":"Padrón — Remisión y datos del Padrón en la CV.","mat":"Padrón","cl":"Remisión y datos del Padrón en la CV.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Padrón (CV): registro administrativo de los vecinos; PRUEBA de residencia y domicilio; lo forma, actualiza, revisa y custodia el AYUNTAMIENTO; los datos obligatorios son los de la ley básica estatal."},{"law":"lprevencion","art":"4","t":"Artículo 4. Definiciones.","sub":"Definiciones — Prevención, riesgo laboral, daños, riesgo grave e inminente.","mat":"Definiciones","cl":"Prevención, riesgo laboral, daños, riesgo grave e inminente.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Definiciones «PRE-RIE-DA-GRI»: PREvención (actividades en todas las fases); RIEsgo laboral (posibilidad de daño; gravedad = probabilidad + severidad); DAños (enfermedades, patologías, lesiones); riesgo Grave e Inminente (probable en un futuro inmediato con daño grave)."},{"law":"lprevencion","art":"38","t":"Artículo 38. Comité de Seguridad y Salud.","sub":"Comité de Seguridad y Salud — Paritario y colegiado; 50 o más trabajadores.","mat":"Comité de Seguridad y Salud","cl":"Paritario y colegiado; 50 o más trabajadores.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Comité de Seguridad y Salud: «50-PARITARIO-TRIMESTRAL»: empresas o centros de 50 o más; paritario (Delegados de Prevención = representantes del empresario); se reúne trimestralmente; delegados sindicales y técnicos con voz y sin voto."},{"law":"leyigualdaMyH","art":"8","t":"Artículo 8. Discriminación por embarazo o maternidad.","sub":"Embarazo y maternidad — Discriminación directa.","mat":"Embarazo y maternidad","cl":"Discriminación directa.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Embarazo/maternidad = DISCRIMINACIÓN DIRECTA (siempre). Truco «8 = barriga»: el número 8 parece una embarazada."},{"law":"leyigualdaMyH","art":"11","t":"Artículo 11. Acciones positivas.","sub":"Acciones positivas — Razonables y proporcionadas.","mat":"Acciones positivas","cl":"Razonables y proporcionadas.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Acciones positivas: medidas específicas a favor de las mujeres para corregir desigualdades patentes; TEMPORALES («mientras subsistan»), RAZONABLES y PROPORCIONADAS; también pueden adoptarlas los particulares."},{"law":"leyigualdaMyH","art":"45","t":"Artículo 45. Elaboración y aplicación de los planes de igualdad.","sub":"Planes de igualdad — Empresas de 50 o más trabajadores.","mat":"Planes de igualdad","cl":"Empresas de 50 o más trabajadores.","w":0,"n":0,"ex":0,"alc":0,"pr":"C","note":"Planes de igualdad: OBLIGATORIOS en empresas de 50 o más trabajadores, cuando lo diga el convenio, o cuando lo imponga la autoridad laboral en sustitución de sanciones accesorias. Voluntarios en el resto. Truco «50 = plan»."}];
window.RANKING3940=[{"law":"lpac","art":"47","t":"Artículo 47. Nulidad de pleno derecho.","mat":"Nulidad de pleno derecho","cl":"Lesionen derechos susceptibles de amparo; órgano manifiestamente incompetente por materia o territorio; contenido imposible; constitutivos de infracción penal; prescindiendo total y absolutamente del procedimiento o de las normas de órganos colegiados; facultades sin requisitos esenciales; otros por ley. Disposiciones nulas (47.2).","note":"Nulidad = «DOCE PEO»: Derechos de amparo · Órgano manifiestamente incompetente por MATERIA o TERRITORIO (¡jerarquía NO, eso es anulable!) · Contenido imposible · Delito · Prescindir TOTAL y absolutamente del procedimiento · Facultades sin requisitos Esenciales · Otros por Ley. Las disposiciones (47.2) también son nulas si vulneran la CE, leyes o normas superiores, regulan materias reservadas a ley o establecen retroactividad sancionadora desfavorable.","n":16,"ex":14,"alc":1,"web":2,"w":43.0,"pr":"A","sub":"Nulidad de pleno derecho — Lesionen derechos susceptibles de amparo; órgano manifiestamente incompetente por materia o territorio; contenido imposible; constitutivos de infracción penal; prescindiendo total y absolutamente del procedimiento o de las normas de órganos colegiados; facultades sin requisitos esenciales; otros por ley. Disposiciones nulas (47.2)."},{"law":"lpac","art":"30","t":"Artículo 30. Cómputo de plazos.","mat":"Cómputo de plazos","cl":"Horas: hábiles (todas salvo sábados, domingos y festivos), máximo 24 h. Días: hábiles salvo que se diga naturales; desde el día siguiente. Meses/años: de fecha a fecha. Último día inhábil: primer hábil siguiente. Hábil en un sitio e inhábil en otro: inhábil.","note":"Plazos: horas hábiles (máximo 24 h; si es más, se expresan en días). Días = HÁBILES, sin sábados, domingos ni festivos. Se cuentan desde el día SIGUIENTE. Meses y años, de fecha a fecha; si no hay día equivalente, el último del mes. Si el último día es inhábil, se prorroga al primer hábil siguiente. Si un día es hábil donde reside el interesado e inhábil en la sede del órgano (o al revés), es INHÁBIL en todo caso.","n":14,"ex":11,"alc":0,"web":2,"w":36.5,"pr":"A","sub":"Cómputo de plazos — Horas: hábiles (todas salvo sábados, domingos y festivos), máximo 24 h. Días: hábiles salvo que se diga naturales; desde el día siguiente. Meses/años: de fecha a fecha. Último día inhábil: primer hábil siguiente. Hábil en un sitio e inhábil en otro: inhábil."},{"law":"lpac","art":"35","t":"Artículo 35. Motivación.","mat":"Motivación","cl":"Con sucinta referencia de hechos y fundamentos: actos que limiten derechos; resuelvan revisión de oficio, recursos, reclamaciones y arbitraje; se separen del criterio seguido o del dictamen; suspensión y medidas provisionales; urgencia, ampliación y actuaciones complementarias; rechazo de pruebas; terminación por imposibilidad y desistimiento de oficio; propuestas sancionadoras y de responsabilidad; discrecionales. Selectivos y concurrencia: según las bases.","note":"Motivación: «LiReSeSuUrPruTerPro…» → Limiten derechos · Resuelvan revisión de oficio, recursos y arbitraje · Se Separen del criterio precedente · Suspensión y medidas provisionales · Urgencia, ampliación y actuaciones complementarias · Rechacen Pruebas · Terminación por imposibilidad y desistimiento de la Administración · Propuestas en procedimientos sancionadores y de responsabilidad · potestades discrecionales.","n":11,"ex":11,"alc":0,"web":2,"w":33.5,"pr":"A","sub":"Motivación — Con sucinta referencia de hechos y fundamentos: actos que limiten derechos; resuelvan revisión de oficio, recursos, reclamaciones y arbitraje; se separen del criterio seguido o del dictamen; suspensión y medidas provisionales; urgencia, ampliación y actuaciones complementarias; rechazo de pruebas; terminación por imposibilidad y desistimiento de oficio; propuestas sancionadoras y de responsabilidad; discrecionales. Selectivos y concurrencia: según las bases."},{"law":"lpac","art":"41","t":"Artículo 41. Condiciones generales para la práctica de las notificaciones.","mat":"Condiciones generales de las notificaciones","cl":"Preferentemente electrónicas. En papel: comparecencia espontánea en oficina de asistencia o entrega directa por empleado público. Medios de pago nunca electrónicos. Rechazo: se tiene por efectuado el trámite. Varios cauces: vale la primera.","note":"Notificaciones: preferentemente electrónicas. En papel solo con comparecencia espontánea en la oficina de asistencia o con entrega directa por un empleado público. Medios de pago (cheques) NUNCA por vía electrónica. Rechazo = se tiene por efectuada. Si se notifica por varios cauces vale la PRIMERA.","n":11,"ex":10,"alc":0,"web":2,"w":32.0,"pr":"A","sub":"Condiciones generales de las notificaciones — Preferentemente electrónicas. En papel: comparecencia espontánea en oficina de asistencia o entrega directa por empleado público. Medios de pago nunca electrónicos. Rechazo: se tiene por efectuado el trámite. Varios cauces: vale la primera."},{"law":"lpac","art":"43","t":"Artículo 43. Práctica de las notificaciones a través de medios electrónicos.","mat":"Notificaciones electrónicas","cl":"Por comparecencia en la sede o en la dirección electrónica habilitada única. Practicada al acceder a su contenido. Rechazada a los 10 días NATURALES sin acceder. El aviso no es requisito de validez.","note":"Notificación electrónica: se practica por comparecencia en la sede o en la DEHú. Se entiende practicada al ACCEDER. Rechazada a los 10 días NATURALES sin acceso. El aviso al correo es informativo: su falta NO invalida la notificación.","n":11,"ex":10,"alc":0,"web":2,"w":32.0,"pr":"A","sub":"Notificaciones electrónicas — Por comparecencia en la sede o en la dirección electrónica habilitada única. Practicada al acceder a su contenido. Rechazada a los 10 días NATURALES sin acceder. El aviso no es requisito de validez."},{"law":"lpac","art":"107","t":"Artículo 107. Declaración de lesividad de actos anulables.","mat":"Declaración de lesividad","cl":"Actos favorables anulables: declaración de lesividad para impugnarlos en el contencioso. Dentro de 4 años; audiencia; 6 meses o caducidad. No recurrible. Entidades locales: el Pleno o el órgano colegiado superior.","note":"Lesividad «4-6-NR»: solo para actos FAVORABLES y ANULABLES. Plazo de 4 años desde que se dictó; caducidad a los 6 meses desde la iniciación; la declaración No es Recurrible. Exige audiencia previa. En entidades locales la declara el PLENO (o el órgano colegiado superior).","n":10,"ex":10,"alc":0,"web":2,"w":31.0,"pr":"A","sub":"Declaración de lesividad — Actos favorables anulables: declaración de lesividad para impugnarlos en el contencioso. Dentro de 4 años; audiencia; 6 meses o caducidad. No recurrible. Entidades locales: el Pleno o el órgano colegiado superior."},{"law":"lpac","art":"21","t":"Artículo 21. Obligación de resolver.","mat":"Obligación de resolver","cl":"Obligación de dictar resolución expresa y notificarla. Plazo máximo el de la norma; no puede exceder de 6 meses salvo ley o Derecho UE; si no lo fija, 3 meses. Exentos: pacto o convenio y derechos sujetos solo a declaración responsable o comunicación.","note":"Obligación de resolver: «6-3». Máximo 6 meses salvo ley o Derecho UE; si la norma no fija plazo, 3 meses. Exentos: pacto o convenio y declaración responsable o comunicación. Se cuenta desde el acuerdo de iniciación (de oficio) o desde la entrada en el registro del órgano competente (a solicitud).","n":11,"ex":9,"alc":0,"web":2,"w":30.5,"pr":"A","sub":"Obligación de resolver — Obligación de dictar resolución expresa y notificarla. Plazo máximo el de la norma; no puede exceder de 6 meses salvo ley o Derecho UE; si no lo fija, 3 meses. Exentos: pacto o convenio y derechos sujetos solo a declaración responsable o comunicación."},{"law":"lpac","art":"5","t":"Artículo 5. Representación.","mat":"Representación","cl":"Capacidad de obrar para ser representante; acreditar la representación para solicitudes, declaraciones responsables, recursos, desistir y renunciar; en mero trámite se presume; 10 días para subsanar.","note":"Representación: hay que acreditarla para «SoDeReDeRe»: Solicitudes, Declaraciones responsables y comunicaciones, REcursos, DEsistir y REnunciar. En los actos de mero trámite se PRESUME. Falta o insuficiencia: 10 días para subsanar.","n":12,"ex":8,"alc":0,"web":2,"w":30.0,"pr":"A","sub":"Representación — Capacidad de obrar para ser representante; acreditar la representación para solicitudes, declaraciones responsables, recursos, desistir y renunciar; en mero trámite se presume; 10 días para subsanar."},{"law":"lpac","art":"52","t":"Artículo 52. Convalidación.","mat":"Convalidación","cl":"La Administración puede convalidar los actos ANULABLES subsanando los vicios. Efecto desde la fecha de la convalidación (salvo retroactividad del 39.3). Incompetencia no determinante de nulidad: la convalida el superior jerárquico; falta de autorización: otorgándola.","note":"Convalidación: solo actos ANULABLES. Produce efecto desde su fecha (salvo la retroactividad del 39.3). Incompetencia no determinante de nulidad: la convalida el superior jerárquico. Falta de autorización: se convalida otorgándola.","n":9,"ex":9,"alc":0,"web":2,"w":28.5,"pr":"A","sub":"Convalidación — La Administración puede convalidar los actos ANULABLES subsanando los vicios. Efecto desde la fecha de la convalidación (salvo retroactividad del 39.3). Incompetencia no determinante de nulidad: la convalida el superior jerárquico; falta de autorización: otorgándola."},{"law":"lpac","art":"125","t":"Artículo 125. Objeto y plazos.","mat":"Recurso extraordinario de revisión: objeto y plazos","cl":"Contra actos firmes, ante el mismo órgano: error de hecho que resulte de documentos del expediente (4 años desde la notificación); documentos de valor esencial; documentos o testimonios declarados falsos por sentencia firme; prevaricación, cohecho, violencia u otra conducta punible por sentencia firme (3 meses).","note":"Recurso extraordinario de revisión «E-D-F-P»: Error de hecho (4 años), Documentos esenciales nuevos, Falsedad declarada en sentencia, Prevaricación o cohecho declarados en sentencia (en estos tres, 3 meses desde el conocimiento o la firmeza). Solo contra actos FIRMES y ante el mismo órgano.","n":9,"ex":9,"alc":1,"web":2,"w":28.5,"pr":"A","sub":"Recurso extraordinario de revisión: objeto y plazos — Contra actos firmes, ante el mismo órgano: error de hecho que resulte de documentos del expediente (4 años desde la notificación); documentos de valor esencial; documentos o testimonios declarados falsos por sentencia firme; prevaricación, cohecho, violencia u otra conducta punible por sentencia firme (3 meses)."},{"law":"lpac","art":"39","t":"Artículo 39. Efectos.","mat":"Efectos","cl":"Válidos y eficaces desde la fecha en que se dicten salvo otra cosa. Eficacia demorada (notificación, publicación, aprobación superior). Retroactividad excepcional: sustitución de actos anulados y efectos favorables sin lesionar a terceros.","note":"Efectos: desde que se DICTAN (salvo que se disponga otra cosa). Eficacia demorada por notificación, publicación o aprobación superior. Retroactividad EXCEPCIONAL: en sustitución de actos ANULADOS o con efectos FAVORABLES, si los hechos ya existían y no se lesiona a terceros.","n":9,"ex":8,"alc":0,"web":2,"w":27.0,"pr":"A","sub":"Efectos — Válidos y eficaces desde la fecha en que se dicten salvo otra cosa. Eficacia demorada (notificación, publicación, aprobación superior). Retroactividad excepcional: sustitución de actos anulados y efectos favorables sin lesionar a terceros."},{"law":"lpac","art":"40","t":"Artículo 40. Notificación.","mat":"Notificación","cl":"Se notifican las resoluciones y actos que afecten a derechos e intereses, en 10 días desde que se dictan, con texto íntegro, si pone fin a la vía administrativa, recursos, órgano y plazo. Notificación defectuosa: efectos desde que el interesado se da por enterado. Basta el intento con texto íntegro para cumplir el plazo máximo.","note":"Notificación «10 días»: se cursa dentro de los 10 días desde que se dicta el acto. Contiene el texto íntegro, si pone fin a la vía administrativa, los recursos, el órgano y el plazo. Notificación defectuosa = efectos desde que el interesado se da por enterado. Para cumplir el plazo de resolver basta el INTENTO de notificación debidamente acreditado.","n":8,"ex":8,"alc":0,"web":2,"w":26.0,"pr":"A","sub":"Notificación — Se notifican las resoluciones y actos que afecten a derechos e intereses, en 10 días desde que se dictan, con texto íntegro, si pone fin a la vía administrativa, recursos, órgano y plazo. Notificación defectuosa: efectos desde que el interesado se da por enterado. Basta el intento con texto íntegro para cumplir el plazo máximo."},{"law":"lpac","art":"14","t":"Artículo 14. Derecho y obligación de relacionarse electrónicamente con las Administraciones Públicas.","mat":"Obligados a relacionarse electrónicamente","cl":"Personas físicas eligen (y pueden cambiar). Obligados: personas jurídicas, entidades sin personalidad, profesionales colegiados en su actividad, representantes de obligados y empleados públicos por razón de su condición.","note":"Obligados (14.2) «PEPRE-RE-EM»: Personas jurídicas, Entidades sin personalidad, PRofesionales COLEGIADOS (notarios y registradores incluidos), REpresentantes de un obligado, EMpleados públicos (por su condición). Las personas físicas ELIGEN y pueden cambiar en cualquier momento.","n":8,"ex":7,"alc":0,"web":2,"w":24.5,"pr":"A","sub":"Obligados a relacionarse electrónicamente — Personas físicas eligen (y pueden cambiar). Obligados: personas jurídicas, entidades sin personalidad, profesionales colegiados en su actividad, representantes de obligados y empleados públicos por razón de su condición."},{"law":"lpac","art":"81","t":"Artículo 81. Solicitud de informes y dictámenes en los procedimientos de responsabilidad patrimonial.","mat":"Informes en responsabilidad patrimonial","cl":"Informe del servicio cuyo funcionamiento causó la lesión (10 días). Dictamen del Consejo de Estado u órgano consultivo autonómico cuando la cuantía sea igual o superior a 50.000 euros (o lo que fije la CCAA); dictamen en 2 meses.","note":"Responsabilidad patrimonial «10-50-2»: informe del servicio en 10 días; dictamen del Consejo de Estado u órgano autonómico si la cuantía es ≥ 50.000 €; el dictamen se emite en 2 meses. El instructor remite la propuesta en 10 días desde el fin de la audiencia.","n":8,"ex":7,"alc":1,"web":2,"w":24.5,"pr":"A","sub":"Informes en responsabilidad patrimonial — Informe del servicio cuyo funcionamiento causó la lesión (10 días). Dictamen del Consejo de Estado u órgano consultivo autonómico cuando la cuantía sea igual o superior a 50.000 euros (o lo que fije la CCAA); dictamen en 2 meses."},{"law":"lpac","art":"96","t":"Artículo 96. Tramitación simplificada del procedimiento administrativo común.","mat":"Tramitación simplificada","cl":"De oficio o a solicitud, por interés público o falta de complejidad. Si un interesado se opone expresamente: ordinaria. Resolución en 30 días. Trámites limitados. Sancionador: infracción leve.","note":"Tramitación simplificada: se resuelve en 30 DÍAS. Oposición expresa de un interesado = ordinaria. Solicitud desestimable en 5 días sin recurso. En sanciones, cuando la infracción es LEVE.","n":8,"ex":7,"alc":0,"web":2,"w":24.5,"pr":"A","sub":"Tramitación simplificada — De oficio o a solicitud, por interés público o falta de complejidad. Si un interesado se opone expresamente: ordinaria. Resolución en 30 días. Trámites limitados. Sancionador: infracción leve."},{"law":"lpac","art":"112","t":"Artículo 112. Objeto y clases.","mat":"Objeto y clases de recursos","cl":"Contra resoluciones y actos de trámite cualificados (deciden el fondo, imposibilitan continuar, producen indefensión o perjuicio irreparable): alzada y reposición potestativo. Fundados en nulidad o anulabilidad. Contra disposiciones generales no cabe recurso administrativo. Procedimientos sustitutivos por ley.","note":"Recursos: alzada o reposición contra resoluciones y actos de trámite cualificados («DIIP»: Deciden el fondo, Imposibilitan continuar, Indefensión, Perjuicio irreparable). Contra disposiciones generales NO cabe recurso administrativo.","n":8,"ex":7,"alc":0,"web":2,"w":24.5,"pr":"A","sub":"Objeto y clases de recursos — Contra resoluciones y actos de trámite cualificados (deciden el fondo, imposibilitan continuar, producen indefensión o perjuicio irreparable): alzada y reposición potestativo. Fundados en nulidad o anulabilidad. Contra disposiciones generales no cabe recurso administrativo. Procedimientos sustitutivos por ley."},{"law":"lpac","art":"68","t":"Artículo 68. Subsanación y mejora de la solicitud.","mat":"Subsanación y mejora de la solicitud","cl":"10 días para subsanar; si no, desistido previa resolución. Ampliable hasta 5 días más (no en selectivos ni concurrencia competitiva). Presentación presencial de obligados: subsanar por vía electrónica.","note":"Subsanación: «10 + 5» días (los 5 de ampliación NO en selectivos ni concurrencia competitiva). Si no se subsana = DESISTIDO, previa resolución. Si un obligado presenta en papel: se le requiere subsanar electrónicamente y la fecha válida es la de la subsanación.","n":7,"ex":7,"alc":0,"web":2,"w":23.5,"pr":"A","sub":"Subsanación y mejora de la solicitud — 10 días para subsanar; si no, desistido previa resolución. Ampliable hasta 5 días más (no en selectivos ni concurrencia competitiva). Presentación presencial de obligados: subsanar por vía electrónica."},{"law":"lpac","art":"82","t":"Artículo 82. Trámite de audiencia.","mat":"Trámite de audiencia","cl":"Instruido el procedimiento e inmediatamente antes de la propuesta de resolución; plazo no inferior a 10 días ni superior a 15. Se puede prescindir si no figuran ni se tienen en cuenta otros hechos, alegaciones o pruebas que las del interesado.","note":"Audiencia «10-15»: entre 10 y 15 días, inmediatamente ANTES de la propuesta de resolución y antes del informe jurídico o del dictamen. Se puede prescindir si solo constan los hechos y alegaciones del propio interesado.","n":7,"ex":7,"alc":1,"web":2,"w":23.5,"pr":"A","sub":"Trámite de audiencia — Instruido el procedimiento e inmediatamente antes de la propuesta de resolución; plazo no inferior a 10 días ni superior a 15. Se puede prescindir si no figuran ni se tienen en cuenta otros hechos, alegaciones o pruebas que las del interesado."},{"law":"lpac","art":"88","t":"Artículo 88. Contenido.","mat":"Contenido de la resolución","cl":"Decide todas las cuestiones planteadas y derivadas. A solicitud: congruente, sin agravar la situación inicial. Motivada (art. 35), expresa recursos, órgano y plazo. No se puede abstener de resolver por silencio u oscuridad de las normas.","note":"Resolución: TODAS las cuestiones; si el procedimiento es a solicitud, CONGRUENTE con lo pedido y SIN reformatio in peius. Nunca puede negarse a resolver alegando silencio, oscuridad o insuficiencia de la norma (sí puede inadmitir solicitudes de derechos no previstos o manifiestamente carentes de fundamento).","n":7,"ex":7,"alc":0,"web":2,"w":23.5,"pr":"A","sub":"Contenido de la resolución — Decide todas las cuestiones planteadas y derivadas. A solicitud: congruente, sin agravar la situación inicial. Motivada (art. 35), expresa recursos, órgano y plazo. No se puede abstener de resolver por silencio u oscuridad de las normas."},{"law":"lpac","art":"95","t":"Artículo 95. Requisitos y efectos.","mat":"Caducidad","cl":"A solicitud, paralizado por causa del interesado: aviso y a los 3 meses caducidad y archivo. No caduca si es trámite no indispensable. No produce por sí sola la prescripción, pero los procedimientos caducados no la interrumpen. Se pueden conservar actos en el nuevo procedimiento.","note":"Caducidad por culpa del interesado: «AVISO + 3 MESES» → archivo. La caducidad no extingue la acción, pero el procedimiento caducado NO interrumpe la prescripción. No cabe si se trata de un trámite NO indispensable.","n":7,"ex":7,"alc":0,"web":2,"w":23.5,"pr":"A","sub":"Caducidad — A solicitud, paralizado por causa del interesado: aviso y a los 3 meses caducidad y archivo. No caduca si es trámite no indispensable. No produce por sí sola la prescripción, pero los procedimientos caducados no la interrumpen. Se pueden conservar actos en el nuevo procedimiento."},{"law":"lrjsp","art":"30","t":"Artículo 30. Prescripción.","mat":"Prescripción","cl":"Si la ley no fija plazos: infracciones muy graves 3 años, graves 2 años, leves 6 meses; sanciones muy graves 3 años, graves 2 años, leves 1 año. Infracciones: desde la comisión (continuadas, desde que cesa). Interrumpe la iniciación con conocimiento del interesado; se reanuda si se paraliza más de 1 mes por causa no imputable.","note":"Prescripción «3-2-6 / 3-2-1»: infracciones muy graves 3 años, graves 2, leves 6 MESES; sanciones muy graves 3 años, graves 2, leves 1 AÑO. Interrumpe la iniciación con conocimiento del interesado; vuelve a correr si se paraliza más de 1 MES por causa no imputable.","n":7,"ex":7,"alc":0,"web":2,"w":23.5,"pr":"A","sub":"Prescripción — Si la ley no fija plazos: infracciones muy graves 3 años, graves 2 años, leves 6 meses; sanciones muy graves 3 años, graves 2 años, leves 1 año. Infracciones: desde la comisión (continuadas, desde que cesa). Interrumpe la iniciación con conocimiento del interesado; se reanuda si se paraliza más de 1 mes por causa no imputable."},{"law":"lrjsp","art":"32","t":"Artículo 32. Principios de la responsabilidad.","mat":"Principios de la responsabilidad patrimonial","cl":"Indemnización de toda lesión en bienes y derechos por el funcionamiento normal o anormal de los servicios públicos, salvo fuerza mayor o deber jurídico de soportar. La anulación no presupone indemnización. Daño efectivo, evaluable económicamente e individualizado. Responsabilidad del Estado legislador.","note":"Daño indemnizable «E-E-I»: Efectivo, Evaluable económicamente e Individualizado. Funcionamiento NORMAL o ANORMAL. Excluidos: FUERZA MAYOR y daños que hay deber jurídico de soportar. Anular un acto NO da derecho automático a indemnización.","n":7,"ex":7,"alc":0,"web":2,"w":23.5,"pr":"A","sub":"Principios de la responsabilidad patrimonial — Indemnización de toda lesión en bienes y derechos por el funcionamiento normal o anormal de los servicios públicos, salvo fuerza mayor o deber jurídico de soportar. La anulación no presupone indemnización. Daño efectivo, evaluable económicamente e individualizado. Responsabilidad del Estado legislador."},{"law":"lpac","art":"3","t":"Artículo 3. Capacidad de obrar.","mat":"Capacidad de obrar","cl":"Personas físicas y jurídicas según el Código Civil; menores sin necesidad de asistencia en lo que permita el ordenamiento; grupos de afectados, uniones sin personalidad y patrimonios independientes SOLO si una ley lo declara.","note":"Capacidad de obrar: personas físicas o jurídicas según el Código Civil; menores en lo permitido; grupos de afectados y entidades sin personalidad SOLO si una ley lo declara.","n":8,"ex":8,"alc":0,"web":1,"w":23.0,"pr":"A","sub":"Capacidad de obrar — Personas físicas y jurídicas según el Código Civil; menores sin necesidad de asistencia en lo que permita el ordenamiento; grupos de afectados, uniones sin personalidad y patrimonios independientes SOLO si una ley lo declara."},{"law":"lpac","art":"24","t":"Artículo 24. Silencio administrativo en procedimientos iniciados a solicitud del interesado.","mat":"Silencio en procedimientos a solicitud","cl":"Regla: estimatorio. Desestimatorio: derecho de petición, transferencia de facultades de dominio o servicio público, medio ambiente, responsabilidad patrimonial, impugnación de actos y revisión de oficio. Estimatorio en alzada contra silencio. El estimatorio es acto finalizador; el desestimatorio solo permite recurrir.","note":"Silencio en procedimientos a solicitud: ESTIMATORIO por regla. Desestimatorio en «PeDoMaReReRe»: PEtición, DOminio y servicio público, Medio Ambiente, REsponsabilidad patrimonial, REcursos (impugnación) y REvisión de oficio. Excepción doble: en el recurso de alzada contra un silencio previo, el silencio es estimatorio.","n":7,"ex":6,"alc":0,"web":2,"w":22.0,"pr":"A","sub":"Silencio en procedimientos a solicitud — Regla: estimatorio. Desestimatorio: derecho de petición, transferencia de facultades de dominio o servicio público, medio ambiente, responsabilidad patrimonial, impugnación de actos y revisión de oficio. Estimatorio en alzada contra silencio. El estimatorio es acto finalizador; el desestimatorio solo permite recurrir."},{"law":"lpac","art":"42","t":"Artículo 42. Práctica de las notificaciones en papel.","mat":"Notificaciones en papel","cl":"Si no está el interesado: cualquier persona mayor de 14 años que se encuentre en el domicilio y haga constar su identidad. Si nadie se hace cargo: segundo intento dentro de los 3 días siguientes, en hora distinta (margen de 3 horas antes/después de las 15 h).","note":"Notificación en papel «14-3-15-3»: puede recogerla un mayor de 14 años que esté en el domicilio; segundo intento UNA sola vez, dentro de los 3 días siguientes, a distinta hora (si el primero fue antes de las 15 h, el segundo después, y viceversa, con al menos 3 horas de diferencia).","n":7,"ex":6,"alc":1,"web":2,"w":22.0,"pr":"A","sub":"Notificaciones en papel — Si no está el interesado: cualquier persona mayor de 14 años que se encuentre en el domicilio y haga constar su identidad. Si nadie se hace cargo: segundo intento dentro de los 3 días siguientes, en hora distinta (margen de 3 horas antes/después de las 15 h)."},{"law":"lpac","art":"53","t":"Artículo 53. Derechos del interesado en el procedimiento administrativo.","mat":"Derechos del interesado en el procedimiento","cl":"Conocer el estado de tramitación, sentido del silencio, órgano y actos; identificar autoridades; no presentar documentos no exigidos o ya aportados; alegar y aportar documentos en cualquier momento anterior a la audiencia; obtener información; asistencia de asesor; cumplir obligaciones de pago por medios electrónicos. Sancionadores: notificación de hechos e infracciones y presunción de no existencia de responsabilidad.","note":"Interesado «CO-ID-NO-AL-AS-PA»: COnocer el estado · IDentificar autoridades · NO aportar lo ya entregado · ALegar antes de la audiencia · ASesor · PAgar electrónicamente. En sancionadores, además: saber de qué le acusan y PRESUNCIÓN de inocencia («no existencia de responsabilidad»).","n":7,"ex":6,"alc":0,"web":2,"w":22.0,"pr":"A","sub":"Derechos del interesado en el procedimiento — Conocer el estado de tramitación, sentido del silencio, órgano y actos; identificar autoridades; no presentar documentos no exigidos o ya aportados; alegar y aportar documentos en cualquier momento anterior a la audiencia; obtener información; asistencia de asesor; cumplir obligaciones de pago por medios electrónicos. Sancionadores: notificación de hechos e infracciones y presunción de no existencia de responsabilidad."},{"law":"lpac","art":"48","t":"Artículo 48. Anulabilidad.","mat":"Anulabilidad","cl":"Cualquier infracción del ordenamiento, incluso la desviación de poder. Defecto de forma: solo si falta un requisito indispensable para el fin o causa indefensión. Fuera de plazo: solo si lo impone la naturaleza del término.","note":"Anulabilidad: cualquier infracción, INCLUIDA la desviación de poder. El defecto de forma solo si impide el fin o causa indefensión. La actuación fuera de plazo solo si lo impone la naturaleza del plazo.","n":6,"ex":6,"alc":1,"web":2,"w":21.0,"pr":"A","sub":"Anulabilidad — Cualquier infracción del ordenamiento, incluso la desviación de poder. Defecto de forma: solo si falta un requisito indispensable para el fin o causa indefensión. Fuera de plazo: solo si lo impone la naturaleza del término."},{"law":"lpac","art":"56","t":"Artículo 56. Medidas provisionales.","mat":"Medidas provisionales","cl":"Iniciado el procedimiento: las adopta el órgano competente para resolver si hay elementos de juicio. Antes de iniciarlo: urgencia inaplazable; confirmación, modificación o levantamiento en el acuerdo de iniciación en 15 días. Proporcionalidad, efectividad y menor onerosidad.","note":"Medidas provisionales «PEMO»: Proporcionalidad, Efectividad y Menor Onerosidad. Antes de iniciarse el procedimiento, solo por urgencia inaplazable, y el acuerdo de iniciación debe confirmarlas en 15 días (si no, quedan sin efecto).","n":6,"ex":6,"alc":1,"web":2,"w":21.0,"pr":"A","sub":"Medidas provisionales — Iniciado el procedimiento: las adopta el órgano competente para resolver si hay elementos de juicio. Antes de iniciarlo: urgencia inaplazable; confirmación, modificación o levantamiento en el acuerdo de iniciación en 15 días. Proporcionalidad, efectividad y menor onerosidad."},{"law":"lpac","art":"67","t":"Artículo 67. Solicitudes de iniciación en los procedimientos de responsabilidad patrimonial.","mat":"Solicitudes de responsabilidad patrimonial","cl":"Derecho a reclamar prescribe al año del hecho o de la manifestación del efecto lesivo; daños físicos o psíquicos: desde la curación o determinación del alcance de las secuelas. Anulación de acto: un año desde la notificación de la sentencia.","note":"Responsabilidad patrimonial: reclamar en 1 AÑO. Daños físicos o psíquicos: el año empieza con la CURACIÓN o la fijación de secuelas. Si el daño viene de un acto anulado, 1 año desde la sentencia definitiva.","n":6,"ex":6,"alc":0,"web":2,"w":21.0,"pr":"A","sub":"Solicitudes de responsabilidad patrimonial — Derecho a reclamar prescribe al año del hecho o de la manifestación del efecto lesivo; daños físicos o psíquicos: desde la curación o determinación del alcance de las secuelas. Anulación de acto: un año desde la notificación de la sentencia."},{"law":"lpac","art":"77","t":"Artículo 77. Medios y período de prueba.","mat":"Medios y período de prueba","cl":"Cualquier medio admisible en Derecho. Período de prueba no superior a 30 días ni inferior a 10. Extraordinario: no superior a 10 días. Rechazo motivado solo si son improcedentes o innecesarias.","note":"Prueba «10-30 + 10»: período ordinario entre 10 y 30 días; extraordinario hasta 10 días. Rechazo de pruebas: resolución MOTIVADA. Los hechos de sentencias penales firmes vinculan.","n":6,"ex":6,"alc":0,"web":2,"w":21.0,"pr":"A","sub":"Medios y período de prueba — Cualquier medio admisible en Derecho. Período de prueba no superior a 30 días ni inferior a 10. Extraordinario: no superior a 10 días. Rechazo motivado solo si son improcedentes o innecesarias."},{"law":"lpac","art":"84","t":"Artículo 84. Terminación.","mat":"Terminación","cl":"Resolución, desistimiento, renuncia y declaración de caducidad. Imposibilidad material de continuar por causas sobrevenidas: resolución motivada.","note":"Terminación «RE-DE-RE-CA»: REsolución, DEsistimiento, REnuncia, CAducidad + imposibilidad material sobrevenida (resolución motivada).","n":6,"ex":6,"alc":0,"web":2,"w":21.0,"pr":"A","sub":"Terminación — Resolución, desistimiento, renuncia y declaración de caducidad. Imposibilidad material de continuar por causas sobrevenidas: resolución motivada."},{"law":"lpac","art":"114","t":"Artículo 114. Fin de la vía administrativa.","mat":"Fin de la vía administrativa","cl":"Resoluciones de alzada; procedimientos sustitutivos; órganos sin superior jerárquico salvo ley; demás resoluciones cuando una disposición lo establezca; acuerdos finalizadores; responsabilidad patrimonial; sancionadores en que el recurso no sea posible; en la AGE, Ministros, Secretarios de Estado, etc.","note":"Ponen fin a la vía administrativa: resolución de ALZADA · procedimientos SUSTITUTIVOS · órgano SIN superior jerárquico · lo que diga una norma · acuerdos finalizadores · resolución de RESPONSABILIDAD PATRIMONIAL · procedimiento complementario de indemnización en sancionadores. En el Ayuntamiento: Alcalde y Pleno (art. 52 LBRL).","n":6,"ex":6,"alc":0,"web":2,"w":21.0,"pr":"A","sub":"Fin de la vía administrativa — Resoluciones de alzada; procedimientos sustitutivos; órganos sin superior jerárquico salvo ley; demás resoluciones cuando una disposición lo establezca; acuerdos finalizadores; responsabilidad patrimonial; sancionadores en que el recurso no sea posible; en la AGE, Ministros, Secretarios de Estado, etc."},{"law":"lpac","art":"4","t":"Artículo 4. Concepto de interesado.","mat":"Concepto de interesado","cl":"Promuevan el procedimiento como titulares de derechos o intereses legítimos; tengan derechos que puedan resultar afectados; intereses legítimos afectados que se personen antes de la resolución definitiva. Asociaciones representativas de intereses económicos y sociales. El causahabiente sucede.","note":"«PRO-DE-PER»: PROmueven el procedimiento · tienen DErechos que pueden resultar afectados · se PERsonan (intereses legítimos) mientras no haya resolución DEFINITIVA. El causahabiente sucede en la condición de interesado cualquiera que sea el estado del procedimiento.","n":5,"ex":5,"alc":0,"web":2,"w":18.5,"pr":"A","sub":"Concepto de interesado — Promuevan el procedimiento como titulares de derechos o intereses legítimos; tengan derechos que puedan resultar afectados; intereses legítimos afectados que se personen antes de la resolución definitiva. Asociaciones representativas de intereses económicos y sociales. El causahabiente sucede."},{"law":"lpac","art":"37","t":"Artículo 37. Inderogabilidad singular.","mat":"Inderogabilidad singular","cl":"Las resoluciones de carácter particular no pueden vulnerar lo establecido en una disposición de carácter general, aunque procedan de un órgano de igual o superior jerarquía. Son nulas.","note":"«El jefe tampoco puede saltarse su propio reglamento»: una resolución particular que vulnera una disposición general es NULA, aunque la dicte el mismo órgano o uno superior.","n":5,"ex":5,"alc":0,"web":2,"w":18.5,"pr":"A","sub":"Inderogabilidad singular — Las resoluciones de carácter particular no pueden vulnerar lo establecido en una disposición de carácter general, aunque procedan de un órgano de igual o superior jerarquía. Son nulas."},{"law":"lpac","art":"45","t":"Artículo 45. Publicación.","mat":"Publicación","cl":"Cuando lo establezcan las normas o lo aconsejen razones de interés público; destinatarios indeterminados; procedimientos selectivos o de concurrencia competitiva (indicando el tablón o medio). Efectos de la notificación.","note":"Publicación en lugar de notificación «IN-SE»: destinatarios INdeterminados o acto que ponga fin a un procedimiento SElectivo o de concurrencia competitiva. Produce los efectos de la notificación.","n":5,"ex":5,"alc":0,"web":2,"w":18.5,"pr":"A","sub":"Publicación — Cuando lo establezcan las normas o lo aconsejen razones de interés público; destinatarios indeterminados; procedimientos selectivos o de concurrencia competitiva (indicando el tablón o medio). Efectos de la notificación."},{"law":"lpac","art":"69","t":"Artículo 69. Declaración responsable y comunicación.","mat":"Declaración responsable y comunicación","cl":"Declaración responsable: el interesado manifiesta bajo su responsabilidad que cumple los requisitos y dispone de documentación. Comunicación: pone en conocimiento datos. Permiten el ejercicio desde su presentación. Inexactitud esencial: impide continuar.","note":"Declaración responsable = «CUMPLO y lo TENGO»; Comunicación = «te AVISO». Ambas habilitan desde el día de su PRESENTACIÓN. Falsedad o inexactitud ESENCIAL: cese de la actividad y posible imposibilidad de pedir lo mismo durante el tiempo que fije la ley.","n":5,"ex":5,"alc":0,"web":2,"w":18.5,"pr":"A","sub":"Declaración responsable y comunicación — Declaración responsable: el interesado manifiesta bajo su responsabilidad que cumple los requisitos y dispone de documentación. Comunicación: pone en conocimiento datos. Permiten el ejercicio desde su presentación. Inexactitud esencial: impide continuar."},{"law":"lpac","art":"98","t":"Artículo 98. Ejecutoriedad.","mat":"Ejecutoriedad","cl":"Actos inmediatamente ejecutivos salvo: suspensión, sanción contra la que quepa recurso administrativo (incluido el potestativo de reposición), disposición en contrario o aprobación superior. Pagos a la Administración: preferentemente electrónicos.","note":"Ejecutoriedad «NO se ejecuta si: SUSPENDIDO · SANCIÓN recurrible en vía administrativa · lo diga una norma · necesita APROBACIÓN superior». Pagos: electrónicos (tarjeta, transferencia, domiciliación…).","n":5,"ex":5,"alc":0,"web":2,"w":18.5,"pr":"A","sub":"Ejecutoriedad — Actos inmediatamente ejecutivos salvo: suspensión, sanción contra la que quepa recurso administrativo (incluido el potestativo de reposición), disposición en contrario o aprobación superior. Pagos a la Administración: preferentemente electrónicos."},{"law":"lpac","art":"106","t":"Artículo 106. Revisión de disposiciones y actos nulos.","mat":"Revisión de disposiciones y actos nulos","cl":"En cualquier momento, de oficio o a solicitud, actos firmes o que no se recurrieron en plazo, previo dictamen FAVORABLE del Consejo de Estado u órgano consultivo autonómico. Disposiciones: solo de oficio. Inadmisión sin dictamen. Plazo de 6 meses: caducidad (de oficio) o desestimación (a solicitud).","note":"Revisión de nulos «CUALQUIER MOMENTO + dictamen FAVORABLE + 6 MESES». De oficio y no resuelto en 6 meses: caducidad; a solicitud: desestimada. Disposiciones generales nulas: solo DE OFICIO.","n":5,"ex":5,"alc":0,"web":2,"w":18.5,"pr":"A","sub":"Revisión de disposiciones y actos nulos — En cualquier momento, de oficio o a solicitud, actos firmes o que no se recurrieron en plazo, previo dictamen FAVORABLE del Consejo de Estado u órgano consultivo autonómico. Disposiciones: solo de oficio. Inadmisión sin dictamen. Plazo de 6 meses: caducidad (de oficio) o desestimación (a solicitud)."},{"law":"lpac","art":"122","t":"Artículo 122. Plazos.","mat":"Recurso de alzada: plazos","cl":"Acto expreso: 1 mes. Si no es expreso: en cualquier momento desde el día siguiente al silencio. Resolución y notificación: 3 meses; silencio desestimatorio (salvo 24.1). Contra su resolución no cabe otro recurso administrativo salvo el extraordinario de revisión.","note":"Alzada «1-3»: 1 MES para interponer (sin plazo si no hay acto expreso), 3 MESES para resolver. Tras la alzada, solo el EXTRAORDINARIO de revisión.","n":5,"ex":5,"alc":0,"web":2,"w":18.5,"pr":"A","sub":"Recurso de alzada: plazos — Acto expreso: 1 mes. Si no es expreso: en cualquier momento desde el día siguiente al silencio. Resolución y notificación: 3 meses; silencio desestimatorio (salvo 24.1). Contra su resolución no cabe otro recurso administrativo salvo el extraordinario de revisión."},{"law":"lpac","art":"13","t":"Artículo 13. Derechos de las personas en sus relaciones con las Administraciones Públicas.","mat":"Derechos de las personas en sus relaciones con las AAPP","cl":"Comunicarse por el Punto de Acceso General electrónico; ser asistidos; lenguas cooficiales; acceso a la información pública; trato con respeto; exigir responsabilidades; obtener medios de identificación y firma; protección de datos.","note":"Art. 13 = derechos de TODAS las PERSONAS (aunque no sean interesadas). Art. 53 = derechos del INTERESADO en un procedimiento concreto. Es la trampa típica.","n":4,"ex":4,"alc":1,"web":2,"w":16.0,"pr":"A","sub":"Derechos de las personas en sus relaciones con las AAPP — Comunicarse por el Punto de Acceso General electrónico; ser asistidos; lenguas cooficiales; acceso a la información pública; trato con respeto; exigir responsabilidades; obtener medios de identificación y firma; protección de datos."},{"law":"lpac","art":"16","t":"Artículo 16. Registros.","mat":"Registros","cl":"Cada Administración, un Registro Electrónico General. Presentación: registro electrónico de cualquier Administración, Correos, representaciones diplomáticas y consulares, oficinas de asistencia en materia de registros y cualquier otro que establezcan las disposiciones.","note":"Dónde presentar «RE-CO-DI-OF»: REgistro electrónico de cualquier Administración, COrreos, DIplomáticas/consulares, OFicinas de asistencia en materia de registros y cualquier otro legal. Pagos: transferencia u otros medios. Los registros se rigen por el calendario de días inhábiles.","n":4,"ex":4,"alc":0,"web":2,"w":16.0,"pr":"A","sub":"Registros — Cada Administración, un Registro Electrónico General. Presentación: registro electrónico de cualquier Administración, Correos, representaciones diplomáticas y consulares, oficinas de asistencia en materia de registros y cualquier otro que establezcan las disposiciones."},{"law":"lpac","art":"25","t":"Artículo 25. Falta de resolución expresa en procedimientos iniciados de oficio.","mat":"Silencio en procedimientos de oficio","cl":"Si pueden producir efectos favorables: desestimados. Si ejercen potestades sancionadoras o de intervención: caducidad y archivo.","note":"De oficio: «favorable = DESESTIMADO; gravamen (sancionador o intervención) = CADUCIDAD». La caducidad no produce por sí sola la prescripción.","n":4,"ex":4,"alc":0,"web":2,"w":16.0,"pr":"A","sub":"Silencio en procedimientos de oficio — Si pueden producir efectos favorables: desestimados. Si ejercen potestades sancionadoras o de intervención: caducidad y archivo."},{"law":"lpac","art":"73","t":"Artículo 73. Cumplimiento de trámites.","mat":"Cumplimiento de trámites","cl":"Trámites de los interesados: 10 días desde la notificación salvo otro plazo. Defectos: requerimiento con 10 días. Fuera de plazo: se admite si se cumple antes o dentro del día en que se notifica la resolución que tiene por transcurrido el plazo.","note":"Trámites del interesado: 10 días. Si no los cumple, se le puede declarar DECAÍDO en su derecho, pero se admite su actuación si la hace ANTES o DENTRO del día en que se le notifica esa resolución.","n":4,"ex":4,"alc":0,"web":2,"w":16.0,"pr":"A","sub":"Cumplimiento de trámites — Trámites de los interesados: 10 días desde la notificación salvo otro plazo. Defectos: requerimiento con 10 días. Fuera de plazo: se admite si se cumple antes o dentro del día en que se notifica la resolución que tiene por transcurrido el plazo."},{"law":"lpac","art":"80","t":"Artículo 80. Emisión de informes.","mat":"Emisión de informes","cl":"Facultativos y no vinculantes salvo disposición. Electrónicos. Plazo de 10 días. Si no se emite: se pueden proseguir las actuaciones salvo informe preceptivo, en cuyo caso se puede suspender (22.1.d).","note":"Informes «F-NV-10»: Facultativos, No Vinculantes, 10 días. Si no llega un informe PRECEPTIVO, se puede suspender el plazo de resolver (máximo 3 meses, art. 22).","n":4,"ex":4,"alc":0,"web":2,"w":16.0,"pr":"A","sub":"Emisión de informes — Facultativos y no vinculantes salvo disposición. Electrónicos. Plazo de 10 días. Si no se emite: se pueden proseguir las actuaciones salvo informe preceptivo, en cuyo caso se puede suspender (22.1.d)."},{"law":"lpac","art":"116","t":"Artículo 116. Causas de inadmisión.","mat":"Causas de inadmisión","cl":"Órgano incompetente (se remite al competente); falta de legitimación; acto no recurrible; plazo transcurrido; carencia manifiesta de fundamento.","note":"Inadmisión «IN-LE-NO-PLA-FU»: INcompetencia · falta de LEgitimación · acto NO recurrible · PLAzo pasado · sin FUndamento manifiesto.","n":4,"ex":4,"alc":0,"web":2,"w":16.0,"pr":"A","sub":"Causas de inadmisión — Órgano incompetente (se remite al competente); falta de legitimación; acto no recurrible; plazo transcurrido; carencia manifiesta de fundamento."},{"law":"lrjsp","art":"9","t":"Artículo 9. Delegación de competencias.","mat":"Delegación de competencias","cl":"En órganos de la misma Administración aunque no sean jerárquicamente dependientes, u organismos vinculados. No delegables: relaciones con Jefatura del Estado, Presidencia del Gobierno, Cortes, Presidencias y Asambleas autonómicas; disposiciones de carácter general; resolución de recursos contra sus propios actos; las excluidas por ley. Publicación; se consideran dictadas por el delegante; no se delega lo delegado salvo ley; revocable en cualquier momento; quórum especial.","note":"NO delegables «JE-DI-RE-LEY»: relaciones con JEfatura del Estado y altas instituciones · DIsposiciones generales · REcursos contra los propios actos · lo que excluya una LEY. Publicar en boletín. Lo resuelto se considera dictado por el DELEGANTE. Prohibido delegar lo delegado (salvo ley). Revocable en cualquier momento. Tras un dictamen preceptivo ya emitido, no se puede delegar la resolución.","n":4,"ex":4,"alc":0,"web":2,"w":16.0,"pr":"B","sub":"Delegación de competencias — En órganos de la misma Administración aunque no sean jerárquicamente dependientes, u organismos vinculados. No delegables: relaciones con Jefatura del Estado, Presidencia del Gobierno, Cortes, Presidencias y Asambleas autonómicas; disposiciones de carácter general; resolución de recursos contra sus propios actos; las excluidas por ley. Publicación; se consideran dictadas por el delegante; no se delega lo delegado salvo ley; revocable en cualquier momento; quórum especial."},{"law":"lrjsp","art":"17","t":"Artículo 17. Convocatorias y sesiones.","mat":"Convocatorias y sesiones","cl":"Presencial o a distancia. Quórum: Presidente y Secretario (o suplentes) y la mitad al menos de los miembros. Sin convocatoria si están todos y lo deciden. Asuntos fuera del orden del día: todos presentes y urgencia por mayoría. Acuerdos por mayoría de votos. Votar en contra o abstenerse exime de responsabilidad. Certificaciones a quien acredite interés legítimo.","note":"Colegiado «P + S + MITAD»: Presidente, Secretario y la mitad de los miembros. Fuera del orden del día: TODOS presentes + urgencia por MAYORÍA. Acuerdos por mayoría. Quien vota en contra o se abstiene queda EXENTO de responsabilidad.","n":4,"ex":4,"alc":0,"web":2,"w":16.0,"pr":"B","sub":"Convocatorias y sesiones — Presencial o a distancia. Quórum: Presidente y Secretario (o suplentes) y la mitad al menos de los miembros. Sin convocatoria si están todos y lo deciden. Asuntos fuera del orden del día: todos presentes y urgencia por mayoría. Acuerdos por mayoría de votos. Votar en contra o abstenerse exime de responsabilidad. Certificaciones a quien acredite interés legítimo."},{"law":"lpac","art":"36","t":"Artículo 36. Forma.","mat":"Forma","cl":"Por escrito y por medios electrónicos salvo que exijan otra forma. Actos verbales: constancia escrita (la hace el titular inferior o el funcionario que los recibe). Actos de la misma naturaleza: una sola resolución.","note":"Forma: ESCRITA y ELECTRÓNICA. Si el acto es verbal y hace falta constancia, la firma el titular del órgano INFERIOR o el funcionario que lo recibe oralmente, indicando la autoridad de la que procede.","n":5,"ex":5,"alc":0,"web":1,"w":15.5,"pr":"B","sub":"Forma — Por escrito y por medios electrónicos salvo que exijan otra forma. Actos verbales: constancia escrita (la hace el titular inferior o el funcionario que los recibe). Actos de la misma naturaleza: una sola resolución."},{"law":"lrjsp","art":"36","t":"Artículo 36. Exigencia de la responsabilidad patrimonial de las autoridades y personal al servicio de las Administraciones Públicas.","mat":"Responsabilidad de autoridades y personal","cl":"El particular reclama directamente a la Administración. Acción de regreso de oficio contra el personal por dolo, culpa o negligencia graves. Procedimiento: alegaciones 15 días, prueba 15 días, audiencia 10 días, propuesta 5 días, resolución 5 días. Pone fin a la vía administrativa.","note":"Nunca se demanda al funcionario: se reclama a la ADMINISTRACIÓN, que luego repite contra él por DOLO o CULPA/NEGLIGENCIA GRAVES. Procedimiento de regreso «15-15-10-5-5»: alegaciones, prueba, audiencia, propuesta, resolución.","n":4,"ex":3,"alc":0,"web":2,"w":14.5,"pr":"B","sub":"Responsabilidad de autoridades y personal — El particular reclama directamente a la Administración. Acción de regreso de oficio contra el personal por dolo, culpa o negligencia graves. Procedimiento: alegaciones 15 días, prueba 15 días, audiencia 10 días, propuesta 5 días, resolución 5 días. Pone fin a la vía administrativa."},{"law":"lpac","art":"22","t":"Artículo 22. Suspensión del plazo máximo para resolver.","mat":"Suspensión del plazo máximo para resolver","cl":"Potestativa: subsanación, pronunciamiento UE, informes preceptivos (máximo 3 meses), pruebas técnicas, negociación de pacto, pronunciamiento judicial. Obligatoria: requerimiento a otra Administración, actuaciones complementarias y recusación.","note":"Informe preceptivo: suspende como MÁXIMO 3 MESES; si no llega, se sigue. Suspensión OBLIGATORIA (22.2) «RE-AC-RE»: REquerimiento a otra Administración, Actuaciones Complementarias, REcusación.","n":3,"ex":3,"alc":0,"web":2,"w":13.5,"pr":"B","sub":"Suspensión del plazo máximo para resolver — Potestativa: subsanación, pronunciamiento UE, informes preceptivos (máximo 3 meses), pruebas técnicas, negociación de pacto, pronunciamiento judicial. Obligatoria: requerimiento a otra Administración, actuaciones complementarias y recusación."},{"law":"lpac","art":"32","t":"Artículo 32. Ampliación.","mat":"Ampliación de plazos","cl":"De oficio o a petición, no más de la mitad, si no perjudica a terceros; pedida y acordada antes del vencimiento; nunca de un plazo vencido; no recurrible. Ampliación por incidencia técnica.","note":"Ampliación «MITAD-ANTES-NR»: máximo la MITAD del plazo; solicitarse y acordarse ANTES del vencimiento; No Recurrible. Siempre por el máximo en trámites en el extranjero o con interesados residentes fuera de España.","n":3,"ex":3,"alc":1,"web":2,"w":13.5,"pr":"B","sub":"Ampliación de plazos — De oficio o a petición, no más de la mitad, si no perjudica a terceros; pedida y acordada antes del vencimiento; nunca de un plazo vencido; no recurrible. Ampliación por incidencia técnica."},{"law":"lpac","art":"33","t":"Artículo 33. Tramitación de urgencia.","mat":"Tramitación de urgencia","cl":"Por interés público, de oficio o a petición: plazos a la MITAD salvo presentación de solicitudes y recursos. No cabe recurso contra el acuerdo.","note":"Urgencia = MITAD de plazos, pero «SoRe» no se tocan: SOlicitudes y REcursos. No recurrible.","n":3,"ex":3,"alc":1,"web":2,"w":13.5,"pr":"B","sub":"Tramitación de urgencia — Por interés público, de oficio o a petición: plazos a la MITAD salvo presentación de solicitudes y recursos. No cabe recurso contra el acuerdo."},{"law":"lpac","art":"62","t":"Artículo 62. Inicio del procedimiento por denuncia.","mat":"Denuncia","cl":"Pone en conocimiento hechos que pueden justificar la iniciación de oficio. Identidad del denunciante y relato. Exención al primero que aporte pruebas si participó (clemencia). No confiere por sí sola la condición de interesado.","note":"Denunciante ≠ interesado. Si participó en la infracción y es el PRIMERO en aportar pruebas → EXENCIÓN; si no es el primero pero aporta valor añadido → REDUCCIÓN. En ambos casos debe cesar en la infracción y no haber destruido pruebas.","n":3,"ex":3,"alc":0,"web":2,"w":13.5,"pr":"B","sub":"Denuncia — Pone en conocimiento hechos que pueden justificar la iniciación de oficio. Identidad del denunciante y relato. Exención al primero que aporte pruebas si participó (clemencia). No confiere por sí sola la condición de interesado."},{"law":"lpac","art":"64","t":"Artículo 64. Acuerdo de iniciación en los procedimientos de naturaleza sancionadora.","mat":"Acuerdo de iniciación sancionador","cl":"Notificado al inculpado; contenido: responsables, hechos y posible sanción, instructor y secretario con régimen de recusación, órgano competente y posibilidad de reconocimiento voluntario, medidas provisionales, derecho a alegar. Si no alega, puede ser propuesta de resolución.","note":"Si no alega en plazo → el acuerdo de iniciación vale como PROPUESTA de resolución (cuando contenga un pronunciamiento preciso sobre la responsabilidad). Si faltan datos para calificar: PLIEGO DE CARGOS posterior.","n":3,"ex":3,"alc":0,"web":2,"w":13.5,"pr":"B","sub":"Acuerdo de iniciación sancionador — Notificado al inculpado; contenido: responsables, hechos y posible sanción, instructor y secretario con régimen de recusación, órgano competente y posibilidad de reconocimiento voluntario, medidas provisionales, derecho a alegar. Si no alega, puede ser propuesta de resolución."},{"law":"lpac","art":"109","t":"Artículo 109. Revocación de actos y rectificación de errores.","mat":"Revocación y rectificación de errores","cl":"Revocar actos de gravamen o desfavorables mientras no haya prescrito, si no es dispensa no permitida ni contraria a igualdad o interés público. Rectificar errores materiales, de hecho o aritméticos en cualquier momento.","note":"Revocación: solo actos DESFAVORABLES, mientras no PRESCRIBA. Rectificación de errores materiales, de hecho o aritméticos: en CUALQUIER momento.","n":3,"ex":3,"alc":0,"web":2,"w":13.5,"pr":"B","sub":"Revocación y rectificación de errores — Revocar actos de gravamen o desfavorables mientras no haya prescrito, si no es dispensa no permitida ni contraria a igualdad o interés público. Rectificar errores materiales, de hecho o aritméticos en cualquier momento."},{"law":"lpac","art":"121","t":"Artículo 121. Objeto.","mat":"Recurso de alzada: objeto","cl":"Contra resoluciones y actos de trámite cualificados que NO pongan fin a la vía administrativa; ante el superior jerárquico; se puede presentar ante el que dictó el acto o el competente. Tribunales de selección: ante el órgano al que estén adscritos o, en su defecto, el que nombró a su presidente.","note":"Alzada = acto que NO agota la vía + al SUPERIOR. Tribunales y órganos de selección: dependen del órgano al que estén ADSCRITOS o, en su defecto, del que NOMBRÓ a su presidente.","n":3,"ex":3,"alc":1,"web":2,"w":13.5,"pr":"B","sub":"Recurso de alzada: objeto — Contra resoluciones y actos de trámite cualificados que NO pongan fin a la vía administrativa; ante el superior jerárquico; se puede presentar ante el que dictó el acto o el competente. Tribunales de selección: ante el órgano al que estén adscritos o, en su defecto, el que nombró a su presidente."},{"law":"lpac","art":"124","t":"Artículo 124. Plazos.","mat":"Recurso de reposición: plazos","cl":"Acto expreso: 1 mes; si no es expreso, en cualquier momento desde el día siguiente al silencio. Resolver y notificar: 1 mes. No cabe nuevo recurso de reposición contra su resolución.","note":"Reposición «1-1»: 1 MES para interponer, 1 MES para resolver. Nada de reposición sobre reposición.","n":3,"ex":3,"alc":0,"web":2,"w":13.5,"pr":"B","sub":"Recurso de reposición: plazos — Acto expreso: 1 mes; si no es expreso, en cualquier momento desde el día siguiente al silencio. Resolver y notificar: 1 mes. No cabe nuevo recurso de reposición contra su resolución."},{"law":"lrjsp","art":"3","t":"Artículo 3. Principios generales.","mat":"Principios generales","cl":"Objetividad; eficacia, jerarquía, descentralización, desconcentración y coordinación; servicio efectivo, simplicidad, participación, racionalización, buena fe, confianza legítima, lealtad institucional, responsabilidad, planificación, eficacia, economía, eficiencia, cooperación. Relación electrónica entre Administraciones. Personalidad jurídica única.","note":"Art. 103 CE + 3.1 LRJSP «E-JE-DES-DES-CO»: Eficacia, JErarquía, DEScentralización, DESconcentración, COordinación. Las Administraciones se relacionan ENTRE SÍ siempre por medios electrónicos. Cada Administración: personalidad jurídica ÚNICA.","n":3,"ex":3,"alc":0,"web":2,"w":13.5,"pr":"B","sub":"Principios generales — Objetividad; eficacia, jerarquía, descentralización, desconcentración y coordinación; servicio efectivo, simplicidad, participación, racionalización, buena fe, confianza legítima, lealtad institucional, responsabilidad, planificación, eficacia, economía, eficiencia, cooperación. Relación electrónica entre Administraciones. Personalidad jurídica única."},{"law":"lrjsp","art":"10","t":"Artículo 10. Avocación.","mat":"Avocación","cl":"El órgano superior asume un asunto de un dependiente (ordinario o por delegación) por razones técnicas, económicas, sociales, jurídicas o territoriales. Delegación en no dependiente: solo avoca el delegante. Acuerdo motivado notificado antes o a la vez que la resolución. No recurrible, impugnable con la resolución.","note":"Avocación = «el de ARRIBA coge el asunto del de ABAJO». Acuerdo MOTIVADO, notificado antes o con la resolución final. Sin recurso directo (se impugna con la resolución).","n":3,"ex":3,"alc":0,"web":2,"w":13.5,"pr":"B","sub":"Avocación — El órgano superior asume un asunto de un dependiente (ordinario o por delegación) por razones técnicas, económicas, sociales, jurídicas o territoriales. Delegación en no dependiente: solo avoca el delegante. Acuerdo motivado notificado antes o a la vez que la resolución. No recurrible, impugnable con la resolución."},{"law":"lrjsp","art":"25","t":"Artículo 25. Principio de legalidad.","mat":"Principio de legalidad sancionadora","cl":"Potestad sancionadora reconocida por norma con rango de ley; la ejercen los órganos con atribución expresa (ley o reglamento). Se extiende a la potestad disciplinaria. No se aplica a contratistas ni a relaciones patrimoniales.","note":"Potestad sancionadora: reconocida por LEY; atribuida a órganos por ley o REGLAMENTO. Aplicable a lo DISCIPLINARIO del personal; NO a contratistas ni a relaciones patrimoniales. Entes locales: Título XI LBRL.","n":3,"ex":3,"alc":0,"web":2,"w":13.5,"pr":"B","sub":"Principio de legalidad sancionadora — Potestad sancionadora reconocida por norma con rango de ley; la ejercen los órganos con atribución expresa (ley o reglamento). Se extiende a la potestad disciplinaria. No se aplica a contratistas ni a relaciones patrimoniales."},{"law":"lrjsp","art":"29","t":"Artículo 29. Principio de proporcionalidad.","mat":"Principio de proporcionalidad","cl":"Nunca privación de libertad. La infracción no puede ser más beneficiosa que cumplir. Graduación: culpabilidad o intencionalidad, continuidad, perjuicios y reincidencia (más de una infracción de la misma naturaleza en un año declarada por resolución firme). Grado inferior. Concurso medial: la más grave. Infracción continuada.","note":"Graduación «CU-CO-PE-RE»: CUlpabilidad o intencionalidad · COntinuidad · PErjuicios · REincidencia (en 1 AÑO, misma naturaleza, resolución FIRME). Sanción administrativa NUNCA implica privación de libertad.","n":3,"ex":3,"alc":0,"web":2,"w":13.5,"pr":"B","sub":"Principio de proporcionalidad — Nunca privación de libertad. La infracción no puede ser más beneficiosa que cumplir. Graduación: culpabilidad o intencionalidad, continuidad, perjuicios y reincidencia (más de una infracción de la misma naturaleza en un año declarada por resolución firme). Grado inferior. Concurso medial: la más grave. Infracción continuada."},{"law":"lpac","art":"6","t":"Artículo 6. Registros electrónicos de apoderamientos.","mat":"Registro electrónico de apoderamientos","cl":"Apud acta presencial (oficina de asistencia en materia de registros) o electrónico (sede). Poderes inscritos: validez máxima 5 años desde la inscripción; prórrogas de máximo 5 años.","note":"Poder inscrito «5+5»: dura como máximo 5 años desde la inscripción y, ANTES de que acabe, el poderdante puede revocarlo o prorrogarlo por otros 5 como máximo. Tres tipos de poder: general (cualquier Administración), ante una Administración concreta y para trámites concretos.","n":4,"ex":4,"alc":0,"web":1,"w":13.0,"pr":"B","sub":"Registro electrónico de apoderamientos — Apud acta presencial (oficina de asistencia en materia de registros) o electrónico (sede). Poderes inscritos: validez máxima 5 años desde la inscripción; prórrogas de máximo 5 años."},{"law":"lpac","art":"11","t":"Artículo 11. Uso de medios de identificación y firma en el procedimiento administrativo.","mat":"Uso de identificación y firma","cl":"Con carácter general basta la identificación. Firma obligatoria solo para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar.","note":"Firma solo para «SoDeReDeRe» (los mismos supuestos en que hay que acreditar la representación del art. 5): Solicitudes, DEclaraciones responsables/comunicaciones, REcursos, DEsistir, REnunciar.","n":4,"ex":4,"alc":0,"web":1,"w":13.0,"pr":"B","sub":"Uso de identificación y firma — Con carácter general basta la identificación. Firma obligatoria solo para formular solicitudes, presentar declaraciones responsables o comunicaciones, interponer recursos, desistir y renunciar."},{"law":"lpac","art":"51","t":"Artículo 51. Conservación de actos y trámites.","mat":"Conservación de actos y trámites","cl":"El órgano que declare la nulidad o anule dispondrá la conservación de actos y trámites cuyo contenido se habría mantenido igual sin la infracción.","note":"Conservación: lo que habría salido igual sin el vicio, SE CONSERVA.","n":4,"ex":4,"alc":0,"web":1,"w":13.0,"pr":"B","sub":"Conservación de actos y trámites — El órgano que declare la nulidad o anule dispondrá la conservación de actos y trámites cuyo contenido se habría mantenido igual sin la infracción."},{"law":"lpac","art":"44","t":"Artículo 44. Notificación infructuosa.","mat":"Notificación infructuosa","cl":"Interesados desconocidos, lugar ignorado o intento fallido: anuncio en el BOE (Tablón Edictal Único). Previamente y de forma facultativa, en boletines de la CCAA o provincia, tablón del Ayuntamiento del último domicilio o consulado.","note":"Infructuosa → BOE SIEMPRE (Tablón Edictal Único). Lo demás (boletín autonómico o provincial, tablón municipal, consulado) es FACULTATIVO y complementario.","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Notificación infructuosa — Interesados desconocidos, lugar ignorado o intento fallido: anuncio en el BOE (Tablón Edictal Único). Previamente y de forma facultativa, en boletines de la CCAA o provincia, tablón del Ayuntamiento del último domicilio o consulado."},{"law":"lpac","art":"63","t":"Artículo 63. Especialidades en el inicio de los procedimientos de naturaleza sancionadora.","mat":"Especialidades en el inicio del sancionador","cl":"Siempre de oficio; separación entre fase instructora y sancionadora (órganos distintos); no se puede sancionar sin procedimiento; infracción continuada: no nuevos procedimientos mientras no haya una primera resolución sancionadora ejecutiva.","note":"Sancionador: SIEMPRE de oficio. Quien instruye NO resuelve. Sin procedimiento NO hay sanción.","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Especialidades en el inicio del sancionador — Siempre de oficio; separación entre fase instructora y sancionadora (órganos distintos); no se puede sancionar sin procedimiento; infracción continuada: no nuevos procedimientos mientras no haya una primera resolución sancionadora ejecutiva."},{"law":"lpac","art":"83","t":"Artículo 83. Información pública.","mat":"Información pública","cl":"Anuncio en el Diario oficial; plazo de alegaciones no inferior a 20 días. Comparecer no da la condición de interesado, pero sí derecho a respuesta razonada.","note":"Información pública: «20 días como MÍNIMO». Quien alega NO es interesado por ello, pero tiene derecho a una respuesta RAZONADA (puede ser común).","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Información pública — Anuncio en el Diario oficial; plazo de alegaciones no inferior a 20 días. Comparecer no da la condición de interesado, pero sí derecho a respuesta razonada."},{"law":"lpac","art":"85","t":"Artículo 85. Terminación en los procedimientos sancionadores.","mat":"Terminación en sancionadores","cl":"Reconocimiento de responsabilidad y pago voluntario antes de la resolución. Si la sanción es solo pecuniaria: reducciones de al menos el 20% cada una, acumulables, condicionadas al desistimiento o renuncia de recursos administrativos.","note":"«Reconoce y paga = 20 + 20»: dos reducciones de AL MENOS el 20% cada una, ACUMULABLES, si la sanción es solo pecuniaria. Condición: renunciar a recurrir en vía administrativa.","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Terminación en sancionadores — Reconocimiento de responsabilidad y pago voluntario antes de la resolución. Si la sanción es solo pecuniaria: reducciones de al menos el 20% cada una, acumulables, condicionadas al desistimiento o renuncia de recursos administrativos."},{"law":"lpac","art":"90","t":"Artículo 90. Especialidades de la resolución en los procedimientos sancionadores.","mat":"Resolución en sancionadores","cl":"Valoración de pruebas, hechos, responsables, infracción y sanción. No hechos distintos de los del procedimiento. Mayor gravedad: 15 días de alegaciones. Ejecutiva cuando no quepa recurso ordinario en vía administrativa. Suspensión cautelar si anuncia contencioso.","note":"Sanción: ejecutiva solo cuando NO cabe recurso ORDINARIO en vía administrativa. Si el órgano ve más gravedad que la propuesta: 15 días al inculpado.","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Resolución en sancionadores — Valoración de pruebas, hechos, responsables, infracción y sanción. No hechos distintos de los del procedimiento. Mayor gravedad: 15 días de alegaciones. Ejecutiva cuando no quepa recurso ordinario en vía administrativa. Suspensión cautelar si anuncia contencioso."},{"law":"lpac","art":"91","t":"Artículo 91. Especialidades de la resolución en los procedimientos en materia de responsabilidad patrimonial.","mat":"Resolución en responsabilidad patrimonial","cl":"Pronunciamiento sobre relación de causalidad, valoración del daño, cuantía y modo de indemnizar. 6 meses sin resolución: se puede entender desestimada.","note":"Responsabilidad patrimonial: 6 MESES sin resolver = DESESTIMADA (contraria a la indemnización). La resolución debe pronunciarse sobre la relación de CAUSALIDAD.","n":2,"ex":2,"alc":1,"web":2,"w":11.0,"pr":"B","sub":"Resolución en responsabilidad patrimonial — Pronunciamiento sobre relación de causalidad, valoración del daño, cuantía y modo de indemnizar. 6 meses sin resolución: se puede entender desestimada."},{"law":"lpac","art":"94","t":"Artículo 94. Desistimiento y renuncia por los interesados.","mat":"Desistimiento y renuncia de los interesados","cl":"Desistir de la solicitud o renunciar a derechos (si no está prohibido). Solo afecta a quien lo formula. Cualquier medio que permita constancia con firma. Terceros pueden instar la continuación en 10 días. Interés general: se limitan los efectos.","note":"Desistir = abandonar la SOLICITUD (puedo volver a pedir). Renunciar = abandonar el DERECHO. Aceptación de plano, salvo terceros personados que pidan seguir en 10 días.","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Desistimiento y renuncia de los interesados — Desistir de la solicitud o renunciar a derechos (si no está prohibido). Solo afecta a quien lo formula. Cualquier medio que permita constancia con firma. Terceros pueden instar la continuación en 10 días. Interés general: se limitan los efectos."},{"law":"lpac","art":"100","t":"Artículo 100. Medios de ejecución forzosa.","mat":"Medios de ejecución forzosa","cl":"Apremio sobre el patrimonio, ejecución subsidiaria, multa coercitiva y compulsión sobre las personas. Entrada en domicilio: consentimiento o autorización judicial.","note":"Medios «A-E-M-C»: Apremio · Ejecución subsidiaria · Multa coercitiva · Compulsión sobre las personas. Para entrar en el domicilio: CONSENTIMIENTO o AUTORIZACIÓN JUDICIAL.","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Medios de ejecución forzosa — Apremio sobre el patrimonio, ejecución subsidiaria, multa coercitiva y compulsión sobre las personas. Entrada en domicilio: consentimiento o autorización judicial."},{"law":"lrjsp","art":"5","t":"Artículo 5. Órganos administrativos.","mat":"Órganos administrativos","cl":"Unidades con funciones con efectos jurídicos frente a terceros o actuación preceptiva. Creación: forma de integración y dependencia jerárquica, funciones y competencias, créditos. No duplicidades.","note":"Crear un órgano «IN-FU-CRE»: INtegración y dependencia jerárquica · FUnciones y competencias · CRÉditos. Prohibido duplicar órganos sin suprimir o restringir el existente.","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Órganos administrativos — Unidades con funciones con efectos jurídicos frente a terceros o actuación preceptiva. Creación: forma de integración y dependencia jerárquica, funciones y competencias, créditos. No duplicidades."},{"law":"lrjsp","art":"8","t":"Artículo 8. Competencia.","mat":"Competencia","cl":"Irrenunciable; la ejercen los órganos que la tienen atribuida como propia salvo delegación o avocación. Delegación, encomienda, delegación de firma y suplencia no alteran la titularidad. Desconcentración. Si no se especifica el órgano: el inferior competente por materia y territorio; si hay varios, el superior jerárquico común.","note":"Competencia IRRENUNCIABLE. «DEL-EN-FIR-SU» (delegación, encomienda, firma y suplencia) no cambian el TITULAR. La DESCONCENTRACIÓN sí traslada la titularidad. Norma que no dice el órgano: el INFERIOR competente por materia y territorio.","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Competencia — Irrenunciable; la ejercen los órganos que la tienen atribuida como propia salvo delegación o avocación. Delegación, encomienda, delegación de firma y suplencia no alteran la titularidad. Desconcentración. Si no se especifica el órgano: el inferior competente por materia y territorio; si hay varios, el superior jerárquico común."},{"law":"lrjsp","art":"18","t":"Artículo 18. Actas.","mat":"Actas","cl":"Las levanta el Secretario: asistentes, orden del día, lugar y tiempo, puntos principales de las deliberaciones y acuerdos. Grabación posible. Aprobación en la misma o en la siguiente reunión.","note":"Acta «A-O-LT-D-A»: Asistentes · Orden del día · Lugar y Tiempo · Deliberaciones principales · Acuerdos. Se aprueba en la MISMA o en la SIGUIENTE sesión. Si hay GRABACIÓN no hace falta recoger las deliberaciones.","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Actas — Las levanta el Secretario: asistentes, orden del día, lugar y tiempo, puntos principales de las deliberaciones y acuerdos. Grabación posible. Aprobación en la misma o en la siguiente reunión."},{"law":"lrjsp","art":"23","t":"Artículo 23. Abstención.","mat":"Abstención","cl":"Interés personal; parentesco de consanguinidad hasta el 4.º grado o afinidad hasta el 2.º, matrimonio o análoga; amistad íntima o enemistad manifiesta; haber sido perito o testigo; relación de servicio o servicios profesionales en los últimos 2 años. Se comunica al superior inmediato. No implica necesariamente la invalidez.","note":"Abstención «IN-PA-AM-PE-SE»: INterés personal · PArentesco (consanguinidad 4.º, afinidad 2.º) · AMistad íntima o enemistad manifiesta · PErito o testigo · SErvicio o servicios profesionales en los últimos 2 AÑOS. Actuar con causa de abstención NO invalida necesariamente el acto, pero genera responsabilidad.","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Abstención — Interés personal; parentesco de consanguinidad hasta el 4.º grado o afinidad hasta el 2.º, matrimonio o análoga; amistad íntima o enemistad manifiesta; haber sido perito o testigo; relación de servicio o servicios profesionales en los últimos 2 años. Se comunica al superior inmediato. No implica necesariamente la invalidez."},{"law":"lrjsp","art":"28","t":"Artículo 28. Responsabilidad.","mat":"Responsabilidad sancionadora","cl":"Personas físicas y jurídicas y, si la ley les da capacidad, grupos de afectados, uniones sin personalidad y patrimonios autónomos, a título de dolo o culpa. Compatible con reposición e indemnización. Solidaridad si la obligación es conjunta.","note":"Solo se sanciona con DOLO o CULPA (no hay responsabilidad objetiva). La sanción es compatible con REPONER y con INDEMNIZAR. Obligación conjunta: responsabilidad SOLIDARIA (si es multa, se individualiza si es posible).","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Responsabilidad sancionadora — Personas físicas y jurídicas y, si la ley les da capacidad, grupos de afectados, uniones sin personalidad y patrimonios autónomos, a título de dolo o culpa. Compatible con reposición e indemnización. Solidaridad si la obligación es conjunta."},{"law":"lrjsp","art":"118","t":"Artículo 118. Definición y actividades propias.","mat":"Consorcios","cl":"Entidades de derecho público con personalidad jurídica propia creadas por varias Administraciones o entidades del sector público institucional, entre sí o con entidades privadas, para actividades de interés común. Denominación «consorcio» o «C».","note":"Consorcio = VARIAS Administraciones (y, en su caso, privados) + personalidad PROPIA + interés COMÚN. Siglas «C».","n":2,"ex":2,"alc":0,"web":2,"w":11.0,"pr":"B","sub":"Consorcios — Entidades de derecho público con personalidad jurídica propia creadas por varias Administraciones o entidades del sector público institucional, entre sí o con entidades privadas, para actividades de interés común. Denominación «consorcio» o «C»."},{"law":"lpac","art":"31","t":"Artículo 31. Cómputo de plazos en los registros.","mat":"Cómputo de plazos en los registros","cl":"Registro electrónico: 24 horas todos los días del año. Lo presentado en día inhábil se entiende hecho en la primera hora del primer día hábil siguiente. La sede muestra fecha y hora oficial.","note":"Registro electrónico 24/7: lo presentado en día INHÁBIL se entiende presentado a la PRIMERA HORA del primer día HÁBIL siguiente. Los plazos para la Administración se cuentan desde la fecha y hora de entrada en SU registro electrónico.","n":3,"ex":3,"alc":0,"web":1,"w":10.5,"pr":"B","sub":"Cómputo de plazos en los registros — Registro electrónico: 24 horas todos los días del año. Lo presentado en día inhábil se entiende hecho en la primera hora del primer día hábil siguiente. La sede muestra fecha y hora oficial."},{"law":"lpac","art":"49","t":"Artículo 49. Límites a la extensión de la nulidad o anulabilidad de los actos.","mat":"Límites a la extensión de la nulidad","cl":"La nulidad de un acto no implica la de los sucesivos independientes; la de una parte no afecta a las demás independientes salvo que sin ella no se hubiera dictado.","note":"«La manzana podrida no pudre el cesto»: la nulidad no se extiende a los actos o partes INDEPENDIENTES.","n":3,"ex":3,"alc":0,"web":1,"w":10.5,"pr":"B","sub":"Límites a la extensión de la nulidad — La nulidad de un acto no implica la de los sucesivos independientes; la de una parte no afecta a las demás independientes salvo que sin ella no se hubiera dictado."},{"law":"lpac","art":"50","t":"Artículo 50. Conversión de actos viciados.","mat":"Conversión de actos viciados","cl":"Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto producirán los efectos de este.","note":"Conversión: el acto viciado «se convierte» en el acto válido cuyos elementos contiene. Sirve para nulos Y anulables.","n":3,"ex":3,"alc":0,"web":1,"w":10.5,"pr":"B","sub":"Conversión de actos viciados — Los actos nulos o anulables que contengan los elementos constitutivos de otro distinto producirán los efectos de este."},{"law":"lpac","art":"70","t":"Artículo 70. Expediente Administrativo.","mat":"Expediente administrativo","cl":"Conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento a la resolución y diligencias de ejecución. Formato electrónico, índice numerado. No forman parte: información auxiliar o de apoyo (notas, borradores, opiniones, resúmenes, informes internos).","note":"Expediente: electrónico, ordenado y con ÍNDICE numerado. NO incluye borradores, notas, opiniones ni informes internos, salvo los informes (preceptivos o facultativos) pedidos antes de la resolución.","n":3,"ex":3,"alc":0,"web":1,"w":10.5,"pr":"B","sub":"Expediente administrativo — Conjunto ordenado de documentos y actuaciones que sirven de antecedente y fundamento a la resolución y diligencias de ejecución. Formato electrónico, índice numerado. No forman parte: información auxiliar o de apoyo (notas, borradores, opiniones, resúmenes, informes internos)."},{"law":"lpac","art":"76","t":"Artículo 76. Alegaciones.","mat":"Alegaciones","cl":"Los interesados pueden aducir alegaciones y aportar documentos en cualquier momento anterior al trámite de audiencia; se tienen en cuenta en la propuesta de resolución.","note":"Alegar: en CUALQUIER momento ANTES de la audiencia. Los defectos de tramitación (paralización, infracción de plazos) se pueden alegar siempre.","n":3,"ex":3,"alc":0,"web":1,"w":10.5,"pr":"B","sub":"Alegaciones — Los interesados pueden aducir alegaciones y aportar documentos en cualquier momento anterior al trámite de audiencia; se tienen en cuenta en la propuesta de resolución."},{"law":"lpac","art":"102","t":"Artículo 102. Ejecución subsidiaria.","mat":"Ejecución subsidiaria","cl":"Actos no personalísimos que puede realizar otro; por la Administración o personas que designe, a costa del obligado; liquidación provisional y cobro anticipado.","note":"Ejecución subsidiaria = lo hace OTRO (no personalísimo) y lo PAGA el obligado (se puede cobrar por anticipado).","n":3,"ex":3,"alc":0,"web":1,"w":10.5,"pr":"B","sub":"Ejecución subsidiaria — Actos no personalísimos que puede realizar otro; por la Administración o personas que designe, a costa del obligado; liquidación provisional y cobro anticipado."},{"law":"lrjsp","art":"12","t":"Artículo 12. Delegación de firma.","mat":"Delegación de firma","cl":"Los titulares de órganos pueden delegar la firma de sus resoluciones y actos en titulares de órganos o unidades dependientes, dentro de los límites del art. 9. No altera la competencia ni requiere publicación; se hace constar en la resolución.","note":"Delegación de FIRMA: solo en subordinados, NO cambia la competencia y NO se publica (a diferencia de la delegación de competencias, que SÍ se publica).","n":2,"ex":1,"alc":0,"web":2,"w":9.5,"pr":"B","sub":"Delegación de firma — Los titulares de órganos pueden delegar la firma de sus resoluciones y actos en titulares de órganos o unidades dependientes, dentro de los límites del art. 9. No altera la competencia ni requiere publicación; se hace constar en la resolución."},{"law":"lpac","art":"117","t":"Artículo 117. Suspensión de la ejecución.","mat":"Suspensión de la ejecución","cl":"El recurso no suspende salvo disposición. Suspensión ponderada si perjuicios de imposible o difícil reparación o causa de nulidad. Suspendido si no se resuelve en 1 mes desde la solicitud. Caución.","note":"Silencio en la solicitud de suspensión: si no hay resolución en 1 MES desde la entrada en el registro, se entiende SUSPENDIDA. Causas para suspender: perjuicio IRREPARABLE o causa de NULIDAD del 47.1.","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Suspensión de la ejecución — El recurso no suspende salvo disposición. Suspensión ponderada si perjuicios de imposible o difícil reparación o causa de nulidad. Suspendido si no se resuelve en 1 mes desde la solicitud. Caución."},{"law":"lpac","art":"119","t":"Artículo 119. Resolución.","mat":"Resolución del recurso","cl":"Estima total o parcialmente, desestima o inadmite. Vicio de forma: retroacción. Decide todas las cuestiones, oyendo antes; congruente y sin agravar la situación inicial.","note":"Resolver recurso: estimar, desestimar o INADMITIR. Vicio de FORMA = RETROACCIÓN. Prohibida la reformatio in peius.","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Resolución del recurso — Estima total o parcialmente, desestima o inadmite. Vicio de forma: retroacción. Decide todas las cuestiones, oyendo antes; congruente y sin agravar la situación inicial."},{"law":"lpac","art":"123","t":"Artículo 123. Objeto y naturaleza.","mat":"Recurso de reposición: objeto","cl":"Potestativo contra actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó. No se puede ir al contencioso hasta que se resuelva o se desestime por silencio.","note":"Reposición = POTESTATIVO, ante el MISMO órgano, contra actos que AGOTAN la vía. Si recurres en reposición, esperas su resolución antes del contencioso.","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Recurso de reposición: objeto — Potestativo contra actos que ponen fin a la vía administrativa, ante el mismo órgano que los dictó. No se puede ir al contencioso hasta que se resuelva o se desestime por silencio."},{"law":"lpac","art":"133","t":"Artículo 133. Participación de los ciudadanos en el procedimiento de elaboración de normas con rango de Ley y reglamentos.","mat":"Participación ciudadana en la elaboración de normas","cl":"Consulta pública previa en el portal web (problemas, necesidad, objetivos, alternativas). Audiencia e información pública del texto. Se puede prescindir en normas presupuestarias u organizativas o por razones graves de interés público.","note":"Consulta previa «PRO-NE-OB-AL»: PROblemas · NEcesidad y oportunidad · OBjetivos · ALternativas. Se puede prescindir en normas PRESUPUESTARIAS u ORGANIZATIVAS o por razones graves de interés público.","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Participación ciudadana en la elaboración de normas — Consulta pública previa en el portal web (problemas, necesidad, objetivos, alternativas). Audiencia e información pública del texto. Se puede prescindir en normas presupuestarias u organizativas o por razones graves de interés público."},{"law":"lrjsp","art":"6","t":"Artículo 6. Instrucciones y órdenes de servicio.","mat":"Instrucciones y órdenes de servicio","cl":"Dirigen la actividad de los órganos dependientes; publicación cuando proceda. Su incumplimiento no afecta por sí solo a la validez de los actos, sin perjuicio de responsabilidad disciplinaria.","note":"Incumplir una instrucción: el acto sigue siendo VÁLIDO, pero el funcionario puede tener responsabilidad DISCIPLINARIA.","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Instrucciones y órdenes de servicio — Dirigen la actividad de los órganos dependientes; publicación cuando proceda. Su incumplimiento no afecta por sí solo a la validez de los actos, sin perjuicio de responsabilidad disciplinaria."},{"law":"lrjsp","art":"26","t":"Artículo 26. Irretroactividad.","mat":"Irretroactividad","cl":"Se aplican las disposiciones vigentes al cometerse los hechos; retroactivas si favorecen al infractor (tipificación, sanción y prescripción), incluso con sanciones pendientes de cumplimiento.","note":"Lo FAVORABLE es retroactivo (también en plazos de prescripción y aunque la sanción esté pendiente de cumplir). Lo desfavorable, NUNCA.","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Irretroactividad — Se aplican las disposiciones vigentes al cometerse los hechos; retroactivas si favorecen al infractor (tipificación, sanción y prescripción), incluso con sanciones pendientes de cumplimiento."},{"law":"lrjsp","art":"27","t":"Artículo 27. Principio de tipicidad.","mat":"Principio de tipicidad","cl":"Solo son infracciones las previstas por ley (leves, graves y muy graves); sanciones delimitadas por ley; los reglamentos pueden especificar o graduar sin crear nuevas; prohibida la analogía.","note":"Tipicidad: infracción y sanción por LEY; el reglamento solo GRADÚA o ESPECIFICA. Prohibida la ANALOGÍA. Clasificación: leves, graves y muy graves.","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Principio de tipicidad — Solo son infracciones las previstas por ley (leves, graves y muy graves); sanciones delimitadas por ley; los reglamentos pueden especificar o graduar sin crear nuevas; prohibida la analogía."},{"law":"lrjsp","art":"34","t":"Artículo 34. Indemnización.","mat":"Indemnización","cl":"Solo daños que no haya deber jurídico de soportar; no indemnizables los imprevisibles según el estado de la ciencia o técnica. Criterios de la legislación fiscal, de expropiación forzosa; baremos en muerte o lesiones. Referencia al día de la lesión, actualizada con el Índice de Garantía de la Competitividad. En especie o pagos periódicos con acuerdo.","note":"Indemnización: valor al DÍA en que se produjo la lesión, actualizado con el ÍNDICE DE GARANTÍA DE LA COMPETITIVIDAD (no el IPC). Riesgos del desarrollo («estado de la ciencia») NO se indemnizan. En especie o a plazos solo con ACUERDO del interesado.","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Indemnización — Solo daños que no haya deber jurídico de soportar; no indemnizables los imprevisibles según el estado de la ciencia o técnica. Criterios de la legislación fiscal, de expropiación forzosa; baremos en muerte o lesiones. Referencia al día de la lesión, actualizada con el Índice de Garantía de la Competitividad. En especie o pagos periódicos con acuerdo."},{"law":"lrjsp","art":"41","t":"Artículo 41. Actuación administrativa automatizada.","mat":"Actuación administrativa automatizada","cl":"Acto realizado íntegramente por medios electrónicos sin intervención directa de un empleado público. Se fija previamente el órgano responsable de especificaciones, programación, control y auditoría, y el responsable a efectos de impugnación.","note":"Automatizada = SIN intervención DIRECTA de un empleado público. Hay que fijar ANTES quién programa, supervisa y responde a efectos de IMPUGNACIÓN.","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Actuación administrativa automatizada — Acto realizado íntegramente por medios electrónicos sin intervención directa de un empleado público. Se fija previamente el órgano responsable de especificaciones, programación, control y auditoría, y el responsable a efectos de impugnación."},{"law":"lrjsp","art":"47","t":"Artículo 47. Definición y tipos de convenios.","mat":"Convenios: definición y tipos","cl":"Acuerdos con efectos jurídicos para un fin común. No lo son los protocolos generales de actuación. No pueden tener por objeto prestaciones de contratos. Tipos: interadministrativos, intradministrativos, con sujetos de derecho privado y con sujetos de derecho internacional.","note":"Convenio = efectos JURÍDICOS. Protocolo general = mera declaración de INTENCIONES (no es convenio). Ningún convenio puede encubrir un CONTRATO. Tipos «INTER-INTRA-PRIVADO-INTERNACIONAL».","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Convenios: definición y tipos — Acuerdos con efectos jurídicos para un fin común. No lo son los protocolos generales de actuación. No pueden tener por objeto prestaciones de contratos. Tipos: interadministrativos, intradministrativos, con sujetos de derecho privado y con sujetos de derecho internacional."},{"law":"lrjsp","art":"84","t":"Artículo 84. Composición y clasificación del sector público institucional estatal.","mat":"Composición del sector público institucional estatal","cl":"Organismos públicos (organismos autónomos, entidades públicas empresariales, agencias estatales), autoridades administrativas independientes, sociedades mercantiles estatales, consorcios, fundaciones del sector público, fondos sin personalidad y universidades no transferidas.","note":"Organismos públicos estatales «O-E-A»: Organismos autónomos, Entidades públicas empresariales y Agencias estatales. El resto (autoridades independientes, sociedades, consorcios, fundaciones, fondos, universidades no transferidas) NO son organismos públicos.","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Composición del sector público institucional estatal — Organismos públicos (organismos autónomos, entidades públicas empresariales, agencias estatales), autoridades administrativas independientes, sociedades mercantiles estatales, consorcios, fundaciones del sector público, fondos sin personalidad y universidades no transferidas."},{"law":"lrjsp","art":"140","t":"Artículo 140. Principios de las relaciones interadministrativas.","mat":"Principios de las relaciones interadministrativas","cl":"Lealtad institucional, adecuación al orden competencial, colaboración, cooperación (voluntaria), coordinación (obligatoria), eficiencia, responsabilidad, garantía e igualdad, solidaridad interterritorial.","note":"Colaboración = deber de ayudar; Cooperación = VOLUNTARIA, compromisos específicos; Coordinación = OBLIGACIÓN de garantizar la coherencia (sobre todo la AGE).","n":1,"ex":1,"alc":0,"web":2,"w":8.5,"pr":"B","sub":"Principios de las relaciones interadministrativas — Lealtad institucional, adecuación al orden competencial, colaboración, cooperación (voluntaria), coordinación (obligatoria), eficiencia, responsabilidad, garantía e igualdad, solidaridad interterritorial."},{"law":"lpac","art":"7","t":"Artículo 7. Pluralidad de interesados.","mat":"Pluralidad de interesados","cl":"Las actuaciones se efectúan con el representante o interesado que hayan señalado expresamente y, en su defecto, con el que figure en primer término.","note":"Varios interesados: se actúa con el que ELIJAN y, si no eligen, con el PRIMERO de la lista.","n":2,"ex":2,"alc":0,"web":1,"w":8.0,"pr":"B","sub":"Pluralidad de interesados — Las actuaciones se efectúan con el representante o interesado que hayan señalado expresamente y, en su defecto, con el que figure en primer término."},{"law":"lpac","art":"23","t":"Artículo 23. Ampliación del plazo máximo para resolver y notificar.","mat":"Ampliación del plazo máximo para resolver","cl":"Excepcional, agotados los medios, acuerdo motivado; nunca superior al plazo del procedimiento; se notifica y no cabe recurso.","note":"Ampliación del plazo para RESOLVER (23): como máximo otro tanto del plazo del procedimiento. Ampliación de plazos de TRÁMITE (32): como máximo la MITAD. Ninguna de las dos es recurrible.","n":2,"ex":2,"alc":0,"web":1,"w":8.0,"pr":"B","sub":"Ampliación del plazo máximo para resolver — Excepcional, agotados los medios, acuerdo motivado; nunca superior al plazo del procedimiento; se notifica y no cabe recurso."},{"law":"lpac","art":"28","t":"Artículo 28. Documentos aportados por los interesados al procedimiento administrativo.","mat":"Documentos aportados por los interesados","cl":"Derecho a no aportar documentos que ya tenga la Administración o elaborados por otra; consulta salvo oposición (no cabe en sanciones o inspección). No se exigen originales salvo excepción. Informes preceptivos de otro órgano: remitidos en 10 días.","note":"«No me pidas lo que ya tienes»: la Administración CONSULTA los documentos salvo que el interesado se OPONGA (no puede oponerse en sancionadores o de inspección). Originales: solo excepcionalmente.","n":2,"ex":2,"alc":0,"web":1,"w":8.0,"pr":"B","sub":"Documentos aportados por los interesados — Derecho a no aportar documentos que ya tenga la Administración o elaborados por otra; consulta salvo oposición (no cabe en sanciones o inspección). No se exigen originales salvo excepción. Informes preceptivos de otro órgano: remitidos en 10 días."},{"law":"lpac","art":"71","t":"Artículo 71. Impulso.","mat":"Impulso","cl":"De oficio en todos sus trámites y por medios electrónicos; orden riguroso de incoación en asuntos homogéneos salvo orden motivada; responsables directos de la tramitación.","note":"Impulso DE OFICIO + orden de LLEGADA en asuntos homogéneos (saltárselo exige orden motivada; si no, responsabilidad disciplinaria y posible remoción).","n":2,"ex":2,"alc":0,"web":1,"w":8.0,"pr":"B","sub":"Impulso — De oficio en todos sus trámites y por medios electrónicos; orden riguroso de incoación en asuntos homogéneos salvo orden motivada; responsables directos de la tramitación."},{"law":"lpac","art":"74","t":"Artículo 74. Cuestiones incidentales.","mat":"Cuestiones incidentales","cl":"No suspenden la tramitación, incluso las de nulidad de actuaciones, salvo la recusación.","note":"Incidentes NO suspenden. Única excepción: la RECUSACIÓN.","n":2,"ex":2,"alc":0,"web":1,"w":8.0,"pr":"B","sub":"Cuestiones incidentales — No suspenden la tramitación, incluso las de nulidad de actuaciones, salvo la recusación."},{"law":"lpac","art":"78","t":"Artículo 78. Práctica de prueba.","mat":"Práctica de prueba","cl":"Comunicación con antelación suficiente (lugar, fecha y hora). Gastos a cargo del interesado que la pida si no la debe soportar la Administración; anticipo a reserva de liquidación.","note":"Prueba a petición del interesado que genera gastos: los paga EL, y la Administración puede pedirle un ANTICIPO.","n":2,"ex":2,"alc":0,"web":1,"w":8.0,"pr":"B","sub":"Práctica de prueba — Comunicación con antelación suficiente (lugar, fecha y hora). Gastos a cargo del interesado que la pida si no la debe soportar la Administración; anticipo a reserva de liquidación."},{"law":"lpac","art":"113","t":"Artículo 113. Recurso extraordinario de revisión.","mat":"Recurso extraordinario de revisión","cl":"Contra actos firmes en vía administrativa, solo por las causas del 125.1.","note":"Extraordinario de revisión = solo contra actos FIRMES y solo por las 4 causas tasadas del art. 125.","n":2,"ex":2,"alc":0,"web":1,"w":8.0,"pr":"B","sub":"Recurso extraordinario de revisión — Contra actos firmes en vía administrativa, solo por las causas del 125.1."},{"law":"lpac","art":"118","t":"Artículo 118. Audiencia de los interesados.","mat":"Audiencia en los recursos","cl":"Hechos o documentos nuevos: alegaciones entre 10 y 15 días. No se tienen en cuenta los que pudo aportar antes. Otros interesados: traslado del recurso.","note":"Audiencia en recursos: solo si hay hechos NUEVOS, 10-15 días. El recurso, los informes y las propuestas NO son documentos nuevos.","n":2,"ex":2,"alc":0,"web":1,"w":8.0,"pr":"B","sub":"Audiencia en los recursos — Hechos o documentos nuevos: alegaciones entre 10 y 15 días. No se tienen en cuenta los que pudo aportar antes. Otros interesados: traslado del recurso."},{"law":"lrjsp","art":"15","t":"Artículo 15. Régimen.","mat":"Órganos colegiados: régimen","cl":"Normas de esta sección, con peculiaridades organizativas. Colegiados con organizaciones representativas o de varias Administraciones: pueden completar sus normas. Publicación del acuerdo de creación si dictan resoluciones con efectos frente a terceros.","note":"Colegiados con efectos frente a terceros: su creación y normas se PUBLICAN en el boletín.","n":2,"ex":2,"alc":0,"web":1,"w":8.0,"pr":"B","sub":"Órganos colegiados: régimen — Normas de esta sección, con peculiaridades organizativas. Colegiados con organizaciones representativas o de varias Administraciones: pueden completar sus normas. Publicación del acuerdo de creación si dictan resoluciones con efectos frente a terceros."},{"law":"lpac","art":"54","t":"Artículo 54. Clases de iniciación.","mat":"Clases de iniciación","cl":"De oficio o a solicitud del interesado.","note":"Dos puertas: OFICIO o SOLICITUD.","n":3,"ex":3,"alc":0,"web":0,"w":7.5,"pr":"B","sub":"Clases de iniciación — De oficio o a solicitud del interesado."},{"law":"lpac","art":"58","t":"Artículo 58. Iniciación de oficio.","mat":"Iniciación de oficio","cl":"Por acuerdo del órgano competente, por propia iniciativa, orden superior, petición razonada de otros órganos o denuncia.","note":"Iniciación de oficio «PrOPeDe»: PRopia iniciativa · Orden superior · PEtición razonada · DEnuncia.","n":0,"ex":0,"alc":0,"web":2,"w":6.0,"pr":"B","sub":"Iniciación de oficio — Por acuerdo del órgano competente, por propia iniciativa, orden superior, petición razonada de otros órganos o denuncia."},{"law":"lpac","art":"87","t":"Artículo 87. Actuaciones complementarias.","mat":"Actuaciones complementarias","cl":"Antes de resolver, por acuerdo motivado; se practican en un plazo no superior a 15 días; alegaciones en 7 días tras su finalización. El plazo para resolver queda suspendido.","note":"Actuaciones complementarias «15-7»: se practican en máximo 15 días; alegaciones en 7. Suspenden el plazo para resolver (suspensión obligatoria del 22.2).","n":0,"ex":0,"alc":0,"web":2,"w":6.0,"pr":"B","sub":"Actuaciones complementarias — Antes de resolver, por acuerdo motivado; se practican en un plazo no superior a 15 días; alegaciones en 7 días tras su finalización. El plazo para resolver queda suspendido."},{"law":"lpac","art":"129","t":"Artículo 129. Principios de buena regulación.","mat":"Principios de buena regulación","cl":"Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia; justificación en la exposición de motivos o preámbulo.","note":"Buena regulación «NE-EFI-PRO-SE-TRA-EFI»: NEcesidad · EFIcacia · PROporcionalidad · SEguridad jurídica · TRAnsparencia · EFIciencia. Truco: «las dos EFI» van en los extremos (eficacia al principio, eficiencia al final).","n":0,"ex":0,"alc":0,"web":2,"w":6.0,"pr":"B","sub":"Principios de buena regulación — Necesidad, eficacia, proporcionalidad, seguridad jurídica, transparencia y eficiencia; justificación en la exposición de motivos o preámbulo."},{"law":"lrjsp","art":"2","t":"Artículo 2. Ámbito Subjetivo.","mat":"Ámbito subjetivo de la LRJSP","cl":"Sector público: AGE, CCAA, Entidades Locales y sector público institucional (organismos y entidades de derecho público, entidades de derecho privado vinculadas, Universidades públicas).","note":"Son Administraciones Públicas: AGE, CCAA, EELL y organismos/entidades de DERECHO PÚBLICO. Las entidades de derecho privado y las Universidades están en el sector público institucional, pero NO son Administración Pública.","n":0,"ex":0,"alc":0,"web":2,"w":6.0,"pr":"C","sub":"Ámbito subjetivo de la LRJSP — Sector público: AGE, CCAA, Entidades Locales y sector público institucional (organismos y entidades de derecho público, entidades de derecho privado vinculadas, Universidades públicas)."},{"law":"lrjsp","art":"11","t":"Artículo 11. Encomiendas de gestión.","mat":"Encomienda de gestión","cl":"Actividades materiales o técnicas, por eficacia o falta de medios; a órganos o entidades de la misma o distinta Administración. No prestaciones de contratos. No cede titularidad ni elementos sustantivos. Misma Administración: acuerdo y publicación; distintas Administraciones: convenio publicado.","note":"Encomienda = solo lo MATERIAL o TÉCNICO; la competencia y las resoluciones siguen siendo del ENCOMENDANTE. Nunca prestaciones propias de CONTRATOS. Entre Administraciones distintas: CONVENIO. El encomendado es encargado del tratamiento de datos.","n":0,"ex":0,"alc":0,"web":2,"w":6.0,"pr":"C","sub":"Encomienda de gestión — Actividades materiales o técnicas, por eficacia o falta de medios; a órganos o entidades de la misma o distinta Administración. No prestaciones de contratos. No cede titularidad ni elementos sustantivos. Misma Administración: acuerdo y publicación; distintas Administraciones: convenio publicado."},{"law":"lrjsp","art":"13","t":"Artículo 13. Suplencia.","mat":"Suplencia","cl":"Vacante, ausencia, enfermedad, abstención o recusación. Si no hay designación: quien designe el órgano inmediato superior. No altera la competencia ni requiere publicación.","note":"Suplencia «VA-AU-EN-AB-RE»: VAcante, AUsencia, ENfermedad, ABstención y REcusación. Sin publicación. Sin suplente designado: lo designa el SUPERIOR inmediato.","n":0,"ex":0,"alc":0,"web":2,"w":6.0,"pr":"C","sub":"Suplencia — Vacante, ausencia, enfermedad, abstención o recusación. Si no hay designación: quien designe el órgano inmediato superior. No altera la competencia ni requiere publicación."},{"law":"lrjsp","art":"16","t":"Artículo 16. Secretario.","mat":"Secretario del órgano colegiado","cl":"Puede ser miembro o persona al servicio de la Administración. Vela por la legalidad formal y material, certifica y garantiza el respeto de las reglas de constitución y adopción de acuerdos.","note":"Secretario: puede ser MIEMBRO o NO. Si no es miembro: voz sin voto. Vela por la legalidad y CERTIFICA.","n":0,"ex":0,"alc":0,"web":2,"w":6.0,"pr":"C","sub":"Secretario del órgano colegiado — Puede ser miembro o persona al servicio de la Administración. Vela por la legalidad formal y material, certifica y garantiza el respeto de las reglas de constitución y adopción de acuerdos."},{"law":"lrjsp","art":"19","t":"Artículo 19. Régimen de los órganos colegiados de la Administración General del Estado y de las Entidades de Derecho Público vinculadas o dependientes de ella.","mat":"Colegiados de la AGE","cl":"Presidente: representación, convocatoria y orden del día, dirimir empates con voto de calidad, visar actas. Miembros: convocatoria con 2 días de antelación, voto particular por escrito en 2 días; no pueden abstenerse los miembros natos. Secretario: voz sin voto si no es miembro.","note":"«2 y 2»: convocatoria con 2 DÍAS de antelación y voto particular por escrito en 2 DÍAS. El Presidente DIRIME empates. Los miembros natos (por su cargo) NO pueden abstenerse.","n":0,"ex":0,"alc":0,"web":2,"w":6.0,"pr":"C","sub":"Colegiados de la AGE — Presidente: representación, convocatoria y orden del día, dirimir empates con voto de calidad, visar actas. Miembros: convocatoria con 2 días de antelación, voto particular por escrito en 2 días; no pueden abstenerse los miembros natos. Secretario: voz sin voto si no es miembro."},{"law":"lrjsp","art":"24","t":"Artículo 24. Recusación.","mat":"Recusación","cl":"En cualquier momento de la tramitación, por escrito con la causa. Al día siguiente el recusado dice si concurre; si la niega, el superior resuelve en 3 días. Sin recurso (se alega al recurrir la resolución final).","note":"Recusación «1-3-NR»: el recusado contesta al DÍA siguiente; si lo niega, el superior resuelve en 3 DÍAS; No Recurrible directamente. Suspende el plazo para resolver (22.2) y es la única cuestión incidental que suspende la tramitación (74 LPAC).","n":0,"ex":0,"alc":0,"web":2,"w":6.0,"pr":"C","sub":"Recusación — En cualquier momento de la tramitación, por escrito con la causa. Al día siguiente el recusado dice si concurre; si la niega, el superior resuelve en 3 días. Sin recurso (se alega al recurrir la resolución final)."},{"law":"lrjsp","art":"31","t":"Artículo 31. Concurrencia de sanciones.","mat":"Concurrencia de sanciones","cl":"Non bis in idem: no se sancionan hechos ya sancionados penal o administrativamente con identidad de sujeto, hecho y fundamento. Sanción UE previa: se tiene en cuenta para graduar.","note":"«Non bis in idem» = triple identidad «SU-HE-FU»: SUjeto, HEcho y FUndamento.","n":0,"ex":0,"alc":0,"web":2,"w":6.0,"pr":"C","sub":"Concurrencia de sanciones — Non bis in idem: no se sancionan hechos ya sancionados penal o administrativamente con identidad de sujeto, hecho y fundamento. Sanción UE previa: se tiene en cuenta para graduar."},{"law":"lrjsp","art":"49","t":"Artículo 49. Contenido de los convenios.","mat":"Contenido de los convenios","cl":"Sujetos y capacidad, competencia, objeto y actuaciones, compromisos económicos, consecuencias del incumplimiento, mecanismo de seguimiento, régimen de modificación (unanimidad si no se regula) y vigencia: máximo 4 años, prorrogables hasta 4 más por unanimidad.","note":"Convenio «4 + 4»: duración máxima 4 AÑOS (salvo norma), prórroga de hasta otros 4 por acuerdo UNÁNIME antes de que termine. Modificación sin regla propia: UNANIMIDAD.","n":0,"ex":0,"alc":0,"web":2,"w":6.0,"pr":"C","sub":"Contenido de los convenios — Sujetos y capacidad, competencia, objeto y actuaciones, compromisos económicos, consecuencias del incumplimiento, mecanismo de seguimiento, régimen de modificación (unanimidad si no se regula) y vigencia: máximo 4 años, prorrogables hasta 4 más por unanimidad."},{"law":"lpac","art":"12","t":"Artículo 12. Asistencia en el uso de medios electrónicos a los interesados.","mat":"Asistencia en el uso de medios electrónicos","cl":"Para los no obligados del art. 14.2 y 14.3; un funcionario habilitado puede identificar o firmar por el interesado con su consentimiento expreso; registro de funcionarios habilitados.","note":"Funcionario habilitado: firma POR el interesado que no tiene medios, si este se identifica ante él y CONSIENTE expresamente. Solo para quien NO está obligado a la vía electrónica.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Asistencia en el uso de medios electrónicos — Para los no obligados del art. 14.2 y 14.3; un funcionario habilitado puede identificar o firmar por el interesado con su consentimiento expreso; registro de funcionarios habilitados."},{"law":"lpac","art":"15","t":"Artículo 15. Lengua de los procedimientos.","mat":"Lengua de los procedimientos","cl":"AGE: castellano, salvo que el interesado use la cooficial en su CCAA. CCAA y EELL: según la legislación autonómica. Traducción al castellano de lo que deba surtir efectos fuera de la CCAA.","note":"Lengua: en la AGE, castellano, pero si el interesado se dirige en valenciano a un órgano con sede en la Comunitat, se tramita en valenciano. Si hay varios interesados y discrepan: CASTELLANO.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Lengua de los procedimientos — AGE: castellano, salvo que el interesado use la cooficial en su CCAA. CCAA y EELL: según la legislación autonómica. Traducción al castellano de lo que deba surtir efectos fuera de la CCAA."},{"law":"lpac","art":"55","t":"Artículo 55. Información y actuaciones previas.","mat":"Información y actuaciones previas","cl":"Antes de iniciar: período de información o actuaciones previas. En sancionadores, por órganos de investigación o inspección.","note":"Actuaciones previas: para saber si conviene abrir el procedimiento. NO interrumpen la prescripción (solo la iniciación con conocimiento del interesado).","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Información y actuaciones previas — Antes de iniciar: período de información o actuaciones previas. En sancionadores, por órganos de investigación o inspección."},{"law":"lpac","art":"57","t":"Artículo 57. Acumulación.","mat":"Acumulación","cl":"De oficio o a instancia, con procedimientos de identidad sustancial o íntima conexión, siempre que los tramite y resuelva el mismo órgano. No cabe recurso.","note":"Acumular: identidad sustancial o íntima conexión + MISMO órgano. No recurrible.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Acumulación — De oficio o a instancia, con procedimientos de identidad sustancial o íntima conexión, siempre que los tramite y resuelva el mismo órgano. No cabe recurso."},{"law":"lpac","art":"65","t":"Artículo 65. Especialidades en el inicio de oficio de los procedimientos de responsabilidad patrimonial.","mat":"Inicio de oficio de responsabilidad patrimonial","cl":"Exige que no haya prescrito el derecho a reclamar; 10 días a los presuntos lesionados para alegaciones, documentos y pruebas.","note":"De oficio en responsabilidad patrimonial: derecho no PRESCRITO (1 año) + 10 DÍAS a los lesionados. Se instruye aunque no se personen.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Inicio de oficio de responsabilidad patrimonial — Exige que no haya prescrito el derecho a reclamar; 10 días a los presuntos lesionados para alegaciones, documentos y pruebas."},{"law":"lpac","art":"66","t":"Artículo 66. Solicitudes de iniciación.","mat":"Solicitudes de iniciación","cl":"Contenido: identidad e identificación del medio de notificación, hechos, razones y petición, lugar y fecha, firma, órgano destinatario con su código DIR3. Una sola solicitud para varias personas con contenido idéntico. Recibo.","note":"Solicitud «NO-HE-LU-FI-OR»: NOmbre y medio de notificación · HEchos y petición · LUgar y fecha · FIrma · ÓRgano destinatario (código DIR3).","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Solicitudes de iniciación — Contenido: identidad e identificación del medio de notificación, hechos, razones y petición, lugar y fecha, firma, órgano destinatario con su código DIR3. Una sola solicitud para varias personas con contenido idéntico. Recibo."},{"law":"lpac","art":"72","t":"Artículo 72. Concentración de trámites.","mat":"Concentración de trámites","cl":"Se acuerdan en un solo acto todos los trámites que admitan impulso simultáneo; al pedir trámites a otros órganos se indica el plazo legal.","note":"Concentración: todo lo que pueda ir junto, en UN acto (simplificación administrativa).","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Concentración de trámites — Se acuerdan en un solo acto todos los trámites que admitan impulso simultáneo; al pedir trámites a otros órganos se indica el plazo legal."},{"law":"lpac","art":"89","t":"Artículo 89. Propuesta de resolución en los procedimientos de carácter sancionador.","mat":"Propuesta de resolución en sancionadores","cl":"Archivo sin propuesta si: hechos inexistentes, no acreditados, no constitutivos de infracción, responsables no identificados o exentos, infracción prescrita. Propuesta notificada con plazo de alegaciones.","note":"Archivo directo «I-NA-NI-NR-P»: hechos Inexistentes · No Acreditados · No constitutivos de Infracción · No hay Responsable · Prescrita.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Propuesta de resolución en sancionadores — Archivo sin propuesta si: hechos inexistentes, no acreditados, no constitutivos de infracción, responsables no identificados o exentos, infracción prescrita. Propuesta notificada con plazo de alegaciones."},{"law":"lpac","art":"93","t":"Artículo 93. Desistimiento por la Administración.","mat":"Desistimiento por la Administración","cl":"En procedimientos de oficio, motivadamente, en los supuestos y con los requisitos de las leyes.","note":"La Administración solo DESISTE en procedimientos DE OFICIO y motivadamente.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Desistimiento por la Administración — En procedimientos de oficio, motivadamente, en los supuestos y con los requisitos de las leyes."},{"law":"lpac","art":"99","t":"Artículo 99. Ejecución forzosa.","mat":"Ejecución forzosa","cl":"Previo apercibimiento, salvo suspensión o ley; respeto a la proporcionalidad: medio menos restrictivo de la libertad individual.","note":"Ejecución forzosa: siempre APERCIBIMIENTO previo y el medio MENOS restrictivo.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Ejecución forzosa — Previo apercibimiento, salvo suspensión o ley; respeto a la proporcionalidad: medio menos restrictivo de la libertad individual."},{"law":"lpac","art":"103","t":"Artículo 103. Multa coercitiva.","mat":"Multa coercitiva","cl":"Cuando lo autoricen las leyes, reiterada por lapsos suficientes: actos personalísimos sin compulsión, actos en que no se estime conveniente la compulsión, actos que el obligado pueda encargar a otro. Independiente y compatible con las sanciones.","note":"Multa coercitiva: NO es sanción (compatible con ella); exige LEY que la autorice y se repite hasta que se cumpla.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Multa coercitiva — Cuando lo autoricen las leyes, reiterada por lapsos suficientes: actos personalísimos sin compulsión, actos en que no se estime conveniente la compulsión, actos que el obligado pueda encargar a otro. Independiente y compatible con las sanciones."},{"law":"lpac","art":"104","t":"Artículo 104. Compulsión sobre las personas.","mat":"Compulsión sobre las personas","cl":"Actos personalísimos de no hacer o soportar, si una ley lo autoriza, con respeto a la dignidad. Obligaciones personalísimas de hacer: indemnización de daños.","note":"Compulsión: solo NO HACER o SOPORTAR; si es un HACER personalísimo que no se cumple → indemnización.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Compulsión sobre las personas — Actos personalísimos de no hacer o soportar, si una ley lo autoriza, con respeto a la dignidad. Obligaciones personalísimas de hacer: indemnización de daños."},{"law":"lpac","art":"115","t":"Artículo 115. Interposición de recurso.","mat":"Interposición de recurso","cl":"Contenido mínimo; el error en la calificación no impide su tramitación si se deduce su carácter. Vicios no alegables por quien los causó.","note":"Error en el nombre del recurso: NO importa si se deduce su verdadero carácter. Quien causó el vicio NO puede alegarlo.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Interposición de recurso — Contenido mínimo; el error en la calificación no impide su tramitación si se deduce su carácter. Vicios no alegables por quien los causó."},{"law":"lpac","art":"126","t":"Artículo 126. Resolución.","mat":"Resolución del extraordinario de revisión","cl":"Inadmisión sin dictamen si no se funda en las causas tasadas o hay desestimados iguales. Se pronuncia sobre la procedencia y el fondo. 3 meses: desestimado.","note":"Extraordinario: 3 MESES sin resolver = DESESTIMADO y vía contenciosa expedita.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Resolución del extraordinario de revisión — Inadmisión sin dictamen si no se funda en las causas tasadas o hay desestimados iguales. Se pronuncia sobre la procedencia y el fondo. 3 meses: desestimado."},{"law":"lpac","art":"128","t":"Artículo 128. Potestad reglamentaria.","mat":"Potestad reglamentaria","cl":"Gobierno de la Nación, órganos de gobierno de las CCAA y órganos de gobierno locales (ordenanzas). Jerarquía; no pueden vulnerar la CE ni las leyes ni regular materias reservadas a ley; no tipificar delitos ni sanciones ni tributos.","note":"Reglamento: NO puede «TIP-TRI-RES»: TIPificar delitos, faltas o infracciones administrativas ni establecer penas o sanciones · TRIbutos, exacciones o prestaciones patrimoniales · materias RESERVADAS a ley.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Potestad reglamentaria — Gobierno de la Nación, órganos de gobierno de las CCAA y órganos de gobierno locales (ordenanzas). Jerarquía; no pueden vulnerar la CE ni las leyes ni regular materias reservadas a ley; no tipificar delitos ni sanciones ni tributos."},{"law":"lrjsp","art":"1","t":"Artículo 1. Objeto.","mat":"Objeto de la LRJSP","cl":"Bases del régimen jurídico de las AAPP, principios de la responsabilidad patrimonial y de la potestad sancionadora, organización y funcionamiento de la AGE y su sector público institucional.","note":"LRJSP = cómo se ORGANIZA y FUNCIONA la Administración «por dentro» (órganos, competencia, colegiados, sanción y responsabilidad: principios). La LPAC regula la relación con los ciudadanos «hacia fuera» (procedimiento).","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Objeto de la LRJSP — Bases del régimen jurídico de las AAPP, principios de la responsabilidad patrimonial y de la potestad sancionadora, organización y funcionamiento de la AGE y su sector público institucional."},{"law":"lrjsp","art":"33","t":"Artículo 33. Responsabilidad concurrente de las Administraciones Públicas.","mat":"Responsabilidad concurrente","cl":"Fórmulas conjuntas de actuación: responsabilidad solidaria frente al particular. Otros casos: según competencia, interés público tutelado e intensidad de intervención; solidaria si no es posible determinarla. Consulta a las demás Administraciones en 15 días.","note":"Actuación CONJUNTA: SOLIDARIA siempre frente al particular. Concurrencia no conjunta: reparto por competencia, interés e intensidad; si no se puede repartir, solidaria.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Responsabilidad concurrente — Fórmulas conjuntas de actuación: responsabilidad solidaria frente al particular. Otros casos: según competencia, interés público tutelado e intensidad de intervención; solidaria si no es posible determinarla. Consulta a las demás Administraciones en 15 días."},{"law":"lrjsp","art":"38","t":"Artículo 38. La sede electrónica.","mat":"Sede electrónica","cl":"Dirección electrónica de titularidad de una Administración. Responsabilidad del titular por la integridad, veracidad y actualización. Certificados cualificados de autenticación de sitio web.","note":"Sede = dirección electrónica OFICIAL: su titular responde de la integridad, veracidad y actualización de lo que publica.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Sede electrónica — Dirección electrónica de titularidad de una Administración. Responsabilidad del titular por la integridad, veracidad y actualización. Certificados cualificados de autenticación de sitio web."},{"law":"lrjsp","art":"39","t":"Artículo 39. Portal de internet.","mat":"Portal de internet","cl":"Punto de acceso electrónico de una Administración que permite el acceso a la información publicada y, en su caso, a la sede.","note":"Portal = la puerta de INFORMACIÓN; Sede = donde se TRAMITA con efectos jurídicos.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Portal de internet — Punto de acceso electrónico de una Administración que permite el acceso a la información publicada y, en su caso, a la sede."},{"law":"lrjsp","art":"53","t":"Artículo 53. Remisión de convenios al Tribunal de Cuentas.","mat":"Remisión al Tribunal de Cuentas","cl":"Convenios con compromisos económicos superiores a 600.000 euros: remisión electrónica en 3 meses al Tribunal de Cuentas u órgano autonómico.","note":"Convenios «600.000 → 3 meses» al Tribunal de Cuentas (o la Sindicatura de Comptes).","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Remisión al Tribunal de Cuentas — Convenios con compromisos económicos superiores a 600.000 euros: remisión electrónica en 3 meses al Tribunal de Cuentas u órgano autonómico."},{"law":"lrjsp","art":"81","t":"Artículo 81. Principios generales de actuación.","mat":"Principios del sector público institucional","cl":"Legalidad, eficiencia, estabilidad presupuestaria, sostenibilidad financiera y transparencia. Sistema de supervisión continua de las entidades dependientes.","note":"Sector público institucional «LE-EFI-ES-SOS-TRANS»: LEgalidad, EFIciencia, EStabilidad presupuestaria, SOStenibilidad financiera y TRANSparencia.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Principios del sector público institucional — Legalidad, eficiencia, estabilidad presupuestaria, sostenibilidad financiera y transparencia. Sistema de supervisión continua de las entidades dependientes."},{"law":"lrjsp","art":"123","t":"Artículo 123. Creación.","mat":"Creación de consorcios","cl":"Mediante convenio de las Administraciones participantes. Si participa la AGE: autorización por ley y del Consejo de Ministros.","note":"El consorcio nace por CONVENIO.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Creación de consorcios — Mediante convenio de las Administraciones participantes. Si participa la AGE: autorización por ley y del Consejo de Ministros."},{"law":"lrjsp","art":"141","t":"Artículo 141. Deber de colaboración entre las Administraciones Públicas.","mat":"Deber de colaboración","cl":"Respetar competencias ajenas, ponderar intereses, facilitar información, prestar asistencia. Solo se niega si no está facultado, no tiene medios, causa perjuicio grave o la información es confidencial; negativa motivada.","note":"Negar colaboración: solo por falta de FACULTADES, falta de MEDIOS, perjuicio GRAVE o información CONFIDENCIAL, y siempre MOTIVADAMENTE.","n":1,"ex":1,"alc":0,"web":1,"w":5.5,"pr":"C","sub":"Deber de colaboración — Respetar competencias ajenas, ponderar intereses, facilitar información, prestar asistencia. Solo se niega si no está facultado, no tiene medios, causa perjuicio grave o la información es confidencial; negativa motivada."},{"law":"lpac","art":"34","t":"Artículo 34. Producción y contenido.","mat":"Producción y contenido","cl":"Los actos se dictan por el órgano competente, ajustándose a los requisitos y al procedimiento; contenido ajustado al ordenamiento, determinado y adecuado a los fines.","note":"Elementos del acto: órgano COMPETENTE + PROCEDIMIENTO + contenido determinado y adecuado a los fines.","n":2,"ex":2,"alc":0,"web":0,"w":5.0,"pr":"C","sub":"Producción y contenido — Los actos se dictan por el órgano competente, ajustándose a los requisitos y al procedimiento; contenido ajustado al ordenamiento, determinado y adecuado a los fines."},{"law":"lpac","art":"1","t":"Artículo 1. Objeto de la Ley.","mat":"Objeto de la Ley","cl":"Requisitos de validez y eficacia de los actos, procedimiento común (incluido sancionador y de responsabilidad patrimonial), iniciativa legislativa y potestad reglamentaria. Solo por LEY trámites adicionales o distintos.","note":"«Trámites distintos = solo LEY». Por reglamento solo se concretan órganos, plazos propios, formas de iniciación y terminación, publicación e informes a recabar. Sancionador y responsabilidad patrimonial NO tienen procedimiento propio: son especialidades del común.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Objeto de la Ley — Requisitos de validez y eficacia de los actos, procedimiento común (incluido sancionador y de responsabilidad patrimonial), iniciativa legislativa y potestad reglamentaria. Solo por LEY trámites adicionales o distintos."},{"law":"lpac","art":"2","t":"Artículo 2. Ámbito subjetivo de aplicación.","mat":"Ámbito subjetivo","cl":"AGE, CCAA, Entidades Locales y sector público institucional. Corporaciones de Derecho Público (colegios profesionales) y Universidades: normativa específica y supletoriamente esta Ley.","note":"«A-C-L + Institucional». Son Administraciones Públicas: AGE, CCAA, EELL y los organismos y entidades de DERECHO PÚBLICO vinculados. Las entidades de derecho PRIVADO solo cuando ejerzan potestades administrativas.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Ámbito subjetivo — AGE, CCAA, Entidades Locales y sector público institucional. Corporaciones de Derecho Público (colegios profesionales) y Universidades: normativa específica y supletoriamente esta Ley."},{"law":"lpac","art":"9","t":"Artículo 9. Sistemas de identificación de los interesados en el procedimiento.","mat":"Sistemas de identificación de los interesados","cl":"Certificado electrónico cualificado de firma, sello electrónico cualificado o sistemas de clave concertada y cualquier otro que las Administraciones consideren válido.","note":"Identificarse ≠ firmar. Con identificarse basta para casi todo; la firma solo se exige para lo del art. 11.2.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Sistemas de identificación de los interesados — Certificado electrónico cualificado de firma, sello electrónico cualificado o sistemas de clave concertada y cualquier otro que las Administraciones consideren válido."},{"law":"lpac","art":"19","t":"Artículo 19. Comparecencia de las personas.","mat":"Comparecencia de las personas","cl":"Solo obligatoria cuando lo prevea una norma con RANGO DE LEY. La citación indicará lugar, fecha, hora, medios y objeto y los efectos de no atenderla.","note":"Obligar a comparecer = solo por LEY. La citación: dónde, cuándo, cómo, para qué y qué pasa si no vas.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Comparecencia de las personas — Solo obligatoria cuando lo prevea una norma con RANGO DE LEY. La citación indicará lugar, fecha, hora, medios y objeto y los efectos de no atenderla."},{"law":"lpac","art":"46","t":"Artículo 46. Indicación de notificaciones y publicaciones.","mat":"Indicación de notificaciones y publicaciones","cl":"Si la publicación lesiona derechos o intereses legítimos: somera indicación del contenido y lugar donde comparecer.","note":"Si publicar el acto entero perjudica al interesado: solo un EXTRACTO («somera indicación») y dónde puede ir a verlo completo.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Indicación de notificaciones y publicaciones — Si la publicación lesiona derechos o intereses legítimos: somera indicación del contenido y lugar donde comparecer."},{"law":"lpac","art":"79","t":"Artículo 79. Petición.","mat":"Petición de informes","cl":"Se piden los preceptivos y los que se juzguen necesarios, citando el precepto que los exige o fundamentando la conveniencia.","note":"Pedir informe: hay que decir QUÉ norma lo exige o POR QUÉ conviene.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Petición de informes — Se piden los preceptivos y los que se juzguen necesarios, citando el precepto que los exige o fundamentando la conveniencia."},{"law":"lpac","art":"86","t":"Artículo 86. Terminación convencional.","mat":"Terminación convencional","cl":"Acuerdos, pactos, convenios o contratos que no versen sobre materias no susceptibles de transacción; finalizadores o previos a la resolución. Contenido mínimo: partes, ámbito y vigencia.","note":"Pacto: posible si no es contrario al ordenamiento ni sobre materias NO transigibles. No altera competencias. En responsabilidad patrimonial fija cuantía y modo de indemnizar (art. 34 LRJSP).","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Terminación convencional — Acuerdos, pactos, convenios o contratos que no versen sobre materias no susceptibles de transacción; finalizadores o previos a la resolución. Contenido mínimo: partes, ámbito y vigencia."},{"law":"lpac","art":"92","t":"Artículo 92. Competencia para la resolución de los procedimientos de responsabilidad patrimonial.","mat":"Competencia en responsabilidad patrimonial","cl":"AGE: Ministro respectivo o Consejo de Ministros (32.3 LRJSP o si lo dice una ley). CCAA y EELL: sus órganos correspondientes.","note":"AGE: el MINISTRO (Consejo de Ministros en responsabilidad del Estado legislador). En el Ayuntamiento: el órgano que diga su normativa (normalmente el Alcalde).","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Competencia en responsabilidad patrimonial — AGE: Ministro respectivo o Consejo de Ministros (32.3 LRJSP o si lo dice una ley). CCAA y EELL: sus órganos correspondientes."},{"law":"lpac","art":"97","t":"Artículo 97. Título.","mat":"Título","cl":"Las AAPP no iniciarán actuación material de ejecución que limite derechos sin la previa resolución que le sirva de fundamento jurídico.","note":"«Sin título no hay ejecución»: antes de actuar materialmente, resolución que lo fundamente, notificada.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Título — Las AAPP no iniciarán actuación material de ejecución que limite derechos sin la previa resolución que le sirva de fundamento jurídico."},{"law":"lpac","art":"101","t":"Artículo 101. Apremio sobre el patrimonio.","mat":"Apremio sobre el patrimonio","cl":"Cuando hay que satisfacer una cantidad líquida; procedimiento de las normas reguladoras de recaudación en vía ejecutiva. No se puede imponer obligación pecuniaria no establecida en norma con rango de ley.","note":"Apremio = DINERO (cantidad líquida) y por el procedimiento de RECAUDACIÓN.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Apremio sobre el patrimonio — Cuando hay que satisfacer una cantidad líquida; procedimiento de las normas reguladoras de recaudación en vía ejecutiva. No se puede imponer obligación pecuniaria no establecida en norma con rango de ley."},{"law":"lpac","art":"110","t":"Artículo 110. Límites de la revisión.","mat":"Límites de la revisión","cl":"No se ejercen cuando por prescripción, tiempo transcurrido u otras circunstancias sean contrarias a la equidad, buena fe, derecho de los particulares o leyes.","note":"Límites «E-BF-DP-L»: Equidad, Buena Fe, Derecho de los Particulares y Leyes.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Límites de la revisión — No se ejercen cuando por prescripción, tiempo transcurrido u otras circunstancias sean contrarias a la equidad, buena fe, derecho de los particulares o leyes."},{"law":"lpac","art":"131","t":"Artículo 131. Publicidad de las normas.","mat":"Publicidad de las normas","cl":"Las normas se publican en el diario oficial para entrar en vigor. La publicación en sede electrónica tiene los mismos efectos que la impresa en las condiciones que se determinen.","note":"Sin publicación en el DIARIO OFICIAL la norma no entra en vigor. El BOE electrónico es oficial y auténtico.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Publicidad de las normas — Las normas se publican en el diario oficial para entrar en vigor. La publicación en sede electrónica tiene los mismos efectos que la impresa en las condiciones que se determinen."},{"law":"lpac","art":"132","t":"Artículo 132. Planificación normativa.","mat":"Planificación normativa","cl":"Plan Normativo anual con las iniciativas del año siguiente; se publica en el Portal de la Transparencia.","note":"Plan Anual Normativo: cada año, para el AÑO SIGUIENTE, publicado en el Portal de TRANSPARENCIA.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Planificación normativa — Plan Normativo anual con las iniciativas del año siguiente; se publica en el Portal de la Transparencia."},{"law":"lrjsp","art":"4","t":"Artículo 4. Principios de intervención de las Administraciones Públicas para el desarrollo de una actividad.","mat":"Principios de intervención","cl":"Medidas que limiten derechos o exijan requisitos: proporcionalidad, medida menos restrictiva, motivar la necesidad, sin trato discriminatorio; evaluar periódicamente.","note":"Intervenir en una actividad: la medida MENOS restrictiva, motivada y proporcionada.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Principios de intervención — Medidas que limiten derechos o exijan requisitos: proporcionalidad, medida menos restrictiva, motivar la necesidad, sin trato discriminatorio; evaluar periódicamente."},{"law":"lrjsp","art":"14","t":"Artículo 14. Decisiones sobre competencia.","mat":"Decisiones sobre competencia","cl":"El órgano incompetente remite directamente las actuaciones al competente y lo notifica. Los interesados pueden pedir inhibición o requerimiento de inhibición. Conflictos de atribuciones: solo entre órganos de una misma Administración no relacionados jerárquicamente y en asuntos no finalizados.","note":"Incompetente: REMITE de oficio y AVISA a los interesados. Conflicto de atribuciones: misma Administración, SIN jerarquía entre ellos y asunto NO terminado.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Decisiones sobre competencia — El órgano incompetente remite directamente las actuaciones al competente y lo notifica. Los interesados pueden pedir inhibición o requerimiento de inhibición. Conflictos de atribuciones: solo entre órganos de una misma Administración no relacionados jerárquicamente y en asuntos no finalizados."},{"law":"lrjsp","art":"20","t":"Artículo 20. Requisitos para constituir órganos colegiados.","mat":"Requisitos de los colegiados en la AGE","cl":"Tres o más personas, creados formalmente, con funciones de decisión, propuesta, asesoramiento, seguimiento o control.","note":"Colegiado = 3 o más personas y creado FORMALMENTE.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Requisitos de los colegiados en la AGE — Tres o más personas, creados formalmente, con funciones de decisión, propuesta, asesoramiento, seguimiento o control."},{"law":"lrjsp","art":"35","t":"Artículo 35. Responsabilidad de Derecho Privado.","mat":"Responsabilidad de Derecho Privado","cl":"Cuando la Administración actúa en relaciones de Derecho privado, directamente o mediante entidad privada, la responsabilidad se exige conforme a los arts. 32 y siguientes.","note":"Aunque la Administración actúe como un particular, su responsabilidad se exige por la vía ADMINISTRATIVA (arts. 32 y ss.).","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Responsabilidad de Derecho Privado — Cuando la Administración actúa en relaciones de Derecho privado, directamente o mediante entidad privada, la responsabilidad se exige conforme a los arts. 32 y siguientes."},{"law":"lrjsp","art":"37","t":"Artículo 37. Responsabilidad penal.","mat":"Responsabilidad penal","cl":"Conforme a su legislación. No suspende los procedimientos de responsabilidad patrimonial salvo que la determinación de los hechos en vía penal sea necesaria.","note":"El proceso penal NO paraliza la responsabilidad patrimonial, salvo que los hechos dependan de lo que diga el juez penal.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Responsabilidad penal — Conforme a su legislación. No suspende los procedimientos de responsabilidad patrimonial salvo que la determinación de los hechos en vía penal sea necesaria."},{"law":"lrjsp","art":"40","t":"Artículo 40. Sistemas de identificación de las Administraciones Públicas.","mat":"Sistemas de identificación de las AAPP","cl":"Sello electrónico basado en certificado cualificado (con NIF y denominación); relación pública de sellos. Se entiende identificada respecto de la información de su portal.","note":"La Administración se identifica con SELLO electrónico; lo publicado como propio en su PORTAL se entiende suyo.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Sistemas de identificación de las AAPP — Sello electrónico basado en certificado cualificado (con NIF y denominación); relación pública de sellos. Se entiende identificada respecto de la información de su portal."},{"law":"lrjsp","art":"42","t":"Artículo 42. Sistemas de firma para la actuación administrativa automatizada.","mat":"Firma en la actuación automatizada","cl":"Sello electrónico de Administración, órgano u organismo, o código seguro de verificación (CSV) que permita comprobar la integridad en la sede.","note":"Actuación automatizada: firma con SELLO o con CSV (código seguro de verificación).","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Firma en la actuación automatizada — Sello electrónico de Administración, órgano u organismo, o código seguro de verificación (CSV) que permita comprobar la integridad en la sede."},{"law":"lrjsp","art":"48","t":"Artículo 48. Requisitos de validez y eficacia de los convenios.","mat":"Requisitos de los convenios","cl":"No ceden la titularidad de la competencia. Deben mejorar la eficiencia. Compromisos financieros sostenibles; aportaciones no superiores a los gastos. Se perfeccionan por el consentimiento; los de la AGE son eficaces tras inscribirse (5 días hábiles) en el registro estatal y se publican en el BOE (10 días hábiles).","note":"Convenio AGE «5-10»: inscripción en el registro estatal en 5 días HÁBILES (desde ahí es eficaz) y publicación en el BOE en 10 días HÁBILES. Se perfecciona con el CONSENTIMIENTO.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Requisitos de los convenios — No ceden la titularidad de la competencia. Deben mejorar la eficiencia. Compromisos financieros sostenibles; aportaciones no superiores a los gastos. Se perfeccionan por el consentimiento; los de la AGE son eficaces tras inscribirse (5 días hábiles) en el registro estatal y se publican en el BOE (10 días hábiles)."},{"law":"lrjsp","art":"50","t":"Artículo 50. Trámites preceptivos para la suscripción de convenios y sus efectos.","mat":"Trámites de los convenios","cl":"Memoria justificativa (necesidad, oportunidad, impacto económico, carácter no contractual). En la AGE: informe del servicio jurídico y autorización de Hacienda en 7 días hábiles.","note":"Siempre MEMORIA justificativa. En la AGE, informes y autorizaciones en 7 días HÁBILES.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Trámites de los convenios — Memoria justificativa (necesidad, oportunidad, impacto económico, carácter no contractual). En la AGE: informe del servicio jurídico y autorización de Hacienda en 7 días hábiles."},{"law":"lrjsp","art":"51","t":"Artículo 51. Extinción de los convenios.","mat":"Extinción de los convenios","cl":"Cumplimiento del objeto o resolución: transcurso del plazo sin prórroga, acuerdo unánime, incumplimiento previo requerimiento, decisión judicial de nulidad, otras causas.","note":"Resolución del convenio «PLA-U-IN-JU-O»: PLAzo sin prórroga · Unanimidad · INcumplimiento (tras requerimiento) · JUez (nulidad) · Otras.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Extinción de los convenios — Cumplimiento del objeto o resolución: transcurso del plazo sin prórroga, acuerdo unánime, incumplimiento previo requerimiento, decisión judicial de nulidad, otras causas."},{"law":"lrjsp","art":"82","t":"Artículo 82. El Inventario de Entidades del Sector Público Estatal, Autonómico y Local.","mat":"Inventario de Entidades del Sector Público","cl":"Registro público administrativo de todas las entidades del sector público institucional; lo gestiona la Intervención General de la Administración del Estado. Se inscriben creación, transformación, fusión o extinción.","note":"Inventario de Entidades = lo lleva la IGAE.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Inventario de Entidades del Sector Público — Registro público administrativo de todas las entidades del sector público institucional; lo gestiona la Intervención General de la Administración del Estado. Se inscriben creación, transformación, fusión o extinción."},{"law":"lrjsp","art":"89","t":"Artículo 89. Personalidad jurídica y potestades.","mat":"Organismos públicos: personalidad y potestades","cl":"Personalidad jurídica pública diferenciada, patrimonio y tesorería propios y autonomía de gestión; potestades administrativas salvo la expropiatoria.","note":"Organismo público: TODAS las potestades administrativas MENOS la EXPROPIATORIA.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Organismos públicos: personalidad y potestades — Personalidad jurídica pública diferenciada, patrimonio y tesorería propios y autonomía de gestión; potestades administrativas salvo la expropiatoria."},{"law":"lrjsp","art":"98","t":"Artículo 98. Definición.","mat":"Organismos autónomos","cl":"Entidades de derecho público con personalidad jurídica propia que desarrollan actividades propias de la Administración (fomento, prestacionales, gestión de servicios). Denominación «O.A.».","note":"Organismo autónomo = Derecho ADMINISTRATIVO, actividades propias de la Administración. Siglas «O.A.».","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Organismos autónomos — Entidades de derecho público con personalidad jurídica propia que desarrollan actividades propias de la Administración (fomento, prestacionales, gestión de servicios). Denominación «O.A.»."},{"law":"lrjsp","art":"103","t":"Artículo 103. Definición.","mat":"Entidades públicas empresariales","cl":"Entidades de Derecho público que se financian con ingresos de mercado y, junto a potestades administrativas, prestan servicios o producen bienes susceptibles de contraprestación. Denominación «E.P.E.».","note":"E.P.E. = se financia con ingresos de MERCADO; régimen mixto (derecho privado salvo en potestades administrativas).","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Entidades públicas empresariales — Entidades de Derecho público que se financian con ingresos de mercado y, junto a potestades administrativas, prestan servicios o producen bienes susceptibles de contraprestación. Denominación «E.P.E.»."},{"law":"lrjsp","art":"120","t":"Artículo 120. Régimen de adscripción.","mat":"Adscripción de los consorcios","cl":"Los estatutos fijan la Administración de adscripción según criterios por orden: mayoría de votos en órganos de gobierno, nombrar mayoría de órganos ejecutivos, personal directivo, mayor control por normativa especial, nombrar órgano de gobierno, financiación de más del 50%, fondo patrimonial, habitantes o extensión.","note":"Adscripción: el PRIMER criterio es la mayoría de VOTOS en los órganos de gobierno; después nombramientos y, más abajo, la financiación (>50%).","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Adscripción de los consorcios — Los estatutos fijan la Administración de adscripción según criterios por orden: mayoría de votos en órganos de gobierno, nombrar mayoría de órganos ejecutivos, personal directivo, mayor control por normativa especial, nombrar órgano de gobierno, financiación de más del 50%, fondo patrimonial, habitantes o extensión."},{"law":"lrjsp","art":"143","t":"Artículo 143. Cooperación entre Administraciones Públicas.","mat":"Cooperación entre Administraciones","cl":"Voluntaria; formalización con aceptación expresa en acuerdos de órganos de cooperación o convenios.","note":"Cooperar es VOLUNTARIO y requiere aceptación EXPRESA.","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Cooperación entre Administraciones — Voluntaria; formalización con aceptación expresa en acuerdos de órganos de cooperación o convenios."},{"law":"lrjsp","art":"145","t":"Artículo 145. Órganos de cooperación.","mat":"Órganos de cooperación","cl":"Composición multilateral o bilateral, de ámbito general o especial, para acordar voluntariamente actuaciones. Con la AGE: inscripción en el registro estatal para que valga la sesión constitutiva.","note":"Órganos de cooperación: multilaterales o bilaterales (Conferencia de Presidentes, Conferencias Sectoriales, Comisiones Bilaterales…).","n":0,"ex":0,"alc":0,"web":1,"w":3.0,"pr":"C","sub":"Órganos de cooperación — Composición multilateral o bilateral, de ámbito general o especial, para acordar voluntariamente actuaciones. Con la AGE: inscripción en el registro estatal para que valga la sesión constitutiva."}];
